def _rpc_update_project_meta(job_id: str, data: dict) -> bool:
    """Atualiza metadados editáveis (project_name/typology/address/phase) via
    RPC `update_project_meta`. Mesmo padrão da update_project_status.
    Retorna True só se rows_updated >= 1."""
    import urllib.request, urllib.error, json
    payload = {
        "p_job_id":       job_id,
        "p_project_name": data.get("project_name"),
        "p_typology":     data.get("typology"),
        "p_address":      data.get("address"),
        "p_phase":        data.get("phase"),
    }
    try:
        url = f"{SUPABASE_URL}/rest/v1/rpc/update_project_meta"
        body = json.dumps(payload).encode('utf-8')
        req = urllib.request.Request(url, data=body, method='POST')
        req.add_header('apikey', SUPABASE_KEY)
        req.add_header('Authorization', f'Bearer {SUPABASE_SERVICE_ROLE_KEY}')
        req.add_header('Content-Type', 'application/json')
        resp = urllib.request.urlopen(req, timeout=20)
        resp_body = resp.read().decode('utf-8', errors='replace')
        rows = 0
        try:
            rows = int(resp_body.strip())
        except (ValueError, TypeError):
            try:
                parsed = json.loads(resp_body)
                if isinstance(parsed, int):
                    rows = parsed
                elif isinstance(parsed, list) and parsed:
                    rows = int(parsed[0]) if isinstance(parsed[0], int) else 0
            except Exception:
                pass
        if rows >= 1:
            _supa_log(f"RPC update_project_meta job_id={job_id} OK rows={rows}  data={json.dumps(data)[:200]}")
            return True
        _supa_log(f"RPC update_project_meta job_id={job_id} ZERO_ROWS  data={json.dumps(data)[:200]}")
        return False
    except urllib.error.HTTPError as e:
        try:
            resp_body = e.read().decode('utf-8', errors='replace')[:500]
        except Exception:
            resp_body = '(unreadable)'
        _supa_log(f"RPC update_project_meta job_id={job_id} HTTP {e.code}: {resp_body}  data={json.dumps(data)[:200]}")
        return False
    except Exception as e:
        _supa_log(f"RPC update_project_meta job_id={job_id} ERR {type(e).__name__}: {e}  data={json.dumps(data)[:200]}")
        return False

# ═══════════════════════════════════════════════════════════════
#  Supabase Storage helpers (bucket aiarq-planilhas)
#  Persiste planilhas geradas pra sobreviverem a redeploys do Render.
# ═══════════════════════════════════════════════════════════════

PLANILHAS_BUCKET = "aiarq-planilhas"
PRANCHAS_BUCKET = "aiarq-pranchas"  # PDFs originais pra "abrir prancha" na revisão inline


def _supabase_storage_upload(local_path: str, remote_key: str) -> bool:
    """Faz upload de um arquivo pro Supabase Storage. Sobrescreve se existe."""
    import urllib.request, urllib.error
    try:
        with open(local_path, "rb") as f:
            body = f.read()
        url = f"{SUPABASE_URL}/storage/v1/object/{PLANILHAS_BUCKET}/{remote_key}"
        req = urllib.request.Request(url, data=body, method="POST")
        req.add_header("apikey", SUPABASE_KEY)
        req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        req.add_header("Content-Type",
                       "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
        req.add_header("x-upsert", "true")
        urllib.request.urlopen(req, timeout=30)
        _supa_log(f"STORAGE upload {remote_key} OK ({len(body)} bytes)")
        return True
    except urllib.error.HTTPError as e:
        try:
            resp_body = e.read().decode("utf-8", errors="replace")[:300]
        except Exception:
            resp_body = "(unreadable)"
        _supa_log(f"STORAGE upload {remote_key} HTTP {e.code}: {resp_body}")
        print(f"Storage upload {remote_key} HTTP {e.code}: {resp_body}")
        return False
    except Exception as e:
        _supa_log(f"STORAGE upload {remote_key} ERR {type(e).__name__}: {e}")
        print(f"Storage upload error: {e}")
        return False


_PRANCHA_MIME = {
    ".pdf": "application/pdf",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".dxf": "application/acad",
    ".dwg": "application/acad",
}


def _stem_da_prancha(nome: str) -> str:
    """O nome da prancha SEM extensão e SEM o sufixo do conversor.

    🩸 17/09/2026 — a miniatura da prancha NUNCA chegou na tela em 5 meses, e
    este era o SEGUNDO dos dois cortes. Quem batiza o PNG tira o `_libredwg`
    (sufixo que o conversor cola no DXF que ele mesmo gera), mas o `ref_sheet`
    que a tela manda de volta GUARDA o sufixo. Duas cópias da mesma receita
    divergindo por construção: `planta_libredwg.dxf` virava a imagem
    `planta.png`, e a busca ia procurar `planta_libredwg.png`, que não existe.

    📏 Medido antes de mexer: casando o nome CRU, **8 dos 56 PNGs** do balde
    são alcançáveis. Tirando o sufixo, **52 de 56** — 33 projetos, 19 clientes.
    Consertar um corte só entregaria 8; por isso os dois entraram no mesmo
    commit.

    🔑 Existe UMA função porque duas divergem — é a lição de
    [[feedback_a_receita_repetida_e_a_doenca]]. Quem grava o nome
    (`process_job`, no fim do preview) e quem procura (`_find_prancha_file`)
    chamam esta aqui, e o guarda prende justamente a igualdade entre as duas
    pontas, não a forma de cada uma.
    """
    base = os.path.splitext(os.path.basename(nome or ""))[0]
    if base.endswith("_libredwg"):
        base = base[: -len("_libredwg")]
    return base


def _sanitize_filename_for_storage(filename: str) -> str:
    """Remove acentos e caracteres especiais que quebram upload pro Supabase Storage.

    Bug detectado: PDF com nome 'Planta 1 - Galpão.pdf' dava HTTP 400 no upload
    mesmo com URL-encoding correto (Galp%C3%A3o). O Storage rejeita certos
    bytes UTF-8 multi-byte. Solução: ASCII-only filename pro storage.
    """
    import unicodedata
    # Decompõe acentos (ã = a + ̃) e remove os combinadores
    nfkd = unicodedata.normalize("NFKD", filename)
    ascii_only = "".join(c for c in nfkd if not unicodedata.combining(c))
    # Mantém só ASCII printáveis seguros pra URL
    safe = "".join(c if (c.isalnum() or c in " ._-()") else "_" for c in ascii_only)
    # Compacta múltiplos underscores
    while "__" in safe:
        safe = safe.replace("__", "_")
    return safe.strip("_ ") or "file"


def _safe_local_filename(filename: str) -> str:
    """Sanitiza filename pra uso em os.path.join local — anti-traversal.

    Aplica _sanitize_filename_for_storage E garante que o resultado:
    - É só basename (sem barras / nem backslashes)
    - Não é '.' nem '..' nem começa com '.'
    - Não é vazio (fallback 'upload')

    Use isso em TODO os.path.join(dir, filename) onde filename vem
    de UploadFile.filename. Sem isso, cliente manda '../../etc/passwd'
    e escreve fora do work_dir.
    """
    import os as _os
    if not filename:
        return "upload"
    # Pega só o último componente (cobre '/foo/bar' e '\\foo\\bar')
    base = _os.path.basename(filename.replace("\\", "/"))
    safe = _sanitize_filename_for_storage(base)
    # Rejeita resultados que ainda seriam traversal ou vazios
    if not safe or safe in (".", "..") or safe.startswith("."):
        return "upload"
    return safe


# Motivo da última falha de upload de prancha, pra sobreviver até o _log_error
# do chamador (ver docstring de _supabase_storage_upload_prancha).
#
# 🚨 17/09/2026 — a MESMA informação em dois alcances, e a duplicação é de
# propósito. Com um projeto por vez, o global bastava. Abrindo a 2ª vaga ele
# vira contaminação entre projetos (regra dura nº2): o projeto A falha, o
# projeto B sobe com sucesso e ZERA o global, e o `_log_error` de A vai dizer
# "não registrado"; pior, se os dois falharem, A grava no registro dele o
# motivo da falha DE OUTRO CLIENTE.
#   • `_FALHA_UPLOAD_DO_JOB` (ContextVar) é o que o MOTOR lê — cada job só
#     enxerga a própria falha, mesmo com dois no ar.
#   • o global continua porque a rota de diagnóstico do admin
#     (`/api/debug/storage-limit`) faz o upload num worker de threadpool e lê de
#     OUTRO contexto; trocar por ContextVar puro faria ela dizer "não
#     registrado" pra sempre, calada. 🪤 ali ainda é global de verdade — é
#     diagnóstico de admin com arquivo sintético, não dado de cliente.
_ULTIMA_FALHA_UPLOAD_PRANCHA = ""
_FALHA_UPLOAD_DO_JOB = contextvars.ContextVar("falha_upload_do_job", default="")


def _supabase_storage_upload_prancha(local_path: str, job_id: str, filename: str) -> bool:
    """Upload de prancha (PDF, PNG, JPG) pro bucket aiarq-pranchas.
    Key: {job_id}/{filename_sanitizado}. Content-Type derivado da extensão.

    Filename é sanitizado pra remover acentos/especiais — Supabase Storage
    rejeita certos UTF-8 multi-byte mesmo URL-encoded.

    🪤 Em falha, grava o MOTIVO e o TAMANHO em _ULTIMA_FALHA_UPLOAD_PRANCHA.
    Antes só devolvia False: o painel dizia "CAD não guardado" sem dizer por quê,
    e o motivo real (413? timeout? tamanho?) morria no log do Render. Caso Ana
    31/07: o DXF que MEDIU não foi guardado e não deu pra saber a causa."""
    import urllib.request, urllib.error
    global _ULTIMA_FALHA_UPLOAD_PRANCHA
    _tam_mb = 0.0
    try:
        _tam_mb = os.path.getsize(local_path) / 1048576.0
    except Exception:
        pass
    try:
        with open(local_path, "rb") as f:
            body = f.read()
        import urllib.parse as _up
        safe_name = _sanitize_filename_for_storage(filename)
        remote_key = f"{job_id}/{_up.quote(safe_name)}"
        url = f"{SUPABASE_URL}/storage/v1/object/{PRANCHAS_BUCKET}/{remote_key}"
        ext = os.path.splitext(safe_name.lower())[1]
        mime = _PRANCHA_MIME.get(ext, "application/octet-stream")
        req = urllib.request.Request(url, data=body, method="POST")
        req.add_header("apikey", SUPABASE_KEY)
        req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        req.add_header("Content-Type", mime)
        req.add_header("x-upsert", "true")
        # Timeout proporcional ao tamanho: 60s dava conta de PDF, mas DXF de
        # planta grande passa de 100 MB e estourava calado. ~2s por MB, teto 5min.
        _tmo = max(60, min(300, int(_tam_mb * 2)))
        urllib.request.urlopen(req, timeout=_tmo)
        if safe_name != filename:
            _supa_log(f"STORAGE upload prancha OK (saneado: '{filename}' → '{safe_name}')")
        _ULTIMA_FALHA_UPLOAD_PRANCHA = ""
        _FALHA_UPLOAD_DO_JOB.set("")
        return True
    except Exception as e:
        _detalhe = ""
        if isinstance(e, urllib.error.HTTPError):
            try:
                _corpo = e.read().decode("utf-8", "replace")[:200]
            except Exception:
                _corpo = ""
            _detalhe = f"HTTP {e.code} {_corpo}".strip()
        else:
            _detalhe = f"{type(e).__name__}: {e}"
        _ULTIMA_FALHA_UPLOAD_PRANCHA = f"{_detalhe} — arquivo de {_tam_mb:.1f} MB"
        _FALHA_UPLOAD_DO_JOB.set(_ULTIMA_FALHA_UPLOAD_PRANCHA)
        _supa_log(f"STORAGE upload prancha {filename} ERR {_ULTIMA_FALHA_UPLOAD_PRANCHA}")
        print(f"[storage pranchas] upload {filename} error: {_ULTIMA_FALHA_UPLOAD_PRANCHA}")
        return False


# Alias de compatibilidade com código antigo
_supabase_storage_upload_pdf = _supabase_storage_upload_prancha


def _supabase_storage_download_prancha(job_id: str, filename: str,
                                       tentativas: int = 3) -> Optional[bytes]:
    """Baixa prancha do Storage CONFERINDO o tamanho. Devolve bytes ou None.

    🩸 03/09/2026. Isto era `return resp.read()`, sem conferir NADA. `read()`
    numa conexão que fecha no meio devolve o pedaço que chegou **sem levantar
    exceção** — e o pedaço era gravado no disco como se fosse o arquivo do
    cliente.

    🪤 HONESTIDADE SOBRE A ORIGEM DESTE CONSERTO: eu cheguei aqui investigando
    o caso do job 75dab573), cujo ODA dizia "Unexpected end of
    file", e afirmei que a causa dele era esta. **Estava errado.** Com a
    conferência ligada, o arquivo dele baixa INTEIRO (nenhum
    `storage:download-truncado` no log) e o ODA do servidor falha do mesmo
    jeito — o que sobra lá é diferença entre o build Windows do ODA 27.1 (que
    converte) e o Linux QT6 27.1 do container (que recusa).

    🔑 O buraco daqui é real e continua valendo por si: um `read()` que não
    sabe dizer que leu menos do que devia, num caminho que roda em TODO filhote
    e em todo reprocesso. Falha silenciosa não produz erro — produz leitura
    PIOR, debitada do desenho do cliente ou do "não-determinismo da IA". Só não
    foi o que pegou o cliente-73.

    🔑 Isto roda em TODO filhote e em todo caminho que rebaixa o original. Um
    arquivo truncado não dá erro: dá uma leitura PIOR, que a gente ia debitar
    do motor ou do não-determinismo da IA.

    🪤 `Content-Length` é a única testemunha, e ela nem sempre vem (resposta em
    chunked). Quando não vier, não dá pra afirmar que veio inteiro — mas
    tampouco dá pra recusar; então segue e REGISTRA, que é diferente de calar.
    """
    import urllib.request, urllib.parse as _up
    remote_key = f"{job_id}/{_up.quote(filename)}"
    url = f"{SUPABASE_URL}/storage/v1/object/{PRANCHAS_BUCKET}/{remote_key}"
    _ultimo = None
    for _n in range(1, max(1, tentativas) + 1):
        try:
            req = urllib.request.Request(url, method="GET")
            req.add_header("apikey", SUPABASE_KEY)
            req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
            resp = urllib.request.urlopen(req, timeout=120)
            _esperado = resp.headers.get("Content-Length")
            data = resp.read()
            try:
                _esperado = int(_esperado) if _esperado is not None else None
            except (TypeError, ValueError):
                _esperado = None
            if _esperado is None:
                try:
                    _log_error("storage:download-sem-tamanho",
                               f"{filename}: servidor não mandou Content-Length "
                               f"({len(data)} bytes recebidos) — não dá pra "
                               f"provar que veio inteiro", job_id)
                except Exception:
                    pass
                return data
            if len(data) == _esperado:
                if _n > 1:
                    try:
                        _log_error("storage:download-truncado",
                                   f"{filename}: veio inteiro na tentativa {_n} "
                                   f"({_esperado} bytes)", job_id, severity="warning")
                    except Exception:
                        pass
                return data
            _ultimo = (f"recebi {len(data)} de {_esperado} bytes "
                       f"({100.0 * len(data) / max(1, _esperado):.1f}%)")
            print(f"[storage pranchas] {filename} TRUNCADO na tentativa {_n}: {_ultimo}")
        except Exception as e:
            _ultimo = f"{type(e).__name__}: {e}"
            print(f"[storage pranchas] download {filename} tentativa {_n}: {e}")
    try:
        _log_error("storage:download-truncado",
                   f"{filename}: NÃO consegui baixar inteiro em {tentativas} "
                   f"tentativas — {_ultimo}. Arquivo DESCARTADO em vez de "
                   f"processar um pedaço.", job_id, severity="critical")
    except Exception:
        pass
    return None


# Alias de compatibilidade
_supabase_storage_download_pdf = _supabase_storage_download_prancha


def _alerta_pranchas_perdidas(job_id, perdidos, total, onde):
    """Arquivo que não voltou do Storage NUNCA some calado. Devolve o aviso.

    🩸 04/09/2026, varredura adversarial. Ontem a função acima passou a
    DESCARTAR download truncado (`Content-Length` não bate) — conserto certo,
    metade feito. Os cinco laços que baixam do Storage tratam o `None` com um
    `continue` e só reclamam quando NÃO VEIO NADA (`if not file_paths`).
    Perder **1 de 9** seguia direto: o job rodava com menos pranchas e o
    cliente recebia `done` numa leitura incompleta.

    🔑 É o caso de **18/08** — um cliente perdeu 8 pranchas e recebeu `done` —
    voltando pela porta que a gente mesmo abriu. Detectar sem consequência não
    é conserto; é o defeito com um log a mais.

    🪤 Os dois piores dos cinco: `_retomar_job_do_storage`, que é a retomada
    automática depois de queda (justo quando o job já está fragilizado), e
    `add_file_and_reprocess`, que é o caminho em que o cliente manda o CAD que
    A GENTE PEDIU — perder arquivo ali é o pior lugar possível.

    🪤 Devolve a frase em vez de gravá-la: cada chamador pendura onde faz
    sentido (aviso do projeto, resposta da rota), e dois deles nem têm projeto
    ainda quando isto roda.
    """
    if not perdidos:
        return None
    _nomes = ", ".join(str(p) for p in perdidos)
    try:
        _log_error("storage:pranchas-perdidas",
                   "%s: %d de %d não voltaram do Storage: %s — a leitura "
                   "seguiria INCOMPLETA sem ninguém saber"
                   % (onde, len(perdidos), total, _nomes[:300]),
                   job_id, severity="critical")
    except Exception:
        pass
    return ("⚠ %d de %d arquivo(s) não puderam ser recuperados do nosso "
            "armazenamento nesta releitura (%s). O que saiu abaixo veio de uma "
            "leitura INCOMPLETA — reprocessar costuma resolver."
            % (len(perdidos), total, _nomes[:200]))


# ─── CHECKPOINT por prancha (19/07) ───────────────────────────────────
# A retomada pós-restart refazia o job INTEIRO do zero — num projeto de 22
# pranchas isso paga a IA de novo e reabre a janela pra outra queda. Agora o
# resultado da análise de cada prancha vira um JSON em
# {job_id}/checkpoint/{stem}.json no bucket de pranchas; na retomada, prancha
# com checkpoint NÃO chama a IA de novo. O filtro do _retomar (.pdf/.dwg/.dxf)
# ignora esses .json. Tudo best-effort: sem checkpoint = comportamento antigo.

def _ckpt_save(job_id: str, stem: str, result: dict) -> None:
    import urllib.request, urllib.parse as _up, json as _j
    try:
        stem = _sanitize_filename_for_storage(stem)  # acentos quebram o Storage
        body = _j.dumps(result, ensure_ascii=False, default=str).encode("utf-8")
        key = f"{job_id}/checkpoint/{_up.quote(stem)}.json"
        url = f"{SUPABASE_URL}/storage/v1/object/{PRANCHAS_BUCKET}/{key}"
        req = urllib.request.Request(url, data=body, method="POST")
        req.add_header("apikey", SUPABASE_KEY)
        req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        req.add_header("Content-Type", "application/json")
        req.add_header("x-upsert", "true")
        urllib.request.urlopen(req, timeout=30)
    except Exception as e:
        print(f"[ckpt] save {stem} falhou (segue sem): {e}")


def _ckpt_load_all(job_id: str) -> dict:
    """{stem: result} de todos os checkpoints do job. Vazio se não há."""
    import urllib.request, urllib.parse as _up, json as _j
    out = {}
    try:
        list_url = f"{SUPABASE_URL}/storage/v1/object/list/{PRANCHAS_BUCKET}"
        body = _j.dumps({"prefix": f"{job_id}/checkpoint/", "limit": 300}).encode("utf-8")
        req = urllib.request.Request(list_url, data=body, method="POST")
        req.add_header("apikey", SUPABASE_KEY)
        req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        req.add_header("Content-Type", "application/json")
        objs = _j.loads(urllib.request.urlopen(req, timeout=15).read().decode("utf-8"))
        for o in objs or []:
            name = o.get("name", "")
            if not name.endswith(".json"):
                continue
            try:
                url = (f"{SUPABASE_URL}/storage/v1/object/{PRANCHAS_BUCKET}/"
                       f"{job_id}/checkpoint/{_up.quote(name)}")
                r = urllib.request.Request(url, method="GET")
                r.add_header("apikey", SUPABASE_KEY)
                r.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
                data = _j.loads(urllib.request.urlopen(r, timeout=20).read().decode("utf-8"))
                out[_up.unquote(name[:-5])] = data
            except Exception:
                continue
    except Exception as e:
        print(f"[ckpt] load_all {job_id}: {e}")
    return out


def _ckpt_limpar(job_id: str) -> None:
    """Apaga os checkpoints do job (chamado no done — não precisam mais)."""
    import urllib.request, urllib.parse as _up, json as _j
    try:
        list_url = f"{SUPABASE_URL}/storage/v1/object/list/{PRANCHAS_BUCKET}"
        body = _j.dumps({"prefix": f"{job_id}/checkpoint/", "limit": 300}).encode("utf-8")
        req = urllib.request.Request(list_url, data=body, method="POST")
        req.add_header("apikey", SUPABASE_KEY)
        req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        req.add_header("Content-Type", "application/json")
        objs = _j.loads(urllib.request.urlopen(req, timeout=15).read().decode("utf-8"))
        for o in objs or []:
            name = o.get("name", "")
            if not name:
                continue
            try:
                url = (f"{SUPABASE_URL}/storage/v1/object/{PRANCHAS_BUCKET}/"
                       f"{job_id}/checkpoint/{_up.quote(name)}")
                r = urllib.request.Request(url, method="DELETE")
                r.add_header("apikey", SUPABASE_KEY)
                r.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
                urllib.request.urlopen(r, timeout=15)
            except Exception:
                continue
    except Exception:
        pass


def _supabase_storage_download(remote_key: str, local_path: str) -> bool:
    """Baixa arquivo do Supabase Storage pra path local. Cria diretório se preciso."""
    import urllib.request
    try:
        url = f"{SUPABASE_URL}/storage/v1/object/{PLANILHAS_BUCKET}/{remote_key}"
        req = urllib.request.Request(url, method="GET")
        req.add_header("apikey", SUPABASE_KEY)
        req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        resp = urllib.request.urlopen(req, timeout=30)
        os.makedirs(os.path.dirname(local_path), exist_ok=True)
        with open(local_path, "wb") as f:
            f.write(resp.read())
        return True
    except Exception as e:
        print(f"Storage download error ({remote_key}): {e}")
        return False


def get_planilha_path(job_id: str) -> Optional[str]:
    """Retorna o path local da planilha de um job. Se sumiu (Render
    /tmp volátil), tenta baixar do Supabase Storage. None se falhou."""
    local = os.path.join(WORK_DIR, job_id, f"orcamento_{job_id}.xlsx")
    if os.path.exists(local):
        return local
    if _supabase_storage_download(f"{job_id}.xlsx", local):
        return local
    return None


