async def _stream_upload_to_disk(upload_file, file_path, *, head_bytes=16, chunk=1024 * 1024):
    """Grava o upload em disco em pedaços, SEM bufferizar o arquivo inteiro na RAM.

    Motivo (anti-OOM): `await upload_file.read()` (sem argumento) puxa o arquivo
    todo pra memória de uma vez — um DXF de 300 MB dava um pico de 300 MB, e em
    cima do resto isso estourava a RAM do Render e reiniciava o serviço pra todos.
    O parser multipart do Starlette já derrama uploads grandes num arquivo temp em
    disco; o vilão era só o `.read()`. Lendo em pedaços de 1 MB, o pico de RAM do
    upload fica em ~1 MB, independente do tamanho do arquivo.

    Retorna (bytes_gravados, head): `head` são os primeiros bytes, pra checagem de
    assinatura (ex.: 'AC' do DWG) sem precisar reabrir o arquivo.
    """
    try:
        await upload_file.seek(0)
    except Exception:
        pass
    total = 0
    head = b""
    try:
        with open(file_path, "wb") as out:
            while True:
                buf = await upload_file.read(chunk)
                if not buf:
                    break
                if len(head) < head_bytes:
                    head += buf[: head_bytes - len(head)]
                out.write(buf)
                total += len(buf)
    except OSError as e:
        # Disco cheio / IOError no meio da gravação: apaga o parcial e devolve
        # erro claro (senão o FastAPI daria 500 mudo e o arquivo meio-escrito
        # ficaria no work_dir). Ambos os chamadores herdam esse tratamento.
        try: os.remove(file_path)
        except OSError: pass
        raise HTTPException(507, "Não consegui salvar o arquivo no servidor "
                            "(sem espaço em disco no momento). Tente de novo em instantes.") from e
    return total, head



def _formato_cad_pelo_conteudo(path: str) -> Optional[str]:
    """'dwg', 'dxf' ou None — pelo CONTEÚDO do arquivo, não pelo nome.

    🩸 05/09/2026, caso cliente-39 (job 8b7a2b71, engenheiro de orçamento vindo
    do Google): mandou HNSC-...-A01-R02.dxf de 5,4 MB. O arquivo começa com
    `AC1024` — é um DWG do AutoCAD 2010 com a extensão trocada. A gente
    decidia o caminho só pelo nome, jogou o DWG no leitor de DXF, e ele morreu
    com "is not a DXF file"; o cliente leu que o arquivo "foi lido, mas não
    rendeu nenhum item — pode ser prancha só de layout". Nada disso era
    verdade. Primeira ocorrência em 120 dias — e caiu no lead que fez tudo
    certo. Reproduzido localmente com um DWG de teste renomeado: mesmos erros.
    🪤 O upload já lia os primeiros bytes pra RECUSAR .dwg sem `AC10xx`;
    faltava o espelho (.dxf que é DWG). Aqui é o lugar que vale pra todo
    caminho — upload, reprocesso, add-file e filhote passam pelo process_job.
    """
    try:
        with open(path, "rb") as _f:
            head = _f.read(64)
    except OSError:
        return None
    import re as _re_ext
    if _re_ext.match(rb"AC1\d{3}", head):
        return "dwg"
    if head.startswith(b"AutoCAD Binary DXF"):
        return "dxf"
    _t = head.lstrip(b"\xef\xbb\xbf \t\r\n")
    if _re_ext.match(rb"(0|999)\r?\n", _t):
        return "dxf"
    return None


def _aviso_complemento_sem_itens(lidos, falhas_leitura):
    """Texto do aviso quando um COMPLEMENTO (/add-file) termina com 0 itens e a
    planilha anterior é mantida. Três situações, três verdades diferentes:
      • nada entrou na leitura (lista vazia) — 05/09, cliente-39, 19:24: as duas
        regras do anexo se anularam, e o aviso dizia "foi lido" com o nome
        virando "o arquivo";
      • entrou, mas a leitura FALHOU (dxf_errors/sheet_errors) — "não consegui ler";
      • entrou, foi lido e não rendeu item — só aqui cabe "foi lido, mas não rendeu".
    🚫 Nunca chutar causa ("prancha só de layout", "PDF escaneado") pra falha que
    a gente não viu — é o mesmo defeito do "não consegui medir" de 03/09.
    Regra nº7 de texto: o aviso é acessório; sempre diz que nada foi perdido."""
    nomes = ", ".join(os.path.basename(str(p)) for p in (lidos or []) if p)
    if not nomes:
        return ("Nenhum arquivo novo entrou nesta leitura — o que você anexou repetia um "
                "arquivo que o projeto já tinha (mesmo conteúdo, com outro nome). Sua "
                "planilha anterior foi mantida — nada foi perdido. Se a intenção era mandar "
                "outra prancha, confira o arquivo e anexe de novo.")
    if falhas_leitura:
        return (f"Não consegui ler o arquivo que você anexou ({nomes}). Sua planilha "
                f"anterior foi mantida — nada foi perdido. O detalhe está no diagnóstico do "
                f"projeto; na maioria das vezes resolve salvar como DXF (versão 2013) e "
                f"anexar de novo.")
    return (f"O arquivo que você anexou ({nomes}) foi lido, mas não rendeu nenhum item "
            f"quantificável. Sua planilha anterior foi mantida — nada foi perdido. Isso "
            f"acontece com prancha só de layout (sem quadros nem legendas) ou PDF "
            f"escaneado; pra medir pelo CAD, anexe o DWG/DXF da planta arquitetônica.")


def _aviso_lineares_zerados(n, tem_cad):
    """Aviso de itens em METRO sem quantidade. Com CAD no envio NÃO diz "mande o
    DXF" (a pessoa já mandou) nem fala de "comprimento tirado de PDF" — 05/09,
    Pedro: os dois textos errados pro cliente. O que é verdade nos dois casos:
    a gente não publica estimativa visual como metro."""
    if tem_cad:
        return ("⚠ %d item(ns) em METRO ficaram sem quantidade. Seu CAD entrou na medição, "
                "mas o comprimento dessas linhas (rodapé, soleira, tubulação) não saiu da "
                "geometria — só de estimativa visual, e a gente não publica estimativa como "
                "número. Preencha esses metros na revisão." % n)
    return ("⚠ %d item(ns) em METRO ficaram sem quantidade. Nós medimos a geometria das "
            "suas pranchas, mas comprimento tirado de PDF não é confiável o bastante pra "
            "virar número na sua planilha — rodapé, soleira e tubulação dependem do percurso "
            "real, não do total de parede. Preencha esses metros ou mande o DXF que a gente "
            "mede." % n)


def _escolher_cads_do_anexo(cads, job_id: str):
    """Quais CADs do anexo (/add-file) entram no reprocesso — pelo CONTEÚDO
    primeiro, pelo nome depois. Devolve (cads_escolhidos, avisos_pro_cliente).

    🩸 05/09/2026, cliente-39, 3º anexo do dia (19:24). O anexo tinha a regra
    "DXF vence o DWG do mesmo nome", julgada pelo NOME: um .dxf que era DWG
    renomeado "venceu" o .dwg de verdade e o jogou fora. Em seguida, no
    process_job, a checagem pelo conteúdo viu que o "DXF" era DWG com o irmão
    .dwg no disco e descartou a cópia. Sobrou ZERO arquivo — zero item em
    0,3 s, sem erro, sem e-mail, e um aviso na tela dizendo que o arquivo
    dele "não rendeu nenhum item". Duas regras certas, na ordem errada.

    🔑 A ordem é a regra: primeiro o conteúdo (`_normalizar_extensao_cad`
    renomeia o DWG disfarçado, ou descarta a cópia se o .dwg real já está no
    envio); só então "DXF vence DWG do mesmo nome" enxerga DXF de verdade
    (caso forro MEP do Pedro, 15/07 — DWG AEC não abre, o DXF re-exportado sim).
    """
    if not cads:
        return [], []
    cads, avisos, _ = _normalizar_extensao_cad(list(cads), job_id)
    dxf_stems = {os.path.splitext(os.path.basename(p))[0].lower()
                 for p in cads if p.lower().endswith(".dxf")}
    cads = [p for p in cads
            if not (p.lower().endswith(".dwg")
                    and os.path.splitext(os.path.basename(p))[0].lower() in dxf_stems)]
    return cads, avisos


def _normalizar_extensao_cad(cad_paths, job_id: str):
    """Renomeia NO DISCO o CAD cujo nome mente sobre o conteúdo.

    Devolve (caminhos_corrigidos, avisos_pro_cliente, mapa) — `mapa` é
    {caminho_antigo: caminho_novo ou None se descartado}, pra quem guarda
    listas paralelas (file_paths, tipos por prancha) acompanhar a troca.
    O Storage guarda o nome que o cliente deu; só a cópia local ganha a
    extensão verdadeira — por isso o reprocesso e o filhote, que baixam do
    Storage, passam por aqui de novo.

    Colisão (x.dwg real + x.dxf que é o MESMO DWG renomeado — foi exatamente
    o 2º envio do cliente-39, que anexou o .dwg de verdade depois): a cópia
    renomeada é descartada, não processada duas vezes — duplicar prancha
    dobraria as quantidades, que é pior que perder a cópia. E a regra
    "DXF supera DWG do mesmo nome" logo abaixo deixa de apagar o DWG bom por
    causa de um .dxf que nem era DXF.
    """
    novos, avisos, mapa = [], [], {}
    for p in cad_paths:
        ext = p.lower().rsplit(".", 1)[-1]
        real = _formato_cad_pelo_conteudo(p)
        if not real or real == ext:
            novos.append(p)
            continue
        bn = os.path.basename(p)
        alvo = p[: -len(ext)] + real
        if os.path.exists(alvo):
            try:
                _log_error("motor:extensao-corrigida",
                           f"{bn}: nome diz .{ext}, conteúdo é {real.upper()} — e "
                           f"{os.path.basename(alvo)} já está no envio: descartei a "
                           f"cópia renomeada pra não medir a prancha duas vezes",
                           job_id, severity="warning")
            except Exception:
                pass
            mapa[p] = None
            continue
        try:
            os.replace(p, alvo)
        except OSError as _e_ren:
            try:
                _log_error("motor:extensao-corrigida",
                           f"{bn}: conteúdo é {real.upper()} mas não consegui "
                           f"renomear ({_e_ren}) — segue com o nome original",
                           job_id, severity="warning")
            except Exception:
                pass
            novos.append(p)
            continue
        mapa[p] = alvo
        try:
            _log_error("motor:extensao-corrigida",
                       f"{bn}: nome diz .{ext}, conteúdo é {real.upper()} → tratado "
                       f"como {real.upper()} ({os.path.basename(alvo)})",
                       job_id, severity="warning")
        except Exception:
            pass
        avisos.append(
            f"O arquivo {bn} veio com a extensão .{ext}, mas o conteúdo é um "
            f"{real.upper()}. Tratamos como {real.upper()} — não é defeito do "
            f"arquivo, só o nome. Pra a próxima: o DXF sai do AutoCAD por "
            f"SALVAR COMO → tipo \"DXF 2013\"; renomear o .dwg não converte.")
        novos.append(alvo)
    return novos, avisos, mapa


def _saida_do_filho_pdfvec(rc, vm) -> tuple:
    """Classifica a saída do filho da medição de PDF que hoje termina MUDA.

    Devolve (tipo, detalhe): tipo é "memoria", "sem_escala" ou None.

    🔬 05/09/2026 (estudo do teto, passo 6 + o que a A08 do cliente-39 custou):
    - "memoria": rc=0 mas alguma etapa engoliu um MemoryError (o try/except por
      etapa segura a falha quando ela cai em Python/GEOS — medido: FORRO com
      teto de 1,5 GB devolveu rc=0 e JSON parcial com err_views/err_rooms
      'MemoryError'). Saía como "sucesso" parcial e o cliente NÃO era avisado —
      o oposto do que o comentário do teto prometia.
    - "sem_escala": rc=0 e o filho pulou por falta de escala (viewport, carimbo,
      cota). Não deixava NENHUMA linha na promoção — só a sombra anotava. Duas
      tentativas na A08 do cliente-39 pra descobrir que era o cache do carimbo.
    Só classifica; quem grava e avisa é o chamador.
    """
    if rc != 0 or not isinstance(vm, dict) or not vm:
        return None, ""
    # 🩸 10/09/2026: a falta de memória também chega como GEOSException
    # ("bad allocation" / "std::bad_alloc") de dentro do shapely. Reconhecer
    # mora em `filho_protegido.e_falta_de_memoria` — os handlers da geometria
    # usam a MESMA decisão.
    import filho_protegido as _fpm
    errs_mem = {k: str(v)[:80] for k, v in vm.items()
                if k.startswith("err_") and _fpm.e_falta_de_memoria(str(v))}
    if errs_mem:
        return "memoria", "; ".join(f"{k}={v}" for k, v in sorted(errs_mem.items()))
    if vm.get("skip"):
        carimbo = (vm.get("err_carimbo")
                   or ("indicadas" if vm.get("indicadas") else None)
                   or (vm.get("declared") or None) or "-")
        cotas = vm.get("cotas_derivacao") or vm.get("err_cotas_derive") or "-"
        viewport = vm.get("err_viewport") or vm.get("n_viewports") or "-"
        # 🩸 10/09/2026: o que a busca da escala AO LADO DA VISTA achou. Vem
        # ANTES das cotas, que são longas: se a linha for cortada, o rastro
        # fica. A forma curta mora em `pdf_vector.rastro_da_escala_por_vista`.
        try:
            from pdf_vector import rastro_da_escala_por_vista
            _pv = rastro_da_escala_por_vista(vm)
        except Exception:
            _pv = {"erro": "rastro indisponível"}
        if not _pv:
            vista = "-"
        else:
            vista = "n=%s lidas=%s" % (_pv.get("n"), _pv.get("lidas"))
            if _pv.get("erro"):
                vista += " erro=%s" % _pv["erro"]
        return "sem_escala", (f"{vm.get('skip')} — viewport={viewport} carimbo={carimbo} "
                              f"vista={vista} cotas={cotas} secs={vm.get('secs')}")
    return None, ""


def _linha_pdfvec_memoria(pranchas, teto: int = 1900) -> str:
    """Monta a linha `pdfvec:memoria`: quanto de memória cada medição de PDF gastou.

    🩸 10/09/2026 — DOIS FUROS NO INSTRUMENTO DO TETO, achados pela revisão de
    10 agentes sobre as pranchas que o filho da promoção perde:

    1. As 6 pranchas eram escolhidas por ÁREA medida (herdavam a ordem do
       `pdfvec:por-prancha`). A mais PESADA quase nunca é a de maior área: no
       job aec7cac2 a única prancha com MemoryError ficou FORA da linha. Um
       instrumento de memória que pulava justo a prancha que estourou a memória.
    2. `mem_etapas` — a memória POR ETAPA — era medida pelo filho, guardada no
       índice por prancha e jogada fora aqui. Sem ela não dá pra dizer EM QUE
       ETAPA o endereço sobe, que é a pergunta de qualquer mexida no teto.

    🔑 Escolhe por VmPeak (a régua do RLIMIT_AS) e acrescenta
    `pico={etapa:VmPeak/VmSize}` em MiB, depois de `etapas={...}`.

    🪤 O prefixo `VmPeak=..MB VmHWM=..MB ini_VmSize=..MB secs=..` fica IDÊNTICO e
    na MESMA ordem: a consulta que deu o p95 do teto casa esse texto por regex.
    Campo novo só entra no FIM da linha de cada prancha.
    🪤 Checkpoint salvo antes deste deploy traz `mem_etapas` com 2 números
    [VmRSS, VmHWM]: essa prancha sai sem `pico=`, sem quebrar a linha.
    🪤 Cabe por construção no corte de 2.000 do `_log_error`: passando do `teto`,
    sai primeiro o `pico=` das pranchas mais LEVES; depois as próprias pranchas
    mais leves, declaradas em `(+N fora)`. Corte calado lê como "foi tudo".
    """
    def _mb(d, k):
        try:
            return int((d or {}).get(k) or 0) // 1024
        except (TypeError, ValueError, AttributeError):
            return 0

    def _pico_kb(r):
        try:
            return int((r.get("mem_kb") or {}).get("VmPeak") or 0)
        except (TypeError, ValueError, AttributeError):
            return 0

    def _pico_por_etapa(r):
        partes = []
        for et, v in (r.get("mem_etapas") or {}).items():
            if not isinstance(v, (list, tuple)) or len(v) < 4:
                continue        # checkpoint antigo: só [VmRSS, VmHWM]
            try:
                partes.append("%s:%d/%d" % (str(et)[:5], int(v[3] or 0) // 1024,
                                            int(v[2] or 0) // 1024))
            except (TypeError, ValueError):
                continue
        return ",".join(partes)

    def _linha(r, com_pico):
        _mk, _mi = r.get("mem_kb") or {}, r.get("mem_kb_inicio") or {}
        _et = r.get("etapas") or {}
        try:
            _secs = float(r.get("secs") or 0)
        except (TypeError, ValueError):
            _secs = 0.0
        linha = ("%s p%s: VmPeak=%dMB VmHWM=%dMB ini_VmSize=%dMB secs=%.0f etapas={%s}"
                 % (str(r.get("arquivo") or "")[:24], r.get("pagina"),
                    _mb(_mk, "VmPeak"), _mb(_mk, "VmHWM"), _mb(_mi, "VmSize"), _secs,
                    ",".join("%s:%s" % (str(k)[:5], v) for k, v in _et.items())))
        if com_pico:
            _p = _pico_por_etapa(r)
            if _p:
                linha += " pico={%s}" % _p
        return linha

    todas = sorted((r for r in (pranchas or [])
                    if isinstance(r, dict) and r.get("mem_kb")),
                   key=_pico_kb, reverse=True)
    escolhidas = todas[:6]
    com_pico = [True] * len(escolhidas)
    n = len(escolhidas)

    def _monta():
        s = " | ".join(_linha(r, com_pico[i]) for i, r in enumerate(escolhidas[:n]))
        if s and len(todas) > n:
            s += " | (+%d fora)" % (len(todas) - n)
        return s

    s = _monta()
    i = len(escolhidas) - 1
    while len(s) > teto and i >= 0:
        com_pico[i] = False
        i -= 1
        s = _monta()
    while len(s) > teto and n > 1:
        n -= 1
        s = _monta()
    return s


#: Fração do teto de endereço do filho a partir da qual a prancha é anotada
#: como "perto do teto". Com o teto de 2e9 bytes (1.907 MiB), 90% = 1.716 MiB.
_FRACAO_PERTO_DO_TETO = 0.9


def _pranchas_perto_do_teto(pranchas, teto_bytes=None,
                            fracao: float = _FRACAO_PERTO_DO_TETO) -> list:
    """Pranchas medidas cujo pico de endereço passou de `fracao` do teto do filho.

    🩸 10/09/2026 — o sinal que substitui o das camadas. O passo de camadas era
    o único que acusava falta de memória (o único MemoryError desde 02/09 foi
    lá) e saiu da promoção. Sem outro sinal, prancha rodando no limite ficaria
    invisível — e é sob pressão de memória que a geometria errava calada.

    🔑 Só observação: grava log, não muda planilha nem aviso. A régua é o
    VmPeak que o próprio filho devolve, a mesma que o RLIMIT_AS cobra, e o teto
    vem de `filho_protegido.RLIMIT_BYTES` — número escrito em dois lugares é
    como os dois lados divergem.
    Devolve [(rotulo, vmpeak_mib)], do maior pico pro menor.
    """
    if teto_bytes is None:
        import filho_protegido
        teto_bytes = filho_protegido.RLIMIT_BYTES
    limite_kb = int(teto_bytes * fracao) // 1024
    achadas = []
    for r in pranchas or []:
        if not isinstance(r, dict):
            continue
        try:
            pico_kb = int((r.get("mem_kb") or {}).get("VmPeak") or 0)
        except (TypeError, ValueError, AttributeError):
            continue
        if pico_kb and pico_kb >= limite_kb:
            rotulo = "%s p%s" % (str(r.get("arquivo") or "?")[:24], r.get("pagina"))
            achadas.append((rotulo, pico_kb // 1024))
    return sorted(achadas, key=lambda x: -x[1])


def _linha_perto_do_teto(perto, teto_bytes=None) -> str:
    """A mensagem do log `pdfvec:perto-do-teto`."""
    if teto_bytes is None:
        import filho_protegido
        teto_bytes = filho_protegido.RLIMIT_BYTES
    return ("%d prancha(s) acima de %d%% do teto de endereço do filho (%d MiB): %s"
            % (len(perto), int(_FRACAO_PERTO_DO_TETO * 100), teto_bytes // 1048576,
               "; ".join("%s=%dMB" % p for p in list(perto)[:6])))


#: Motivos de falha da medição de PDF que viram aviso pro cliente. Motivo fora
#: daqui (nome de exceção do pai, diagnóstico interno) não é texto pra quem lê a
#: planilha — é log.
# 🩸 14/09/2026 — o motivo NOVO. Até hoje o aviso só falava de falha
# TÉCNICA nossa (tempo, processo morto, memória). A folha barrada por
# escala adivinhada saía igual a "não tinha o que medir" — que é
# exatamente a confusão que este aviso existe pra desfazer, e a mesma
# família do zerar CALADO que o passo 1 consertou na planilha.
_MOTIVOS_DO_AVISO_PDFVEC = ("tempo", "processo", "memoria", "escala-adivinhada")


def _avisos_da_medicao_pdfvec(falhas, por_prancha=None) -> tuple:
    """Transforma as falhas da medição de PDF nos avisos que o cliente lê.

    Devolve (avisos, mensagem_de_log). Nada a avisar → ([], "").

    🩸 31/08/2026 (caso cliente-14): 2 de 16 pranchas estouraram o tempo da
    medição geométrica e a planilha não distinguia "não tinha o que medir" de
    "não deu tempo de medir". Daí nasceu o aviso — e a mesma auditoria pôs no
    aviso também a prancha cujo PROCESSO morreu. 05/09: "memoria" ganhou frase
    própria ('densa demais' não é 'não havia o que medir').

    🩸 10/09/2026 — O AVISO CONTAVA ARQUIVO E CHAMAVA DE PRANCHA. Job aec7cac2,
    um caderno único de 30+ páginas: a p11 estourou o tempo, a p28 abortou e a
    p27 FOI MEDIDA (entrou no prompt e no índice) com um MemoryError numa etapa
    posterior. O cliente leu "1 prancha(s) são densas demais (faltou memória)":
    errou a conta, errou o motivo das outras duas e chamou de não medida a
    página medida. 📏 Medido desde 02/09: foi o único dos 7 avisos com a conta
    errada — os outros eram PDFs de uma página, onde arquivo e página coincidem.

    🔑 Três regras:
    - conta PÁGINAS (a chave é a prancha, `<arquivo>_p<N>`) e nomeia
      "<arquivo> pág. N", com N a partir de 1;
    - a frase de memória só quando TODAS as páginas do grupo foram memória;
      motivos misturados → "não puderam ser medidas", que é verdade pros três;
    - página que está no índice por prancha FOI medida: sai num aviso próprio
      que só afirma o que é verdade por construção — a medição não terminou
      todas as etapas, o que foi medido serviu de base pra leitura, e item de
      PDF sai como estimativa (`_pdf_downgrade` rebaixa todo 'confirmado').
    🚫 Nunca dizer que a medição "entrou na planilha": parede medida não vira
    linha linear sozinha (a planilha zera com "Comprimento NÃO medido").
    """
    por_prancha = por_prancha or {}
    paginas = {}
    for f in falhas or []:
        if not isinstance(f, dict) or f.get("motivo") not in _MOTIVOS_DO_AVISO_PDFVEC:
            continue
        chave = f.get("prancha") or "%s_p%s" % (f.get("arquivo"), f.get("pagina"))
        paginas.setdefault(chave, []).append(f)
    if not paginas:
        return [], ""

    def _rotulo(f):
        arq = str(f.get("arquivo") or "?")
        try:
            return "%s pág. %d" % (arq, int(f.get("pagina")) + 1)
        except (TypeError, ValueError):
            return arq

    def _lista(grupo):
        rotulos = sorted({_rotulo(fs[0]) for fs in grupo})
        return ", ".join(rotulos[:3]) + ("" if len(rotulos) <= 3 else " e outras")

    nao_medidas = [fs for ch, fs in paginas.items() if ch not in por_prancha]
    em_parte = [fs for ch, fs in paginas.items() if ch in por_prancha]
    avisos, log = [], []
    if nao_medidas:
        motivos = {f.get("motivo") for fs in nao_medidas for f in fs}
        if motivos == {"tempo"}:
            porque = "não deram tempo de ser medidas geometricamente"
        elif motivos == {"memoria"}:
            porque = ("são densas demais para a nossa medição geométrica "
                      "(faltou memória — limite nosso, não defeito do arquivo)")
        elif motivos == {"escala-adivinhada"}:
            # 🪤 Frase PRÓPRIA de propósito: as outras três dizem "não deu" —
            # esta diz "deu, e a gente recusou". A diferença importa pro cliente:
            # a saída dele é escrever a escala na prancha (ou mandar o CAD), não
            # esperar a gente melhorar.
            porque = ("não dizem a escala em lugar nenhum, e a escala que daria "
                      "pra deduzir das cotas não se confirmou — preferimos não "
                      "medir a entregar número adivinhado")
        else:
            porque = "não puderam ser medidas geometricamente"
        avisos.append(
            "⚠ %d prancha(s) %s (%s). Elas foram lidas assim mesmo, mas os itens "
            "delas saem como estimativa — confira essas contra o projeto antes de "
            "fechar orçamento." % (len(nao_medidas), porque, _lista(nao_medidas)))
        log.append("%d prancha(s) sem medição (%s): %s" % (
            len(nao_medidas), ",".join(sorted(str(m) for m in motivos)),
            _lista(nao_medidas)))
    if em_parte:
        motivos_p = {f.get("motivo") for fs in em_parte for f in fs}
        avisos.append(
            "⚠ %d prancha(s) foram medidas, mas a medição geométrica não terminou "
            "todas as etapas (%s). O que chegou a ser medido serviu de base para a "
            "leitura, e os itens delas saem como estimativa — confira essas contra o "
            "projeto antes de fechar orçamento." % (len(em_parte), _lista(em_parte)))
        log.append("%d medida(s) só em parte (%s): %s" % (
            len(em_parte), ",".join(sorted(str(m) for m in motivos_p)),
            _lista(em_parte)))
    return avisos, " | ".join(log)


_RX_ESTRUT_NOME = None
_RX_NEGACAO_ANTES = None


def _nome_parece_estrutural(nome: str) -> bool:
    """O nome do arquivo tem cara de projeto ESTRUTURAL — e NÃO está negado.

    🩸 02/09/2026, primeira cliente do dia (cliente-27, TEKOA): mandou
    "..._EXE_REV01_SEM ESTRUTURAL.pdf" e recebeu no envio o aviso "esses
    arquivos parecem de projeto ESTRUTURAL". O regex achava `estrut` e não lia
    o "SEM" na frente. Medido: foi a ÚNICA vez que esse aviso disparou desde
    que existe (01/08) — e disparou errado. Aviso falso na primeira tela que
    a pessoa vê é o pior lugar pra errar.

    🔑 A regra continua a mesma (palavra estrutural no nome); só não dispara
    quando a palavra vem logo depois de uma NEGAÇÃO: "sem", "s/", "não/nao",
    "exceto", "menos". Fronteira de palavra no "sem" pra "SEMANA.pdf" não
    virar negação.
    """
    global _RX_ESTRUT_NOME, _RX_NEGACAO_ANTES
    import re as _re
    if _RX_ESTRUT_NOME is None:
        # 🩸 03/09/2026 — SEGUNDA VEZ QUE ESTE AVISO DISPARA, E A SEGUNDA
        # ERRADA. Cliente `cliente-11@` mandou
        # "CIQUANTA-CABEAMENTO ESTRUTURADO.dwg" e foi avisado de que parecia
        # projeto estrutural. Cabeamento ESTRUTURADO é rede de dados; o pedaço
        # solto `estrut` casava com "estruturado".
        # Rodando a versão antiga contra nomes plausíveis, mais dois:
        #     NAVIGATION-PLAN.dwg  → "viga" dentro de naVIGAtion
        #     LAJEADO-CENTRO.dwg   → "laje" dentro de Lajeado (cidade)
        # 🔑 O placar deste aviso na vida inteira: 2 disparos, 2 errados. Aviso
        # que só erra treina o cliente a ignorar TODOS os nossos avisos — o
        # custo não fica no aviso falso, fica nos verdadeiros.
        # 🪤 Fronteira dos DOIS lados. `estrutura|estrutural|estruturas|
        # estruturais` valem; `estruturado` não. Nas palavras curtas a
        # fronteira à direita é a que importa (laje/lajeado); em `viga` é a da
        # esquerda (navigation).
        _RX_ESTRUT_NOME = _re.compile(
            # 🪤 "ESTRUT_TERREO.pdf" é abreviação legítima e comum, e um
            # guarda que já existia pegou ela caindo quando eu apertei
            # demais. Então: a palavra inteira OU a abreviação — as duas
            # com fronteira à direita, que é o que exclui "estruturado".
            r"(?<![a-zà-ü])estrutur(?:a|al|as|ais)(?![a-zà-ü])"
            r"|(?<![a-zà-ü])estrut(?![a-zà-ü])"
            r"|(?<![a-zà-ü])f[oô]rmas?(?![a-zà-ü])"
            r"|(?<![a-zà-ü])funda[cç]"
            # 🩸 03/09, 2ª mordida do mesmo conserto: `arma[cç][aã]o` não pega
            # o PLURAL ("ARMAÇÕES", "ARMACOES"). Achado por revisão adversarial
            # do meu próprio commit, horas depois.
            r"|(?<![a-zà-ü])arma[cç](?:[ãa]o|[õo]es)(?![a-zà-ü])"
            # 🩸 `pilares?` significa "pilare" + s OPCIONAL — nunca casa PILAR
            # no singular. Apertando o regex pra tirar dois falsos positivos eu
            # DESLIGUEI uma detecção verdadeira, calado. O certo é `pilar(es)?`.
            r"|(?<![a-zà-ü])pilar(?:es)?(?![a-zà-ü])"
            r"|(?<![a-zà-ü])vigas?(?![a-zà-ü])"
            r"|(?<![a-zà-ü])lajes?(?![a-zà-ü])"
            r"|(?<![a-zà-ü])baldrames?(?![a-zà-ü])"
            r"|(?<![a-zà-ü])sapatas?(?![a-zà-ü])", _re.IGNORECASE)
        _RX_NEGACAO_ANTES = _re.compile(
            r"(?<![a-zà-ü])(?:sem|s/|n[aã]o|exceto|menos)[ _./-]*$", _re.IGNORECASE)
    m = _RX_ESTRUT_NOME.search(nome or "")
    if not m:
        return False
    antes = (nome or "")[max(0, m.start() - 12):m.start()]
    return not _RX_NEGACAO_ANTES.search(antes)

def _recusa_no_upload(status: int, mensagem: str, motivo: str,
                      detalhe: str = "", quem: str = ""):
    """Recusa o upload DEIXANDO RASTRO. Sempre levanta — nunca devolve.

    🩸 04/09/2026. As SETE portas de recusa do `/api/process` não gravavam
    absolutamente nada: sem login, token trocado, muitos envios seguidos,
    request acima de 450 MB, nenhum arquivo, formato não aceito, mais de 50
    arquivos. A pessoa via o erro na tela e, do nosso lado, **não tinha
    acontecido nada**.

    🔑 Consequência medida hoje, investigando por que 15 de 96 contas nunca
    subiram projeto: no banco, **"tentou e a gente recusou" e "nunca tentou"
    são a mesma coisa**. A investigação inteira esbarrou nisso e teve que
    escrever "indeterminado" caso após caso. Já existe um cliente
    (`cliente-01@`) que mandou o POST e sumiu — hoje ele conta como
    "desistiu".

    🔑 Isto não conserta o funil; conserta a nossa capacidade de MEDIR o funil.
    Sem ele, toda pergunta sobre entrada continua sendo respondida com palpite
    — e hoje eu tive seis hipóteses derrubadas por medição, uma atrás da outra.

    🪤 `severity="warning"`: recusa não é erro do motor, mas também não é
    migalha de diagnóstico. Tem que aparecer sem afogar o painel.
    🪤 O `detalhe` é o que transforma a linha em informação: qual extensão a
    pessoa tentou, quantos MB, quantos arquivos. "Recusado" sozinho não ensina
    nada sobre o que ela queria fazer.
    """
    try:
        _log_error("upload:recusado",
                   "motivo=%s http=%d quem=%s%s"
                   % (motivo, status, (quem or "?")[:80],
                      (" | " + detalhe[:200]) if detalhe else ""),
                   None, severity="warning")
    except Exception:
        pass
    raise HTTPException(status, mensagem)


@app.post("/api/process")
async def process_files(
    request: Request,
    background_tasks: BackgroundTasks,
    files: list[UploadFile] = File(...),
    sheet_types: list[str] = Form(default=[]),
    sheet_ambientes: list[str] = Form(default=[]),
    typology: str = "office",
    project_type: str = "arquitetura",
    project_name: str = "",
    user_id: str = "",
    user_email: str = "",
    user_name: str = "",
    credits_to_consume_cents: int = 0,
    # 🩸 08/09/2026 — ERA `float`, E O FASTAPI CONVERTIA ANTES DO NOSSO CÓDIGO.
    # Com isso "1.200" (mil e duzentos, em pt-BR) chegava aqui já como 1.2 e
    # não havia conserto possível do lado de dentro: o texto original tinha
    # morrido na fronteira. Recebendo como `str`, a régua `_area_do_texto`
    # decide — e quem manda número continua funcionando ("120" lê 120).
    user_total_area: str = "",
    user_pe_direito: float = 0,
):
    """Recebe PDF, DWG ou DXF e inicia processamento em background.

    - `files`: arquivos de prancha.
    - `sheet_types` (opcional): lista paralela a `files`. String vazia
      em uma posição significa "detectar automaticamente". Valor não-vazio
      sobrescreve a detecção e força o prompt do tipo escolhido pelo user.
      Valores aceitos: demolir, layout_novo, layout_atual, arquitetura,
      pontos, piso, forro, det_forro, mobiliario, marcenaria.
    - `typology` (opcional, default `office`): usado pela calibração por
      densidade pra comparar o projeto com padrões da mesma categoria.
    - `project_name` (opcional): apelido amigável dado pelo cliente.
    - `user_id` (opcional): se informado, vincula o projeto ao usuário e
      permite consumo/crédito. Validado contra JWT — não dá pra criar
      projeto em nome de outro usuário.
    - `credits_to_consume_cents` (opcional): se > 0, consome esse valor
      de créditos do user (usado quando checkout retornou is_free=true
      por saldo suficiente).
    """
    # AUTORIZAÇÃO: se o Form passou user_id (não-anônimo), tem que ter JWT
    # correspondente. Sem isso, atacante manda user_id de outro user e
    # cria projeto+consome créditos no nome dele.
    # Processar EXIGE login sempre — fecha a "porta dos fundos": impede chamada
    # anônima direta na API (por fora do site) que dispararia IA cara sem dono.
    # O painel já loga e manda o Bearer, então não muda nada pro usuário real.
    jwt_user = _get_user_from_request(request)
    if not jwt_user:
        _recusa_no_upload(401, "Faça login para enviar um projeto.",
                          "sem-login", quem=user_email or user_id)
    if user_id and user_id != "anonymous" and jwt_user.get("id") != user_id and jwt_user.get("email", "").lower() != ADMIN_EMAIL:
        _recusa_no_upload(403, "user_id não corresponde ao token de autenticação",
                          "token-nao-bate",
                          detalhe="form=%s token=%s" % (user_id, jwt_user.get("id")),
                          quem=jwt_user.get("email") or user_email)
    # Dono autoritativo vem do token (não confia só no parâmetro).
    if not user_id or user_id == "anonymous":
        user_id = jwt_user.get("id") or user_id

    # Freio anti-abuso de CUSTO (achado auditoria 27/07): processar dispara IA
    # cara (Anthropic/Replicate) + RAM. No beta grátis/ilimitado, um usuário
    # logado num loop queimaria gasto sem teto. Limite por usuário+IP, generoso —
    # um humano sobe poucos projetos por sessão; robô em loop é barrado.
    if not _rate_limit_ok(f"process:{user_id}", request, limit=12, window_s=600):
        _recusa_no_upload(429, "Muitos projetos enviados em pouco tempo. Espere "
                          "alguns minutos e tente de novo.",
                          "muitos-envios", detalhe="teto=12 em 600s",
                          quem=jwt_user.get("email") or user_email)

    # Teto de tamanho do REQUEST (anti-OOM). Desde 21/07 o upload é gravado em
    # disco em pedaços (_stream_upload_to_disk) — NÃO bufferiza mais o arquivo
    # inteiro na RAM, então o pico de memória do upload é ~1 MB por arquivo,
    # independente do tamanho. Render agora em 4 GB de RAM (o "25 GB" é DISCO).
    # O que ainda consome RAM é o PROCESSAMENTO (ezdxf carrega o DXF na memória,
    # prancha a prancha) — por isso o cap por-arquivo (DXF 150MB) no motor segue
    # sendo a trava real; este teto de request só limita quantas pranchas vêm de
    # uma vez. 320→450 MB após o fix de streaming + upgrade pra 4 GB (incidente
    # 21/07: em 2 GB, cap de 700MB + upload de 506MB deu OOM; agora é outro cenário).
    _clen = request.headers.get("content-length") or request.headers.get("Content-Length")
    if _clen and _clen.isdigit() and int(_clen) > 450 * 1024 * 1024:
        _recusa_no_upload(413, "Arquivos muito grandes (máx. ~450 MB no total). Envie as pranchas do projeto — se for um projeto enorme, mande em 2 lotes.",
                          "request-grande",
                          detalhe="%d MB (teto 450)" % (int(_clen) // 1048576),
                          quem=jwt_user.get("email") or user_email)

    if typology not in _VALID_TYPOLOGIES:
        typology = "office"
    # Tipo de projeto escolhido no upload: roteia o motor (arquitetura vs estrutura)
    project_type = (project_type or "arquitetura").strip().lower()
    if project_type not in ("arquitetura", "estrutura"):
        project_type = "arquitetura"
    # Área informada pelo cliente (campo opcional no upload): sanitiza contra
    # número absurdo/negativo. 0 = não informou (comportamento antigo).
    try:
        user_pe_direito = float(user_pe_direito or 0)
    except (TypeError, ValueError):
        user_pe_direito = 0
    if not (1.8 <= user_pe_direito <= 8.0):   # fora disso não é pé-direito plausível
        user_pe_direito = 0
    _area_digitada = str(user_total_area or "").strip()
    _area_val, _area_err = _area_do_texto(user_total_area)
    user_total_area = float(_area_val or 0)
    # 🩸 03/09/2026 (job 3eb748e3): o cliente digitou **880.000** no campo de
    # área e passou, porque o teto era 1 km². O número foi pra planilha dele,
    # carimbado como "informada por você".
    # 🔑 Teto não é conferência de plausibilidade. Medido: TODAS as áreas já
    # informadas por cliente, do maior pro menor, são
    #     880.000 (a do cliente-73) · 3.274 · 400 · 378 · 335 · 290 · 192 · 190 ·
    #     150 · 73 · 31
    # A segunda maior é 3.274 m². A dele é 269× isso. 100.000 m² (10 hectares
    # de área construída) é 30× a maior real — generoso e ainda pega o caso.
    # 🪤 E zerar CALADO é a doença do dia: o cliente digitou e a gente ignorou
    # sem contar. Agora registra, e a resposta do upload devolve o aviso.
    # 🔑 08/09: agora o aviso carrega o que a pessoa DIGITOU, não um número
    # reformatado. Antes só existia o caso "grande demais" — porque só ele era
    # detectável: qualquer outra coisa virava float torto e passava calada.
    # Com a régua nova, "1.200" é lido certo (1200) e "abc" é recusado com
    # motivo; os dois casos avisam, em vez de zerar em silêncio.
    aviso_area_implausivel = _area_digitada if _area_err else None
    if not files:
        _recusa_no_upload(400, "Nenhum arquivo enviado", "sem-arquivo",
                          quem=jwt_user.get("email") or user_email)

    # Validar arquivos (aceitar PDF, DWG e DXF)
    valid_extensions = ('.pdf', '.dwg', '.dxf')
    # Guarda triplas (arquivo, sheet_type, ambiente) pra manter o mapeamento
    # após filtragem. sheet_types/sheet_ambientes podem estar vazias.
    valid_pairs = []
    for idx, f in enumerate(files):
        if f.filename and f.filename.lower().endswith(valid_extensions):
            st = sheet_types[idx] if idx < len(sheet_types) else ""
            amb = sheet_ambientes[idx] if idx < len(sheet_ambientes) else ""
            valid_pairs.append((f, st, amb))
    if not valid_pairs:
        # 🔑 O detalhe aqui é o mais valioso dos sete: diz QUE FORMATO a pessoa
        # tentou subir. Se aparecer .rvt, .skp ou .ifc com frequência, isso é
        # informação de PRODUTO, não de erro.
        _ext = sorted({(f.filename or "?").lower().rsplit(".", 1)[-1][:8]
                       for f in files if f.filename})
        _recusa_no_upload(400, "Nenhum arquivo válido encontrado. Aceito: PDF, DWG ou DXF.",
                          "formato-nao-aceito",
                          detalhe="tentou: %s (%d arquivo(s))" % (", ".join(_ext) or "?", len(files)),
                          quem=jwt_user.get("email") or user_email)

    if len(valid_pairs) > 50:
        _recusa_no_upload(400, "Máximo de 50 arquivos por projeto", "muitos-arquivos",
                          detalhe="%d arquivos (teto 50)" % len(valid_pairs),
                          quem=jwt_user.get("email") or user_email)

    # ── TRAVA DE ENVIO EM DOBRO ──────────────────────────────────────────
    # 🚨 26/08/2026, caso cliente-34. O site mandou o MESMO arquivo DUAS VEZES,
    # com 1 segundo de diferença:
    #     13:18:47  POST /api/process -> b249f3e4
    #     13:18:48  POST /api/process -> 58bc66c7   (mesmo DWG, mesmo projeto)
    # Os dois jobs entraram em processamento e a memória do Render foi de
    # 287 MB (10:17) a 3,81 GB (10:19), contra um teto de 4,29 GB. A instância
    # reiniciou e ela levou DOIS erros seguidos na cara — no primeiro projeto
    # que mandou depois de se cadastrar. Ela nunca mais enviou nada.
    #
    # 🪤 A trava de 3 s do `dashboard.html` (`_ultimoEnvioMs`) EXISTE e tem um
    # listener só — e mesmo assim os dois passaram. Ela é POR ABA: não cobre
    # duas abas, nem retry do XHR, nem chamada direta na API. Trava de tela
    # nunca vai cobrir; a do servidor cobre a origem toda de uma vez.
    #
    # 🔑 Não é rate-limit: o `_rate_limit_ok` acima deixa 12 projetos em 10 min
    # de propósito (um humano manda vários projetos DIFERENTES numa sessão).
    # O que esta trava barra é o MESMO projeto duas vezes em segundos — e ela
    # devolve o job que já existe, então pro cliente parece que funcionou (que é
    # o que ele queria: UM projeto processando).
    _assinatura_envio = _assinatura_do_envio(user_id, project_name, valid_pairs)
    _ja_existe = _envio_recente_igual(_assinatura_envio)
    if _ja_existe:
        _log_error("motor:envio-em-dobro",
                   f"user={str(user_id)[:8]} projeto={str(project_name)[:40]!r} "
                   f"n_arquivos={len(valid_pairs)} -> devolvendo {_ja_existe}",
                   _ja_existe, severity="info")
        # 🪤 Espelha o formato da resposta normal. O site lê `data.job_id` e
        # também `data.aviso_aec` / `data.aviso_estrutural` — devolver um dicionário
        # curto demais faria o cliente cair num caminho sem os campos que ele lê.
        return {"job_id": _ja_existe, "files_received": len(valid_pairs),
                "file_types": {"pdf": 0, "dwg": 0, "dxf": 0}, "status": "queued",
                "typology": typology, "project_type": project_type,
                "duplicado": True}

    # Criar job
    job_id = str(uuid.uuid4())[:8]
    _registrar_envio(_assinatura_envio, job_id)
    work_dir = os.path.join(WORK_DIR, job_id)
    os.makedirs(work_dir, exist_ok=True)

    # Salvar arquivos + mapas {caminho_local: sheet_type / ambiente}
    file_paths = []
    user_sheet_types: dict[str, str] = {}
    user_ambientes: dict[str, str] = {}
    file_types = {'pdf': 0, 'dwg': 0, 'dxf': 0}
    avisos_aec: list[str] = []   # DWGs com objetos AEC — aviso imediato (ver abaixo)
    # Arquivos com cara de projeto ESTRUTURAL enviados em modo arquitetura
    # (01/08/2026: só 3 de 107 projetos escolheram o modo estrutura no dropdown,
    # enquanto FORMA.pdf/fundacao.pdf passavam como arquitetura — onde laje e
    # aço nunca são medidos). Detecção por nome do arquivo, aviso não-bloqueante.
    avisos_estrutural: list[str] = []
    # 🪤 O regex vivia AQUI, solto, e ficou pra trás quando a detecção virou a
    # função `_nome_parece_estrutural` (que sabe ler a negação do "SEM
    # ESTRUTURAL"). Ele continuava sendo compilado a cada upload e não era lido
    # por ninguém — o pyflakes acusava "assigned to but never used". Cópia velha
    # de regra ao lado da regra nova é a próxima pessoa consertando a errada.
    # A fronteira do "forma" (pra "inFORMAtivo" e "plataFORMA" não dispararem)
    # continua viva, dentro da função.
    # 🪤 Importar AQUI e reclamar alto se falhar. A detecção só valia a pena se
    # rodasse mesmo; escondida atrás de um try/except mudo, um ImportError
    # deixaria o aviso desligado pra sempre sem ninguém perceber.
    try:
        from dwg_extractor import dwg_has_aec_markers as _detecta_aec
    except Exception as _e_imp:
        _detecta_aec = None
        print(f"[upload] AVISO: detecção de AEC indisponível ({type(_e_imp).__name__}: {_e_imp})")
        try:
            _log_error("dwg:aec-detector-indisponivel",
                       f"Não consegui importar dwg_has_aec_markers no upload: "
                       f"{type(_e_imp).__name__}: {_e_imp}", None, severity="warning")
        except Exception:
            pass
    for upload_file, user_st, user_amb in valid_pairs:
        # Anti path-traversal: nunca confiar em upload_file.filename
        safe_name = _safe_local_filename(upload_file.filename)
        file_path = os.path.join(work_dir, safe_name)
        # Grava em disco em pedaços (não bufferiza o arquivo inteiro na RAM).
        n_written, head = await _stream_upload_to_disk(upload_file, file_path)

        # Validação de integridade (Bug cliente-40 2026-05-04: DWG chegou
        # truncado e backend processou sem detectar, gerando planilha vazia)
        if upload_file.size and n_written != upload_file.size:
            try: os.remove(file_path)
            except OSError: pass
            # 🔑 A recusa MAIS importante das dez: significa que a conexão
            # caiu no meio do envio. É literalmente "tentou e falhou" — e era
            # justamente o caso que ficava indistinguível de "nunca tentou".
            _recusa_no_upload(
                400,
                f"Arquivo '{upload_file.filename}' chegou incompleto: "
                f"recebido {n_written} de {upload_file.size} bytes. "
                f"Provável conexão instável durante upload — tente de novo.",
                "envio-incompleto",
                detalhe="%s: %d de %d bytes" % (upload_file.filename, n_written,
                                                upload_file.size),
                quem=jwt_user.get("email") or user_email)
        ext = upload_file.filename.lower().rsplit('.', 1)[-1]
        if ext == "dwg":
            if n_written < 100:
                try: os.remove(file_path)
                except OSError: pass
                _recusa_no_upload(
                    400,
                    f"DWG '{upload_file.filename}' muito pequeno ({n_written} bytes) — "
                    f"provavelmente corrompido. Verifique se o arquivo abre no AutoCAD.",
                    "dwg-pequeno-demais",
                    detalhe="%s: %d bytes" % (upload_file.filename, n_written),
                    quem=jwt_user.get("email") or user_email)
            if head[:2] != b"AC":
                try: os.remove(file_path)
                except OSError: pass
                _recusa_no_upload(
                    400,
                    f"DWG '{upload_file.filename}' não tem assinatura válida "
                    f"(esperado iniciar com 'AC10xx'). Arquivo corrompido — "
                    f"verifique no AutoCAD ou exporte como PDF e suba o PDF.",
                    "dwg-sem-assinatura",
                    detalhe="%s: começa com %r" % (upload_file.filename, head[:4]),
                    quem=jwt_user.get("email") or user_email)
            # AEC/MEP: avisar AGORA, não depois de 5 min de processamento.
            # Medido em 01/08/2026: 13 das 29 falhas de DWG são objetos AEC
            # (AutoCAD Architecture/MEP), que nenhum conversor livre abre. A
            # detecção já existia — mas só rodava DEPOIS da conversão falhar,
            # então o cliente esperava o processamento inteiro pra descobrir.
            # NÃO bloqueia: o mesmo envio pode trazer um DXF ou PDF que salve
            # o projeto. Só entrega a informação enquanto ele ainda está na tela.
            if _detecta_aec is not None:
                try:
                    if _detecta_aec(file_path):
                        avisos_aec.append(upload_file.filename)
                except Exception as _e_aec:
                    print(f"[upload] detecção AEC falhou em {safe_name}: {_e_aec}")

        if project_type != "estrutura" and _nome_parece_estrutural(upload_file.filename or ""):
            avisos_estrutural.append(upload_file.filename)
        file_paths.append(file_path)
        if user_st:
            user_sheet_types[file_path] = user_st
        if user_amb:
            user_ambientes[file_path] = user_amb
        file_types[ext] = file_types.get(ext, 0) + 1

    # Resumo de tipos recebidos
    types_summary = ", ".join(f"{v} {k.upper()}" for k, v in file_types.items() if v > 0)

    # Criar status
    jobs[job_id] = ProcessingStatus(
        job_id=job_id,
        status="queued",
        progress=0,
        current_step=f"Recebidos {len(file_paths)} arquivos ({types_summary}). Iniciando processamento...",
        total_steps=3,
    )

    # Salvar projeto no Supabase
    _supabase_insert("projects", {
        "job_id": job_id,
        "user_id": user_id or "anonymous",
        "user_email": user_email or "",
        "user_name": user_name or "",
        "project_name": project_name or "Sem nome",
        "typology": typology,
        "project_type": project_type,
        "files_count": len(file_paths),
        "file_types": file_types,
        "status": "queued",
        "user_total_area": user_total_area if user_total_area > 0 else None,
        # 🪤 Gravar o pé-direito NÃO é só pra retomada: sem ele no banco era
        # impossível saber se a derivação de pintura tinha 0 casos por falta de
        # uso ou por estar quebrada (03/08: 0 itens derivados, e nenhuma forma
        # de distinguir os dois). Campo que o cliente informa tem que ficar
        # registrado, nem que seja só pra medir.
        "user_pe_direito": user_pe_direito if user_pe_direito > 0 else None,
    })

    # Consome créditos de cashback/cupom se o frontend declarou uso
    # (quando crédito cobriu 100% do preço e pulou o Stripe).
    if credits_to_consume_cents > 0 and user_id and user_id != "anonymous":
        consumed = _consume_credits(user_id, credits_to_consume_cents, job_id)
        print(f"[credits] job={job_id} user={user_id} consumed={consumed}/{credits_to_consume_cents}")

    # Iniciar processamento em thread separada (não bloqueia HTTP).
    # Usa _process_job_throttled (fila de vagas) pra não estourar RAM com jobs
    # concorrentes — ver _tem_vaga_agora / _esperar_vaga acima.
    import threading
    t = threading.Thread(
        target=_process_job_throttled,
        args=(job_id, file_paths, work_dir),
        kwargs={"typology": typology,
                "user_sheet_types": user_sheet_types,
                "user_ambientes": user_ambientes,
                "project_type": project_type,
                "user_total_area": user_total_area,
                "user_pe_direito": user_pe_direito},
        daemon=True,
    )
    t.start()

    # Alerta interno pro Pedro: novo projeto entrou (em thread — não atrasa a resposta)
    try:
        import html as _h4, threading as _th4
        _types_str = ", ".join(f"{v} {k.upper()}" for k, v in file_types.items() if v > 0)
        _alert_body = (f"<b>Usuário:</b> {_h4.escape(user_name or '—')} &lt;{_h4.escape(user_email or 'anônimo')}&gt;<br>"
                       f"<b>Projeto:</b> {_h4.escape(project_name or '(sem nome)')}<br>"
                       f"<b>Arquivos:</b> {len(file_paths)} ({_types_str})<br>"
                       f"<b>Código:</b> {job_id}")
        _th4.Thread(target=_notify_admin, args=("Novo projeto recebido", _alert_body), daemon=True).start()
    except Exception as _na:
        print(f"[notify] alerta novo-projeto falhou: {_na}")

    resp = {"job_id": job_id, "files_received": len(file_paths),
            "file_types": file_types, "status": "queued", "typology": typology,
            "project_type": project_type}
    # 🩸 01/09 — "MANDEI DE NOVO E DEU A MESMA COISA". O cliente que recebe uma
    # planilha cheia de linha vazia acha que o problema é o ARQUIVO dele e
    # remanda o mesmo caderno. O cliente-75 fez isso 11 minutos depois de receber a
    # primeira. Ele não estava errado em tentar — estava sem a informação de
    # que o que trava não é o arquivo.
    # 🪤 Aviso, nunca bloqueio: reenviar é direito dele, e a mesma tela já tem
    # dois avisos não-bloqueantes (AEC, estrutural) — este é o terceiro da
    # família e usa o mesmo caminho no site.
    # 🚫 O texto NÃO promete "mesmo resultado": o motor não é determinístico
    # (medido 08/08 — 458 e 177 m² do mesmo arquivo). Promete o que é verdade:
    # a CAUSA do vazio não mudou, e diz quais são as duas alavancas que mudam.
    try:
        _repet = _projeto_ja_enviado(
            user_id,
            {(getattr(f, "filename", "") or "").strip().lower()
             for f, _st, _amb in valid_pairs},
            user_pe_direito, user_total_area)
    except Exception as _e_rep:
        _repet = None
        print(f"[upload] checagem de projeto repetido falhou: {_e_rep}")
    if _repet:
        _so_pdf = file_types.get("pdf", 0) > 0 and (
            file_types.get("dwg", 0) + file_types.get("dxf", 0)) == 0
        # 🩸 22/09/2026 (job ee801b82 → f8d8e6d8): pranchas de ESTRUTURA
        # (poço, caixa de válvulas, bloco) receberam o conselho da arquitetura:
        # pé-direito "pra parede, pintura e rodapé" e área "pra piso e forro".
        # 📏 Medido em 22/09 (90 d, sem eval): em estrutura, pé-direito
        # informado nunca preencheu linha (`motor:pe-direito` estrutura
        # tocados=0 em todos) e área informada preencheu 0 linhas em 4 jobs.
        # 🔑 O tipo das PRANCHAS conta: se da outra vez elas foram lidas como
        # estrutura, o conselho de arquitetura também não vale pra elas agora.
        _tipo_antes = _repet.get("project_type") or ""
        _estrutura = project_type == "estrutura" or _tipo_antes == "estrutura"
        _saidas = []
        # 🩸 22/09/2026 (revisão): com o tipo trocado, o aviso dizia "mandar de
        # novo não muda o motivo" e, logo abaixo, "o tipo muda o que a gente
        # procura" — na direção de correção, a 1ª frase é falsa. E mandava
        # conferir DEPOIS de o envio sair, sem dizer como consertar.
        _troca_de_tipo = bool(_tipo_antes and _tipo_antes != project_type)
        if _troca_de_tipo:
            _saidas.append(
                "da outra vez estas pranchas foram lidas como %s, e este envio "
                "está como %s — o tipo muda o que a gente procura no desenho. "
                "Se este envio estiver com o tipo errado, não precisa mandar os "
                "arquivos de novo: quando ele terminar, abra o projeto e, em "
                "Detalhes do processamento, use Reprocessar escolhendo o tipo certo"
                % (_tipo_antes.upper(), (project_type or "").upper()))
        if not user_pe_direito and not _estrutura:
            # 📏 MEDIDO (26/08): informar o pé-direito derruba a fatia de linha
            # em branco de 59,5% pra 27,3%. É a maior alavanca que existe, e é
            # um campo de dez segundos.
            _saidas.append(
                "informe o PÉ-DIREITO no envio — é o campo que mais preenche "
                "linha vazia aqui (parede, pintura e rodapé dependem dele)")
        if not user_total_area and not _estrutura:
            _saidas.append(
                "informe a ÁREA TOTAL — ela vira base honesta pros itens de "
                "piso, forro e laje, rotulada como informada por você")
        if _so_pdf:
            _saidas.append(
                "se você tiver o DXF ou o DWG das mesmas pranchas, mande ele: "
                + ("de PDF a gente lê o desenho, mas número lido de PDF não "
                   "vira quantidade medida" if _estrutura else
                   "de PDF a gente lê a planta, mas comprimento de PDF não é "
                   "confiável o bastante pra virar número"))
        # 🔑 O número só é afirmado quando a conta é exata (lista do Storage).
        # Pelos itens ele é piso: prancha sem item não entra.
        _quantos = ("%d dos %d" if _repet.get("contagem_exata")
                    else "Pelo menos %d dos %d") % (_repet["n_iguais"], _repet["n_novos"])
        resp["aviso_repetido"] = {
            "job_anterior": _repet["job_id"],
            "projeto_anterior": _repet["project_name"],
            "arquivos_iguais": _repet["n_iguais"],
            "arquivos_enviados": _repet["n_novos"],
            "titulo": "Estas pranchas já passaram por aqui",
            "texto": (
                "%s arquivos deste envio têm o mesmo nome dos que você mandou "
                "no projeto \"%s\". Seu projeto vai processar normalmente%s\n\n"
                "O que muda:\n%s"
                % (_quantos, _repet["project_name"],
                   (". Desta vez o tipo é outro, então a leitura pode sair "
                    "diferente." if _troca_de_tipo else
                    " — mas se o que te incomodou foi linha em branco e as "
                    "pranchas são as mesmas, mandar de novo não muda o motivo "
                    "delas estarem em branco."),
                   "\n".join("• " + s for s in _saidas) if _saidas else
                   "• abra a revisão do projeto e preencha as linhas que "
                   "faltam — o que você corrigir lá a gente usa")),
        }
        try:
            _log_error("upload:projeto-repetido",
                       "user=%s remandou %d de %d arquivos do job %s (%.0f%%) "
                       "— avisado no envio (pe_direito=%s area=%s) "
                       "contagem=%s tipo=%s->%s"
                       % (str(user_id)[:8], _repet["n_iguais"], _repet["n_novos"],
                          _repet["job_id"], 100 * _repet["fracao"],
                          user_pe_direito or "-", user_total_area or "-",
                          "storage" if _repet.get("contagem_exata") else "itens",
                          _tipo_antes or "-", project_type or "-"),
                       job_id, severity="info")
        except Exception:
            pass
    if aviso_area_implausivel is not None:
        resp["aviso_area"] = {
            "valor": aviso_area_implausivel,
            "titulo": "Conferir a área total informada",
            # 🪤 O número é formatado SOZINHO. A 1ª versão fazia
            # `.format(...).replace(",", ".")` na frase inteira e comeu a
            # vírgula do texto: "…3.274 m²). então NÃO usamos". Trocar
            # separador no texto todo estraga a pontuação.
            # 🪤 O texto ecoa o que a pessoa DIGITOU, sem reformatar. A versão
            # antiga formatava o número (`{:,.0f}` + troca de separador) e já
            # tinha comido a vírgula da frase uma vez. E agora há um motivo
            # melhor: quando a recusa é "não consegui ler", não existe número
            # nenhum pra formatar — existe o texto dela.
            "texto": ("Você informou “{}” no campo de área total, e a gente "
                      "não usou esse número: {}.\n\n"
                      "O projeto segue normalmente e a área sai medida da "
                      "prancha, se ela tiver cota ou quadro de áreas. Se o "
                      "número estiver certo mesmo, é só reenviar e a gente "
                      "olha o caso.").format(aviso_area_implausivel, _area_err),
        }
        try:
            _log_error("upload:area-implausivel",
                       f"cliente digitou '{aviso_area_implausivel}' no campo de área "
                       f"— {_area_err} (teto {_AREA_PLAUSIVEL_MAX}) — "
                       f"IGNORADA e cliente avisado no envio", job_id)
        except Exception:
            pass
    if avisos_estrutural and project_type != "estrutura":
        resp["aviso_estrutural"] = {
            "arquivos": avisos_estrutural,
            "titulo": "Esses arquivos parecem de projeto ESTRUTURAL",
            "texto": ("Pelo nome, são pranchas de estrutura (fôrma, fundação, armação...). "
                      "Este envio está no modo Arquitetura, que não mede aço, pilares nem lajes.\n\n"
                      "Se o objetivo é o quantitativo estrutural: envie de novo escolhendo "
                      "'Estrutura (concreto armado)' no tipo de projeto — lá o motor mede aço "
                      "por tabela, pilares e lajes.\n\n"
                      "Se essas pranchas são só apoio do projeto de arquitetura, ignore este aviso."),
        }
        try:
            _log_error("upload:estrutural-em-modo-arquitetura",
                       f"Arquivos com cara de estrutural em modo arquitetura: "
                       f"{', '.join(avisos_estrutural[:5])} — cliente avisado no envio",
                       job_id, severity="info")
        except Exception:
            pass
    if avisos_aec:
        _tem_alternativa = (file_types.get('dxf', 0) + file_types.get('pdf', 0)) > 0
        resp["aviso_aec"] = {
            "arquivos": avisos_aec,
            "tem_alternativa": _tem_alternativa,
            "titulo": ("Um dos seus arquivos é do AutoCAD Architecture/MEP"
                       if len(avisos_aec) == 1 else
                       "Alguns arquivos são do AutoCAD Architecture/MEP"),
            "texto": (
                "Esse tipo de DWG guarda paredes e móveis como \"objetos inteligentes\", "
                "que nenhum conversor abre direto — nem o \"Salvar como DXF\" comum. "
                "Não é defeito do seu arquivo.\n\n"
                "Como resolver, em 3 passos:\n"
                "1. No AutoCAD, com o arquivo aberto, digite EXPORTTOAUTOCAD e Enter\n"
                "2. Escolha a versão 2013 e confirme — ele cria um arquivo novo "
                "(o seu original não é alterado)\n"
                "3. Abra esse arquivo novo, salve como DXF e anexe aqui\n\n"
                + ("Seu projeto vai seguir processando com os outros arquivos, "
                   "mas o que estiver só nesse DWG não vai ser medido."
                   if _tem_alternativa else
                   "Como esse é o único arquivo do envio, o processamento "
                   "provavelmente não vai conseguir medir nada.")),
        }
        try:
            _log_error("dwg:aec-detectado-no-upload",
                       f"AEC detectado ANTES de processar: {', '.join(avisos_aec)} — "
                       f"cliente avisado na hora (alternativa no envio: {_tem_alternativa})",
                       job_id, severity="info")
        except Exception:
            pass
    return resp


@app.get("/api/debug/supa-log")
async def debug_supa_log(request: Request, tail: int = 50):
    """Últimas N linhas do log de operações Supabase — pra investigar por que
    updates silenciosos falham sem ter acesso direto ao log do Render.

    Restrito a admin (vaza queries internas com payloads e IDs).
    """
    _require_admin(request)
    try:
        if not os.path.exists(_SUPA_LOG_PATH):
            return {"status": "ok", "lines": [], "note": "log vazio ou ainda não criado"}
        with open(_SUPA_LOG_PATH, "r", encoding="utf-8") as f:
            all_lines = f.readlines()
        last = all_lines[-tail:] if tail > 0 else all_lines
        return {"status": "ok", "total_lines": len(all_lines),
                "returned": len(last), "lines": [ln.rstrip("\n") for ln in last]}
    except Exception as e:
        return {"status": "error", "error": f"{type(e).__name__}: {e}"}


# Estado do teste de libredwg (roda em thread — o Render corta HTTP em ~100 s,
# e o lote leva ate 4 min; "Load failed" no admin em 01/08 foi isso).
_LIBREDWG_TESTE = {"rodando": False, "resultados": [], "testados": 0,
                   "converteram_e_abrem": 0, "jobs_na_fila": 0, "fim": None}


def _medir_dxf_geometria(dxf_path: str) -> dict:
    """Métricas de geometria pra comparar conversores (qualidade, não estética):
    nº de entidades, extensão do desenho e soma dos comprimentos de linha.
    Se dois DXF do MESMO DWG batem nisso, medem igual no motor."""
    import ezdxf, math
    doc = ezdxf.readfile(dxf_path)
    msp = doc.modelspace()
    n = 0
    total_len = 0.0
    xs, ys = [], []
    for e in msp:
        n += 1
        try:
            t = e.dxftype()
            if t == "LINE":
                dx = e.dxf.end.x - e.dxf.start.x
                dy = e.dxf.end.y - e.dxf.start.y
                total_len += math.hypot(dx, dy)
                xs += [e.dxf.start.x, e.dxf.end.x]; ys += [e.dxf.start.y, e.dxf.end.y]
            elif t == "LWPOLYLINE":
                pts = [(p[0], p[1]) for p in e.get_points()]
                for a, b in zip(pts, pts[1:]):
                    total_len += math.hypot(b[0]-a[0], b[1]-a[1])
                xs += [p[0] for p in pts]; ys += [p[1] for p in pts]
        except Exception:
            continue
    ext = ((max(xs)-min(xs)) if xs else 0.0, (max(ys)-min(ys)) if ys else 0.0)
    return {"entidades": n, "soma_linhas": round(total_len, 1),
            "extensao": (round(ext[0], 1), round(ext[1], 1))}


@app.get("/api/debug/libredwg-batch")
def debug_libredwg_batch(request: Request, limite: int = 5,
                               iniciar: int = 0, modo: str = "recusados"):
    """Mede o fallback libredwg contra os DWG que o ODA recusou. Admin-only.

    Contexto (01/08/2026): 6+ envios falharam com 'não conseguimos abrir' e o
    caso Ana provou que às vezes o arquivo é bom — o conversor é que não lê.
    O dwg2dxf (libredwg) está compilado no Docker desde 29/07 e NUNCA foi
    medido contra um arquivo real recusado. Este endpoint baixa do Storage os
    DWG de jobs com esse erro, roda o dwg2dxf em cada um e reporta:
    converteu? o DXF resultante abre no ezdxf? quantas entidades tem?

    Só LÊ e mede — não reprocessa nada, não mexe em projeto nenhum.

    🪤 Roda em THREAD e o navegador faz POLLING: o Render corta respostas HTTP
    em ~100 s e o lote leva até 4 min — a 1ª versão síncrona morreu com
    "Load failed" no admin (01/08). `?iniciar=1` dispara; sem parâmetro,
    devolve o andamento. `limite` = arquivos por lote (1-10).
    """
    _require_admin(request)
    import shutil as _sh
    dwg2dxf = _sh.which("dwg2dxf")
    if not dwg2dxf:
        return {"erro": "dwg2dxf não está no PATH deste servidor",
                "dica": "confirmar no /api/debug/dwg se libredwg_which é null"}

    if not iniciar or _LIBREDWG_TESTE["rodando"]:
        return dict(_LIBREDWG_TESTE)   # snapshot do andamento (ou do último lote)

    limite = max(1, min(10, int(limite)))
    _LIBREDWG_TESTE.update({"rodando": True, "resultados": [], "testados": 0,
                            "converteram_e_abrem": 0, "jobs_na_fila": 0, "fim": None})

    def _rodar_qualidade(_sp, _tf, t0):
        """Converte o MESMO DWG pelo ODA e pelo libredwg e compara a geometria.

        É a validação que a trava de qualidade do fallback pede: DXF que abre
        mas mede diferente geraria número branco falso (regra nº1). Roda nos
        DWGs de projetos DONE (onde o ODA funcionou e dá baseline)."""
        from dwg_extractor import convert_dwg_to_dxf
        _st_q, rows = _supa_rest_service(
            "GET",
            "projects?status=eq.done&select=job_id,file_types,created_at"
            "&order=created_at.desc&limit=80")
        rows = rows if isinstance(rows, list) else []
        jobs = [r["job_id"] for r in rows
                if (r.get("file_types") or {}).get("dwg", 0) > 0]
        _LIBREDWG_TESTE["jobs_na_fila"] = len(jobs)
        dwg2dxf_bin = __import__("shutil").which("dwg2dxf")
        # 🪤 1ª rodada (print do Pedro, 01/08): 4 dos 5 sorteados eram DWGs que
        # o ODA nem converte — projetos DONE via PDF/DXF com o DWG falhando em
        # silêncio. Sem baseline não há comparação, então esses não podem
        # consumir o limite; só contam num teto de tentativas separado.
        _tentativas = 0
        for job in jobs:
            if (_LIBREDWG_TESTE["testados"] >= limite or _tentativas >= 25
                    or time.time() - t0 > 600):
                break
            try:
                nomes = [n for n in _supabase_storage_list(PRANCHAS_BUCKET, f"{job}/")
                         if n.lower().endswith(".dwg")]
            except Exception:
                continue
            for nome in nomes[:1]:   # 1 DWG por job basta pra amostra
                if (_LIBREDWG_TESTE["testados"] >= limite or _tentativas >= 25
                        or time.time() - t0 > 600):
                    break
                _tentativas += 1
                item = {"job_id": job, "arquivo": nome}
                try:
                    dados = _supabase_storage_download_prancha(job, nome)
                    if not dados:
                        item["resultado"] = "não consegui baixar"
                    else:
                        with _tf.TemporaryDirectory() as tmp:
                            src = os.path.join(tmp, "in.dwg")
                            open(src, "wb").write(dados)
                            item["mb"] = round(len(dados) / 1048576, 1)
                            dxf_oda = convert_dwg_to_dxf(src)   # gate off ⇒ só ODA
                            dst_lw = os.path.join(tmp, "lw.dxf")
                            try:
                                _sp.run([dwg2dxf_bin, "-y", "-o", dst_lw, src],
                                        capture_output=True, timeout=90)
                            except _sp.TimeoutExpired:
                                pass
                            if not dxf_oda:
                                item["resultado"] = "ODA não converteu (sem baseline)"
                            elif not os.path.exists(dst_lw) or os.path.getsize(dst_lw) == 0:
                                item["resultado"] = "libredwg não converteu este"
                            else:
                                m_oda = _medir_dxf_geometria(dxf_oda)
                                m_lw = _medir_dxf_geometria(dst_lw)
                                item["oda"] = m_oda
                                item["libredwg"] = m_lw
                                base = m_oda["soma_linhas"] or 1e-9
                                delta = abs(m_lw["soma_linhas"] - m_oda["soma_linhas"]) / base
                                item["delta_linhas_pct"] = round(delta * 100, 2)
                                iguais = delta <= 0.01
                                item["resultado"] = ("GEOMETRIA BATE (≤1%)" if iguais
                                                     else "GEOMETRIA DIVERGE")
                                if iguais:
                                    _LIBREDWG_TESTE["converteram_e_abrem"] += 1
                except Exception as e:
                    item["resultado"] = f"erro: {type(e).__name__}: {e}"[:150]
                _LIBREDWG_TESTE["resultados"].append(item)
                if "delta_linhas_pct" in item:
                    _LIBREDWG_TESTE["testados"] += 1   # só comparações reais contam
        try:
            _log_error("libredwg:qualidade",
                       f"{_LIBREDWG_TESTE['converteram_e_abrem']} de "
                       f"{_LIBREDWG_TESTE['testados']} DWGs com geometria batendo "
                       f"ODA×libredwg (±1%, soma de linhas)", None, severity="info")
        except Exception:
            pass

    def _rodar():
        import subprocess as _sp, tempfile as _tf
        t0 = time.time()
        try:
            # 🪤 _supa_rest_service devolve (status, dados) — iterar a tupla
            # direto quebrava a thread em 0,1 s ("0 de 0" no admin, 01/08).
            if modo == "qualidade":
                _rodar_qualidade(_sp, _tf, t0)
                return
            _st_lw, rows = _supa_rest_service(
                "GET",
                "projects?status=eq.error&select=job_id,error_message,created_at"
                "&order=created_at.desc&limit=60")
            rows = rows if isinstance(rows, list) else []
            jobs = [r["job_id"] for r in rows
                    if "conseguimos abrir" in (r.get("error_message") or "").lower()]
            _LIBREDWG_TESTE["jobs_na_fila"] = len(jobs)
            for job in jobs:
                if _LIBREDWG_TESTE["testados"] >= limite or time.time() - t0 > 600:
                    break
                try:
                    nomes = [n for n in _supabase_storage_list(PRANCHAS_BUCKET, f"{job}/")
                             if n.lower().endswith(".dwg")]
                except Exception:
                    continue
                for nome in nomes:
                    if _LIBREDWG_TESTE["testados"] >= limite or time.time() - t0 > 600:
                        break
                    item = {"job_id": job, "arquivo": nome}
                    try:
                        dados = _supabase_storage_download_prancha(job, nome)
                        if not dados:
                            item["resultado"] = "não consegui baixar do Storage"
                        else:
                            with _tf.TemporaryDirectory() as tmp:
                                src = os.path.join(tmp, "in.dwg")
                                dst = os.path.join(tmp, "out.dxf")
                                open(src, "wb").write(dados)
                                item["mb"] = round(len(dados) / 1048576, 1)
                                try:
                                    proc = _sp.run([dwg2dxf, "-o", dst, src],
                                                   capture_output=True, timeout=90)
                                    item["exit"] = proc.returncode
                                    if not os.path.exists(dst) or os.path.getsize(dst) == 0:
                                        item["resultado"] = "dwg2dxf não gerou DXF"
                                        item["stderr"] = (proc.stderr or b"")[-200:].decode(
                                            "utf-8", "replace")
                                    else:
                                        item["dxf_mb"] = round(os.path.getsize(dst) / 1048576, 1)
                                        try:
                                            import ezdxf
                                            doc = ezdxf.readfile(dst)
                                            item["resultado"] = "CONVERTEU e o DXF abre"
                                            item["entidades"] = len(doc.modelspace())
                                            _LIBREDWG_TESTE["converteram_e_abrem"] += 1
                                        except Exception as e_dxf:
                                            item["resultado"] = "converteu mas o DXF não abre no ezdxf"
                                            item["erro_leitura"] = (
                                                f"{type(e_dxf).__name__}: {e_dxf}"[:120])
                                except _sp.TimeoutExpired:
                                    item["resultado"] = "timeout (90s)"
                    except Exception as e:
                        item["resultado"] = f"erro no teste: {type(e).__name__}: {e}"[:150]
                    _LIBREDWG_TESTE["resultados"].append(item)
                    _LIBREDWG_TESTE["testados"] += 1
            # registra o veredito no error_log — sobrevive a restart e aparece no painel
            try:
                _log_error("libredwg:batch",
                           f"{_LIBREDWG_TESTE['converteram_e_abrem']} de "
                           f"{_LIBREDWG_TESTE['testados']} DWG recusados converteram e abrem "
                           f"({round(time.time()-t0)}s)", None, severity="info")
            except Exception:
                pass
        finally:
            _LIBREDWG_TESTE["rodando"] = False
            _LIBREDWG_TESTE["fim"] = round(time.time() - t0, 1)

    threading.Thread(target=_rodar, daemon=True).start()
    return {"iniciado": True, **{k: v for k, v in _LIBREDWG_TESTE.items()}}


@app.get("/api/debug/storage-limit")
async def debug_storage_limit(request: Request, mb: int = 60):
    """Descobre o limite REAL de upload do Storage sem usar cliente como cobaia.

    Sobe um arquivo sintético de `mb` MB no bucket das pranchas e apaga em
    seguida. Devolve OK ou o motivo exato da recusa (413 = passou do limite
    global do projeto; timeout = lentidão, não limite).

    Existe porque em 31/07 (caso Ana) 4 de 37 projetos com CAD estavam sem o
    arquivo original e não dava pra saber se era o teto de 50 MB do plano Free
    ou o timeout de 60s — os dois suspeitos empilhados. Restrito a admin.
    """
    _require_admin(request)
    import tempfile, urllib.request, urllib.parse as _up
    PASTA_DIAG = "diagnostico"
    mb = max(1, min(600, int(mb)))
    _t0 = time.time()
    caminho = None
    try:
        # Conteúdo tipo DXF (texto repetido) pra o teste parecer o caso real:
        # bytes aleatórios não comprimem, texto sim, e é texto que a gente sobe.
        linha = b"  0\nLINE\n  8\nTESTE-DIAGNOSTICO\n 10\n0.0\n 20\n0.0\n"
        with tempfile.NamedTemporaryFile(suffix=".dxf", delete=False) as fh:
            caminho = fh.name
            escrito = 0
            alvo = mb * 1048576
            bloco = linha * 2048
            while escrito < alvo:
                fh.write(bloco)
                escrito += len(bloco)
        tamanho_real = os.path.getsize(caminho) / 1048576.0
        nome = "diagnostico-limite.dxf"
        ok = await run_in_threadpool(
            _supabase_storage_upload_prancha, caminho, PASTA_DIAG, nome)
        resp = {
            "tamanho_testado_mb": round(tamanho_real, 1),
            "subiu": ok,
            "motivo": None if ok else (_ULTIMA_FALHA_UPLOAD_PRANCHA or "não registrado"),
            "segundos": round(time.time() - _t0, 1),
        }
        # Limpa TUDO que existir na pasta de diagnóstico, não só o desta rodada.
        # 🪤 Antes eu montava a chave com o nome ORIGINAL, mas o upload sanitiza
        # o nome antes de gravar (`_sanitize_filename_for_storage`) — o delete
        # batia num caminho que não existia e deixava 250 MB parados no bucket.
        # Listar e apagar o que está lá de verdade não depende de adivinhar o nome.
        # 🪤 Varre a pasta atual E a antiga "_diagnostico": a 1ª versão gravava com
        # underscore (o job_id não passa pelo sanitizador, só o nome do arquivo).
        # Ao renomear a pasta eu quase deixei 250 MB órfãos pra sempre, porque a
        # limpeza nova só olhava o nome novo.
        apagados, erros = [], []
        for pasta in (PASTA_DIAG, "_diagnostico"):
            try:
                for n in _supabase_storage_list(PRANCHAS_BUCKET, f"{pasta}/"):
                    alvo = f"{pasta}/{_up.quote(n)}"
                    if _supabase_storage_delete(PRANCHAS_BUCKET, alvo):
                        apagados.append(f"{pasta}/{n}")
                    else:
                        erros.append(f"{pasta}/{n}")
            except Exception as e:
                erros.append(f"{pasta}: {type(e).__name__}: {e}")
        resp["apagado"] = (not erros)
        resp["apagados"] = apagados
        if erros:
            resp["erro_ao_apagar"] = "; ".join(str(x) for x in erros)
        return resp
    finally:
        if caminho:
            try:
                os.unlink(caminho)
            except Exception:
                pass


@app.get("/api/debug/dwg")
async def debug_dwg(request: Request):
    """Diagnóstico do suporte DWG. Restrito a admin (revela paths do FS)."""
    _require_admin(request)
    import shutil
    result = {
        "oda_which": shutil.which("ODAFileConverter"),
        # O Dockerfile instala libredwg-tools com "|| echo" — se o pacote não vier,
        # o build passa em silêncio e o fallback simplesmente não existe, sem ninguém
        # saber. Aqui a resposta fica explícita (null = fallback indisponível).
        "libredwg_which": shutil.which("dwg2dxf"),
        "oda_paths_checked": [],
    }
    # Verificar caminhos
    for p in ["/usr/bin/ODAFileConverter", "/usr/local/bin/ODAFileConverter",
              "/opt/ODAFileConverter/ODAFileConverter"]:
        result["oda_paths_checked"].append({"path": p, "exists": os.path.exists(p)})

    # Tentar importar dwg_extractor
    try:
        from dwg_extractor import _find_oda_converter, extract_from_file
        result["dwg_extractor_import"] = True
        oda = _find_oda_converter()
        result["oda_found_by_extractor"] = oda
    except Exception as e:
        result["dwg_extractor_import"] = False
        result["dwg_extractor_error"] = str(e)

    # libredwg (fallback open-source — opcional)
    result["libredwg_dwg2dxf"] = shutil.which("dwg2dxf")
    # Removido o find recursivo: caro (timeout) e revelador de layout do FS.

    return result


@app.get("/api/debug/oda-log/{job_id}")
async def get_oda_log(request: Request, job_id: str):
    """Retorna o log do ODA File Converter para um job.

    Restrito ao dono do projeto (ou admin) — log pode revelar nomes de
    arquivos enviados pelo usuário.
    """
    _require_project_owner(request, job_id)
    log_path = os.path.join(WORK_DIR, job_id, "_oda_log.txt")
