def frase_por_formato(f):
    """Uma linha por formato pro cartao Entrega (02/09/2026).

    Devolve None quando nao ha projeto finalizado atras do numero ou quando a
    RPC nao mandou o campo - a tela escreve 'sem medicao', nunca 0%. Funcao
    pura e separada da rota DE PROPOSITO: o guarda CHAMA isto."""
    if not isinstance(f, dict):
        return None
    fmt = str(f.get("formato") or "").strip()
    fin, mediu = f.get("total"), f.get("mediu")
    if not fmt or fin is None or mediu is None:
        return None
    try:
        fin, mediu = int(fin), int(mediu)
    except (TypeError, ValueError):
        return None
    if fin <= 0:
        return None
    return {"formato": fmt, "mediu": mediu, "finalizados": fin,
            "pct": int(round(100.0 * mediu / fin))}


def faixas_de_retorno(R):
    """As perguntas de retencao SEPARADAS por nome (02/09/2026).

    Medido: 74 clientes; 2+ projetos = 40 (54%) e isso e USO, nao retorno;
    voltou OUTRO DIA = 8 (10,8%); outra semana = 5 (6,8%). Chave que a RPC nao
    mandou vira None, nunca zero - zero e a afirmacao 'ninguem voltou'."""
    if not isinstance(R, dict):
        return None
    try:
        tot = int(R.get("clientes") or 0)
    except (TypeError, ValueError):
        return None
    if tot <= 0:
        return None

    def _p(chave):
        v = R.get(chave)
        if v is None:
            return None
        try:
            n = int(v)
        except (TypeError, ValueError):
            return None
        return {"n": n, "pct": int(round(100.0 * n / tot))}

    return {
        "clientes": tot,
        "voltou_outro_dia": _p("voltaram_outro_dia"),
        "voltou_outra_semana": _p("voltaram_outra_sem"),
        "dois_ou_mais_projetos": _p("dois_ou_mais_projetos"),
        "so_um_projeto": _p("so_um_projeto"),
    }


@app.get("/api/admin/qualidade-semanal")
def admin_qualidade_semanal(request: Request):
    """QUALIDADE DA ENTREGA por semana FIXA do calendário (admin).

    Por que existe (Pedro, 07/08/2026 — "evolução semanal de acertos"): a
    "Taxa de Sucesso" do painel responde só *"o job terminou?"*. Ela contou
    como SUCESSO o job 454200a5 daquele mesmo dia — 41 itens entregues e
    **zero medidos**. Pro cliente isso não é sucesso.

    A RPC quebra cada semana em três estados que somam 100% dos finalizados:
      mediu     → concluiu E tirou ≥1 quantidade da geometria do CAD
      sem_medir → concluiu, mas tudo veio de texto/estimativa
      erro      → falhou
    A taxa de sucesso atual é (mediu + sem_medir). A fatia `mediu` é o que
    de fato virou quantitativo.

    🪤 Critério de QUEM entra: trabalho de cliente (tem e-mail e não é o
    Pedro). NÃO filtra por `archived` — dos 72 arquivados, 59 são ruído de
    teste mas 13 são de cliente real, com 8 erros dentro; filtrar por
    arquivado apagaria fracasso que aconteceu de verdade.
    🪤 Semana FIXA, nunca janela móvel (senão número do passado muda sozinho).
    """
    _require_admin(request)
    import urllib.request as _ur
    try:
        url = f"{SUPABASE_URL}/rest/v1/rpc/admin_qualidade_semanal"
        req = _ur.Request(url, data=b"{}", method="POST")
        req.add_header("apikey", SUPABASE_KEY)
        req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        req.add_header("Content-Type", "application/json")
        d = _json.loads(_ur.urlopen(req, timeout=20).read().decode("utf-8"))
        # 02/09/2026: o Dashboard passa a usar a MESMA chamada pra formato (90d)
        # e retorno. Se a RPC ainda nao tiver o campo, `resumo` vem None e a
        # tela escreve 'sem medicao' - nunca um zero inventado.
        if isinstance(d, dict):
            _lista = d.get("por_formato_90d")
            _fmt = ([x for x in (frase_por_formato(f) for f in _lista) if x]
                    if isinstance(_lista, list) else None)
            d["resumo"] = {
                "por_formato_90d": _fmt if _fmt else None,
                "janela_formato_90d": d.get("janela_formato_90d"),
                "retorno": faixas_de_retorno(d.get("retencao")),
            }
        return d
    except Exception as _e:
        print(f"[qualidade-semanal] erro: {_e}")
        raise HTTPException(502, "Não consegui carregar a qualidade semanal")


@app.get("/api/admin/motor-health")
def admin_motor_health(request: Request):
    """Painel de SAÚDE DO MOTOR (admin): % medido por fonte (CAD vs PDF), distribuição
    de % medido por projeto, itens medidos x total e top motivos de falha. Agrega via
    RPC admin_motor_health (SECURITY DEFINER, só service_role) pra o Pedro parar de
    otimizar às cegas (board 15/07)."""
    _require_admin(request)
    import urllib.request as _ur
    try:
        url = f"{SUPABASE_URL}/rest/v1/rpc/admin_motor_health"
        req = _ur.Request(url, data=b"{}", method="POST")
        req.add_header("apikey", SUPABASE_KEY)
        req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        req.add_header("Content-Type", "application/json")
        data = _json.loads(_ur.urlopen(req, timeout=20).read().decode("utf-8"))
    except Exception as _e:
        print(f"[motor-health] erro: {_e}")
        raise HTTPException(502, "Não consegui carregar a saúde do motor")

    # #3 PDF SOMBRA: o medidor vetorial de PDF roda em modo sombra (loga em
    # error_log stage 'pdfvec:shadow') e NÃO vira item medido — o item de PDF é
    # sempre estimado por design. Este readout mostra o que o vetor TERIA medido:
    # quantos PDFs pegaram escala, quanto de cômodo/parede foi achado. É o portão
    # pra um dia graduar PDF de sombra→medido com dado, não chute (board 15/07).
    _shadow = {"n_pdfs": 0, "com_escala": 0, "pulados": 0, "rooms_m2_total": 0.0,
               "walls_m_total": 0.0, "amostras": []}
    try:
        _sq = (f"{SUPABASE_URL}/rest/v1/error_log?stage=like.pdfvec*"
               f"&select=message,job_id,created_at&order=created_at.desc&limit=120")
        _sr = _ur.Request(_sq, method="GET")
        _sr.add_header("apikey", SUPABASE_KEY)
        _sr.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        _slogs = _json.loads(_ur.urlopen(_sr, timeout=20).read().decode("utf-8"))
        for _row in _slogs:
            try:
                _pg = (_json.loads(_row.get("message") or "{}").get("pages") or [{}])[0]
            except Exception:
                continue
            _shadow["n_pdfs"] += 1
            if _pg.get("skip"):
                _shadow["pulados"] += 1
                continue
            if _pg.get("scale"):
                _shadow["com_escala"] += 1
            _rm = float(_pg.get("rooms_m2") or 0)
            _wm = float(_pg.get("walls_m") or 0)
            _shadow["rooms_m2_total"] += _rm
            _shadow["walls_m_total"] += _wm
            if (_rm > 0 or _wm > 0) and len(_shadow["amostras"]) < 8:
                _shadow["amostras"].append({
                    "job_id": _row.get("job_id"),
                    "escala": _pg.get("scale"),
                    "n_rooms": _pg.get("n_rooms") or 0,
                    "rooms_m2": round(_rm, 1),
                    "walls_m": round(_wm, 1),
                })
        _shadow["rooms_m2_total"] = round(_shadow["rooms_m2_total"], 1)
        _shadow["walls_m_total"] = round(_shadow["walls_m_total"], 1)
    except Exception as _se:
        print(f"[motor-health] pdf-shadow erro: {_se}")
    data["pdf_shadow"] = _shadow
    return data


