def _neutraliza_links_de_avaliacao(html: str) -> str:
    """Mata os links de nota de um e-mail de EXEMPLO.

    🩸 31/08 (auditoria): o preview e o "Enviar teste pra mim" montam o e-mail
    pelos MESMOS builders do envio real — então as estrelinhas saíam com token
    HMAC VÁLIDO pro par (job "exemplo-1234", "cliente@exemplo.com"). Clicar numa
    delas gravava nota de verdade em `processing_survey`, em produção, e ainda
    disparava o alerta pro admin. Numa base com 5 avaliações na história inteira,
    poluir com nota de teste é estragar o pouco que existe.
    🔑 Neutraliza por VARREDURA, não por parâmetro em cada builder: assim vale
    pros tipos de e-mail que ainda vão nascer, sem ninguém precisar lembrar.
    """
    import re as _re_prev
    return _re_prev.sub(
        r'href="[^"]*obrigado\.html\?[^"]*"',
        'href="#" title="exemplo: link desativado no teste"', html or "")


class _SemPreview(KeyError):
    """Tipo que TEM ficha no catálogo mas não tem preview (o texto nasce no
    processamento, ou mora em outra aba). Herda de KeyError pra quem só trata
    'tipo desconhecido' continuar funcionando; quem sabe distinguir diz o motivo."""


def _render_email_by_type(key: str):
    """Wrapper: monta o exemplo e MATA os links de nota antes de devolver.

    🚨 O corpo real é `_render_email_by_type_raw`, que tem uma dezena de
    `return` — envolver por fora garante que NENHUM deles escape da
    neutralização, inclusive os tipos de e-mail que ainda vão nascer."""
    subject, html = _render_email_by_type_raw(key)
    return subject, _neutraliza_links_de_avaliacao(html)


def _render_email_by_type_raw(key: str):
    """Devolve (subject, html) de um tipo de email com dados de EXEMPLO. NÃO
    envia nada. 🚫 Não chame direto: use `_render_email_by_type`, que neutraliza
    os links de avaliação. Levanta KeyError se o tipo não existe."""
    nome = "Pedro"
    projeto = "Residencial Vila Nova"
    fake_link = "https://ai.arq.br/login.html"
    fake_job = "exemplo-1234"
    if key == "boas_vindas":
        return _build_welcome_email(nome)
    if key == "planilha_pronta":
        # Exemplo dos "próximos passos" (bloco real, dados fictícios) pro preview
        # ficar representativo — sem tocar em all_items reais.
        _extra = _next_steps_html(fake_job, 30, 42, False)
        return _build_planilha_pronta_email(nome, projeto, fake_job, 42, _extra,
                                            email="cliente@exemplo.com")
    if key == "erro_reprocessar":
        return _build_falha_email(nome, projeto, True)
    if key == "erro_trocar":
        return _build_falha_email(nome, projeto, False)
    if key == "erro_nosso":
        return _build_falha_email(nome, projeto, False, culpa_nossa=True,
                                  ja_entregou=True, job_id=fake_job)
    if key == "nudge_cadastro":
        return _build_nudge_email(nome, "cadastro", fake_link)
    if key == "nudge_onboarding":
        return _build_nudge_email(nome, "onboarding", fake_link)
    if key == "feedback":
        return _build_nudge_email(nome, "feedback", fake_link)
    if key == "retorno_30d":
        return _build_retorno30_email(nome)
    if key == "nps_relacional":
        return _build_nps_relacional_email(nome, "cliente@exemplo.com", 2)
    if key == "proximo_projeto":
        return _build_proximo_projeto_email(nome, projeto)
    if key == "cronograma_checkin":
        return _build_cronograma_checkin_email(nome, projeto, 6, fake_job)
    if key == "calibracao":
        return _build_calibracao_email(nome, projeto)
    # 05/09: os que estavam "fora do catálogo" — pelo MESMO builder do envio real.
    if key == "sem_medida":
        return _build_sem_medida_email(nome, projeto, fake_job, 30, 27, "",
                                       email="cliente@exemplo.com")
    # 06/09: o TERCEIRO caso — leu e identificou, mas nao mediu nada do CAD.
    # Numeros do exemplo tirados do caso real que o revelou (job 40550d3e):
    # 124 itens, 53 em branco, ZERO medidos.
    # 🩸 22/09 (revisão): sem `so_pdf` o preview mostrava a versão do CAD —
    # "costuma ser escala" e o convite da área —, que quase ninguém recebe.
    # Medido às 15:57 de 22/09 (now() de testemunha): dos 9 leu_sem_medir com
    # job_id desde 07/09, 8 eram só-PDF e 8 tinham `pdfvec:por-prancha` no log
    # (medição vetorial, onde a área digitada não entra em linha nenhuma). O
    # exemplo é esse caso. Sem o bloco do PDF aqui, `mediu_a_prancha` fica no
    # padrão — de propósito: o preview mostra a variante mais comum, não
    # todas (a do bloco se lê no e-mail do próprio job).
    if key == "leu_sem_medir":
        return _build_leu_sem_medir_email(nome, projeto, fake_job, 124, 53, "",
                                          email="cliente@exemplo.com",
                                          so_pdf=True, area_informada_serve=False)
    if key == "boas_vindas_cadastro":
        return _build_welcome_email(nome, True, fake_link)
    if key == "convidado_area_propria":
        return _build_convidado_area_propria_email(nome, projeto, "Admin Exemplo")
    if key == "escritorio_convite":
        # o MESMO builder do envio (escritorio.py), com link de exemplo
        _as, _html, _txt = _escritorio.email_do_convite(
            "Admin Exemplo", "admin@exemplo.com", projeto, "https://ai.arq.br/convite.html#t=EXEMPLO",
            moldura=_email_wrap)
        return _as, _html
    if key in ("leitura_nova", "leitura_combinada"):
        # Exemplo com ganho E com uma prancha que piorou, pra o preview mostrar
        # o quadro de honestidade dos dois lados.
        _antes = {"medidos": 12, "itens": 38, "com_numero": 24, "pranchas": 5,
                  "por_prancha": {"A01": {"medidos": 6}, "A02": {"medidos": 6}}}
        _depois = {"medidos": 27, "itens": 46, "com_numero": 39, "pranchas": 7,
                   "por_prancha": {"A01": {"medidos": 22}, "A02": {"medidos": 5}}}
        if key == "leitura_nova":
            return _build_leitura_nova_email(nome, projeto, fake_job, _antes, _depois)
        return _build_leitura_combinada_email(nome, projeto, fake_job, _antes, _depois, [])
    _ficha = next((c for c in _EMAIL_CATALOG if c["key"] == key), None)
    if _ficha and _ficha.get("sem_preview"):
        raise _SemPreview(_ficha["sem_preview"])
    raise KeyError(key)


@app.get("/api/admin/email-render")
async def admin_email_render(request: Request, type: str = ""):
    """Renderiza (subject, html) de UM tipo de email com dados de EXEMPLO.
    Admin-only. NÃO envia nada — é só pra pré-visualizar no painel."""
    _require_admin(request)
    key = (type or "").strip()
    try:
        subject, html = _render_email_by_type(key)
    except _SemPreview as _sp:
        raise HTTPException(400, f"este tipo não tem preview: {_sp.args[0]}")
    except KeyError:
        raise HTTPException(400, f"tipo de email desconhecido: {key}")
    return {"type": key, "subject": subject, "html": html}


class TesteEmailPayload(BaseModel):
    type: str


@app.post("/api/admin/email-teste")
def admin_email_teste(payload: TesteEmailPayload, request: Request):
    """Manda UM e-mail do catálogo, com dados de exemplo, PRA O PRÓPRIO ADMIN.

    Pedro, 31/08/2026: *"manda pra mim então"* — depois de eu dizer que só
    conferi os e-mails no Chrome, e que Gmail e Outlook reescrevem CSS. Ver na
    caixa de verdade é o único teste que vale.

    🔒 O destinatário é SEMPRE `ADMIN_EMAIL`, nunca o que vier no corpo: uma
    rota que manda e-mail com HTML nosso pra endereço arbitrário viraria
    trampolim de spam com a nossa reputação de domínio. A Central de E-mails
    tinha só preview; a newsletter já tinha "enviar teste só pra mim" e este é
    o mesmo padrão, agora pra qualquer tipo do catálogo.
    """
    _require_admin(request)
    key = (payload.type or "").strip()
    try:
        subject, html = _render_email_by_type(key)
    except _SemPreview as _sp:
        raise HTTPException(400, f"este tipo não tem preview nem teste: {_sp.args[0]}")
    except KeyError:
        raise HTTPException(400, f"tipo de email desconhecido: {key}")
    ok = _send_email_smtp(ADMIN_EMAIL, f"[TESTE] {subject}", html)
    if not ok:
        # 🪤 Nunca responder "enviado" sem ter enviado — o painel diria que
        # está tudo certo e o e-mail nunca chegaria.
        # E DEIXAR RASTRO: na 1ª tentativa isto falhou e não havia NADA no
        # error_log pra dizer por quê — `_send_email_smtp` só faz `print`, que
        # morre no log do Render. Sem env de SMTP a resposta é a mesma de um
        # servidor que recusou; o painel precisa saber a diferença.
        _falta = [k for k in ("SMTP_HOST", "SMTP_USER", "SMTP_PASSWORD")
                  if not os.getenv(k)]
        _motivo = ("faltam variáveis de ambiente: " + ", ".join(_falta)) if _falta             else "o servidor de e-mail recusou a mensagem"
        _log_error("email-teste:falhou", f"tipo={key} para={ADMIN_EMAIL} — {_motivo}",
                   severity="warning")
        raise HTTPException(502, f"não enviei: {_motivo}")
    return {"status": "ok", "type": key, "para": ADMIN_EMAIL, "subject": subject}


class SuprimirPayload(BaseModel):
    email: str
    motivo: Optional[str] = ""
    tipo: str = "manual"                 # caixa_cheia | inexistente | reclamou | manual
    n_devolucoes: int = 0
    primeira_devolucao: Optional[str] = None
    ultima_devolucao: Optional[str] = None


_SUPRIMIR_TIPOS = ("caixa_cheia", "inexistente", "reclamou", "manual")


def _email_normalizado_ou_400(email: str) -> str:
    e = (email or "").strip().lower()
    if len(e) > 254 or "@" not in e[1:-1] or " " in e:
        raise HTTPException(400, "e-mail inválido")
    return e


@app.get("/api/admin/email-suprimidos")
def admin_email_suprimidos(request: Request):
    """A lista de supressão inteira (ativos e liberados), pra Central de E-mails."""
    _require_admin(request)
    st, rows = _supa_rest_service("GET", "/email_suprimidos?select=*&order=criado_em.desc", timeout=10)
    if st != 200 or rows is None:      # 🪤 vazio ≠ falhou
        raise HTTPException(502, "não consegui ler a lista de supressão agora — tente de novo")
    return {"status": "ok", "itens": rows, "ativos": sum(1 for r in rows if not r.get("liberado_em"))}


@app.post("/api/admin/email-suprimir")
def admin_email_suprimir(payload: SuprimirPayload, request: Request):
    """Põe (ou repõe) um endereço na lista de supressão. Upsert: quem tinha sido
    liberado volta a ficar bloqueado (liberado_em volta a NULL)."""
    _require_admin(request)
    e = _email_normalizado_ou_400(payload.email)
    if payload.tipo not in _SUPRIMIR_TIPOS:
        raise HTTPException(400, f"tipo: use {', '.join(_SUPRIMIR_TIPOS)}")
    corpo = {
        "email": e,
        "motivo": (payload.motivo or "").strip() or "adicionado pelo admin",
        "tipo": payload.tipo,
        "n_devolucoes": max(0, int(payload.n_devolucoes or 0)),
        "primeira_devolucao": payload.primeira_devolucao or None,
        "ultima_devolucao": payload.ultima_devolucao or None,
        "criado_por": "admin",
        "liberado_em": None,
        "liberado_por": None,
    }
    st, _ = _supa_rest_service("POST", "/email_suprimidos?on_conflict=email", body=corpo,
                               prefer="resolution=merge-duplicates,return=minimal", timeout=10)
    if st not in (200, 201, 204):
        raise HTTPException(502, "não consegui gravar na lista de supressão — tente de novo")
    _suprimidos(force=True)     # a próxima tentativa de envio já bloqueia
    return {"status": "ok", "email": e}


@app.post("/api/admin/email-liberar")
def admin_email_liberar(payload: SuprimirPayload, request: Request):
    """Libera um endereço: preenche liberado_em (o histórico fica) e o e-mail volta a sair."""
    _require_admin(request)
    e = _email_normalizado_ou_400(payload.email)
    st, _ = _supa_rest_service(
        "PATCH", f"/email_suprimidos?email=eq.{urllib.parse.quote(e)}",
        body={"liberado_em": datetime.utcnow().isoformat() + "Z", "liberado_por": "admin"},
        prefer="return=minimal", timeout=10)
    if st not in (200, 204):
        raise HTTPException(502, "não consegui liberar agora — tente de novo")
    _suprimidos(force=True)
    return {"status": "ok", "email": e}


# ── DEVOLUÇÃO (bounce): quem alimenta a lista de supressão (22/09/2026) ──────
# 🩸 A lista existe desde 05/09 e o envio JÁ a consulta — mas NADA a alimenta:
# ela tem 2 linhas, as duas postas à mão naquele dia. Medido em 22/09 pelo
# Pedro, na caixa dele: **14 devoluções em 90 dias, de 4 endereços**; 3 clientes
# ficaram sem NENHUM e-mail nosso (um deles desde julho), todos por caixa cheia,
# e 1 endereço não existe. O sistema marca esses envios como ENVIADOS — o
# servidor aceitou a mensagem; a recusa chega minutos depois, na caixa do Pedro.
# Ou seja: `email_sent_log` diz "saiu" e o cliente não recebeu. É o silêncio de
# 22/09 outra vez, por outra porta.
#
# 📏 ALCANCE (só leitura, 22/09): 622 envios pra 159 endereços em 90 dias; 8
# deles foram pros 2 endereços hoje suprimidos, e ZERO depois da supressão — a
# trava funciona, o que falta é quem a alimente. Os 2 suprimidos TÊM conta no
# site: a tela alcança quem o e-mail não alcança.
#
# 🧭 POR QUE NÃO LER A CAIXA (IMAP) — decisão pro Pedro, não minha. Ler as
# devoluções sozinho exigiria: credencial de app do Gmail dele em env var
# (segredo novo, e o repo é público), uma rotina periódica no Render (a vaga do
# motor é UMA — `JOBS_SIMULTANEOS=1`), parser de DSN/bounce report (formato
# variado por provedor) e uma regra pra separar "caixa cheia de hoje" de
# "endereço que não existe". É meio dia de trabalho e um segredo novo pra
# resolver 14 eventos em 90 dias. O caminho barato é este: o Pedro cola a lista
# que ele JÁ recebe, e o sistema faz o resto. Se as devoluções passarem de ~1
# por semana, o IMAP se paga — e aí a conta muda.
class DevolucoesPayload(BaseModel):
    emails: list = []                    # a lista colada da caixa do Pedro
    tipo: str = "caixa_cheia"
    motivo: Optional[str] = ""
    ultima_devolucao: Optional[str] = None


def _emails_da_colagem(bruto) -> list:
    """Tira endereços de um texto colado (ou de uma lista) — vírgula, ponto e
    vírgula, quebra de linha, `Nome <e-mail>`, tudo serve. Devolve em minúsculas
    e sem repetir, na ordem em que apareceram."""
    import re as _re_dev
    if isinstance(bruto, (list, tuple)):
        texto = "\n".join(str(x or "") for x in bruto)
    else:
        texto = str(bruto or "")
    vistos, saida = set(), []
    for achado in _re_dev.findall(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}", texto):
        e = achado.strip().lower()
        if e not in vistos:
            vistos.add(e)
            saida.append(e)
    return saida


@app.post("/api/admin/email-devolucoes")
def admin_email_devolucoes(payload: DevolucoesPayload, request: Request):
    """Recebe a lista de endereços que DEVOLVERAM e grava todos de uma vez.

    O Pedro cola o que a caixa dele mostra; a rota normaliza, soma a contagem de
    devoluções do que já estava lá e faz um upsert só. Devolve o que gravou e o
    que recusou — nunca 400 na lista inteira por causa de uma linha torta, que é
    o que faria ele desistir da tela e voltar pro formulário de um em um.

    🚫 Endereço INTERNO (Pedro/aliases, NOTIFY_EMAIL) é recusado: suprimir o
    destino dos alertas calaria a casa inteira, e é exatamente o tipo de linha
    que aparece numa caixa de devolução por engano."""
    _require_admin(request)
    if payload.tipo not in _SUPRIMIR_TIPOS:
        raise HTTPException(400, f"tipo: use {', '.join(_SUPRIMIR_TIPOS)}")
    alvos = _emails_da_colagem(payload.emails)
    if not alvos:
        raise HTTPException(400, "não achei nenhum endereço na lista")
    if len(alvos) > 200:
        raise HTTPException(400, "lista grande demais — mande até 200 por vez")
    recusados = [e for e in alvos
                 if _email_eh_interno(e) or e == (NOTIFY_EMAIL or "").lower()]
    alvos = [e for e in alvos if e not in recusados]
    if not alvos:
        return {"status": "ok", "gravados": [], "recusados": recusados, "n": 0}

    # 🪤 O upsert do PostgREST REESCREVE a linha inteira. Sem ler antes, um
    # endereço que já tinha 7 devoluções voltaria pra 1 e perderia a data da
    # primeira — e é justamente esse histórico que decide se vale suprimir.
    # Leitura que falha NÃO vira escrita com número inventado: 502, e o Pedro
    # tenta de novo.
    _filtro = ",".join(urllib.parse.quote(e) for e in alvos)
    st_ler, antigos = _supa_rest_service(
        "GET", f"/email_suprimidos?select=email,n_devolucoes,primeira_devolucao"
               f"&email=in.({_filtro})", timeout=10)
    if st_ler != 200 or antigos is None:
        raise HTTPException(502, "não consegui ler a lista atual — não gravei nada")
    _por_email = {str(r.get("email") or "").strip().lower(): r for r in (antigos or [])}

    _hoje = _dia_brasilia()
    _quando = (payload.ultima_devolucao or _hoje)[:10]
    corpo = []
    for e in alvos:
        _velho = _por_email.get(e) or {}
        corpo.append({
            "email": e,
            "motivo": (payload.motivo or "").strip() or f"devolução registrada em {_hoje}",
            "tipo": payload.tipo,
            "n_devolucoes": int(_velho.get("n_devolucoes") or 0) + 1,
            "primeira_devolucao": _velho.get("primeira_devolucao") or _quando,
            "ultima_devolucao": _quando,
            "criado_por": "admin:devolucao",
            "liberado_em": None,          # devolveu de novo: volta a bloquear
            "liberado_por": None,
        })
    st, _ = _supa_rest_service("POST", "/email_suprimidos?on_conflict=email", body=corpo,
                               prefer="resolution=merge-duplicates,return=minimal",
                               timeout=15)
    if st not in (200, 201, 204):
        raise HTTPException(502, "não consegui gravar as devoluções — tente de novo")
    _suprimidos(force=True)               # o próximo envio já bloqueia
    try:
        # 🔒 contagem, nunca endereço: `error_log` é técnico e o repo é público.
        _log_error("email:devolucoes",
                   f"{len(corpo)} endereço(s) suprimido(s) por devolução "
                   f"(tipo={payload.tipo}); {len(recusados)} recusado(s) por serem internos",
                   severity="info")
    except Exception:
        pass
    return {"status": "ok", "n": len(corpo), "recusados": recusados,
            "gravados": [r["email"] for r in corpo]}


_AVISOS_COM_TETO: dict = {}


def _avisar_com_teto(stage: str, msg: str, minutos: int = 15) -> None:
    """Registra um aviso de leitura no máximo uma vez a cada `minutos`.

    🪤 Sem teto, uma leitura que falha grava uma linha NOVA em `error_log` a
    cada vez que o Pedro abre a tela — e como estes stages ficam fora de
    `_STAGES_DIAGNOSTICO`, entopem justamente o painel de 40 linhas que ele usa
    pra achar erro de verdade. A falha continua visível; só não se repete.
    """
    try:
        # 🪤 A chave leva a MENSAGEM junto: com o teto só por stage, uma
        # segunda falha de causa DIFERENTE dentro dos 15 min nunca chegaria ao
        # log, e o docstring estaria prometendo o que não entrega.
        _chave = "%s|%s" % (stage, (msg or "")[:120])
        _agora = time.time()
        if _agora - float(_AVISOS_COM_TETO.get(_chave) or 0) < minutos * 60:
            return
        if len(_AVISOS_COM_TETO) > 200:      # não vira vazamento de memória
            _AVISOS_COM_TETO.clear()
        _AVISOS_COM_TETO[_chave] = _agora
        _log_error(stage, msg, severity="warning")
    except Exception:
        pass


def _email_retorno_por_tipo(dias: int = 90):
    """O que voltou depois de cada tipo de e-mail. None quando ilegível.

    🩸 Item 12 da fila (19/09/2026). A Central dizia quantos e-mails SAÍRAM e
    parava aí: em 90 dias foram 303 de reativação para 125 pessoas, e ninguém
    sabia o que tinha voltado. Medido antes de escrever esta função: das ~184
    pessoas com a janela já fechada nos tipos que falam com quem sumiu
    (retorno_30d, newsletter, calibracao, nudge_*, nps_relacional), NENHUMA
    abriu projeto novo.

    O número é `projeto novo`, e só ele — de propósito:
      · não depende de cookie. O rastro de site é cego pra 50 das 125 pessoas
        (no `retorno_30d`, 25 de 39 nunca tiveram um usage_event sequer), e
        "não vi" não pode ser servido como "não voltou";
      · a RPC conta por PESSOA (quem recebeu 3 newsletters não vale 3) e só
        com a janela FECHADA — quem recebeu ontem vai em `aguardando_7d`.

    🚫 Não é prova de causa: quem abriria o projeto de qualquer jeito entra na
    conta igual. Por isso vêm junto duas coisas: `projeto_antes_7d`, a MESMA
    janela antes do envio, e `mediana_horas_ate_o_projeto`.
    🩸 A mediana entrou porque a revisão derrubou a 1ª versão desta tela: o
    único número positivo dela era CO-PRESENÇA. `boas_vindas` marcava 72 de 95,
    e os 72 abriram o projeto 2,4 minutos depois do envio — o e-mail sai porque
    a pessoa acabou de entrar no site. "Mediana 2 min" desmente o placar
    sozinha, sem limiar inventado e sem jogar dado fora.
    🪤 E é a régua de UM objetivo: `calibracao` pede planilha revisada e
    `nps_relacional` pede resposta — nesses dois a tela não acende alarme e diz
    o motivo.
    """
    try:
        # timeout curto: é painel admin, e a ficha já sabe dizer "não sei".
        # Esperar 15 s pra descobrir que não dá é pior que cortar em 5.
        _st, _r = _supa_rest_service("POST", "rpc/admin_email_retorno",
                                     {"dias": int(dias)}, timeout=5)
        if _st >= 400 or not isinstance(_r, dict):
            _avisar_com_teto("admin:email-retorno",
                             f"não consegui ler o retorno dos e-mails (HTTP {_st}) — "
                             f"a Central vai dizer 'não sei', não zero")
            return None
        return _r
    except Exception as _e:
        _avisar_com_teto("admin:email-retorno", f"exceção lendo o retorno: {_e}")
        return None


@app.get("/api/admin/email-catalog")
def admin_email_catalog(request: Request):
    """Lista os tipos de email da Central de Emails com {key, nome, grupo,
    gatilho, volume}. `volume` = quantos já saíram (email_sent_log por kind).
    Cada ficha leva também `retorno`: o que voltou depois daquele tipo.
    Admin-only."""
    _require_admin(request)
    # O que voltou depois de cada tipo — e, no mesmo pacote, o volume.
    # 🪤 A contagem do volume puxava a tabela `email_sent_log` INTEIRA pela
    # rede, sem filtro nem limite, pra contar em Python. A RPC já lê essa
    # tabela: agora devolve `volume_total` por tipo e a rota faz UMA ida ao
    # banco em vez de duas.
    # 🪤 31/08 continua valendo: leitura falhada vira `None`, nunca 0 — "0
    # e-mails" é indistinguível de "nunca saiu nenhum".
    _retorno = _email_retorno_por_tipo(90)
    # 🪤 Ter respondido um objeto não é ter contado: um 200 com dict sem
    # `por_tipo` faria toda ficha imprimir "0 e-mails enviados" — o defeito de
    # 31/08 entrando por outra porta. Chave ausente é falha; lista vazia é
    # medição legítima.
    _leu_volume = (isinstance(_retorno, dict)
                   and isinstance(_retorno.get("por_tipo"), list))
    _por_tipo = {}
    volumes = {}
    if _leu_volume:
        for _t in (_retorno.get("por_tipo") or []):
            _k = (_t or {}).get("kind") or ""
            if _k:
                _por_tipo[_k] = _t
                volumes[_k] = int((_t or {}).get("volume_total") or 0)
    items = []
    for c in _EMAIL_CATALOG:
        items.append({**c, "volume": (int(volumes.get(c["key"], 0))
                                      if _leu_volume else None),
                      "retorno": _por_tipo.get(c["key"])})
    # 🚨 31/08 (auditoria): a Central listava só o que está no _EMAIL_CATALOG, e
    # o motor manda tipos que não estão nele — inclusive a variante que é a
    # MAIORIA das entregas. Um catálogo que esconde o que mais sai não é
    # catálogo. Os órfãos entram no fim, marcados, pra ninguém confundir com
    # tipo curado.
    _conhecidos = {c["key"] for c in _EMAIL_CATALOG}
    for _k, _v in sorted(volumes.items()):
        if _k and _k not in _conhecidos:
            items.append({"key": _k, "nome": _k, "grupo": "Fora do catálogo",
                          "gatilho": "sai pelo motor, sem ficha no catálogo",
                          "volume": _v, "orfao": True,
                          "retorno": _por_tipo.get(_k)})
    # 🪤 `orfaos_lidos`: quando a leitura cai, os tipos que o motor manda e o
    # catálogo não conhece DESAPARECEM da Central — e some justamente a lista
    # que existe pra mostrar o que ninguém curou. A tela avisa em vez de
    # deixar a ausência passar por "não há nenhum".
    return {"items": items, "volume_lido": _leu_volume,
            "retorno_lido": _leu_volume, "orfaos_lidos": _leu_volume,
            "retorno_dias": (_retorno or {}).get("dias")}


_BOOT_EM = datetime.utcnow()


def _versao_no_ar() -> dict:
    """Qual commit esta rodando, e desde quando.

    🚨 Nasceu de uma pergunta do Pedro (25/08/2026). Depois de um push, a
    unica forma de saber se o codigo novo tinha subido era abrir a tela e
    olhar o conteudo. "Subiu" era deducao, nao medicao -- e esta casa ja tem a
    regra de que "nao rodou" nao e a mesma coisa que "nao funcionou".

    O Render exporta RENDER_GIT_COMMIT no ambiente do servico. O repo e
    PUBLICO, entao o SHA nao revela nada que ja nao esteja no GitHub.

    🩤 O boot importa tanto quanto o commit: redeploy do MESMO commit nao
    muda o SHA, e sem o horario de boot nao daria pra distinguir "subiu de
    novo" de "nem tentou".
    """
    sha = (os.getenv("RENDER_GIT_COMMIT") or "").strip()
    return {
        "commit": sha[:7] or None,
        "branch": (os.getenv("RENDER_GIT_BRANCH") or "").strip() or None,
        "no_ar_desde": _BOOT_EM.isoformat(),
        "de_pe_ha_min": round((datetime.utcnow() - _BOOT_EM).total_seconds() / 60),
    }


def _memoria_do_container() -> dict:
    """Memoria do CONTAINER (cgroup), nao a do host.

    🚨 26/08/2026. O Render matou o servico por estouro de memoria as 10:19,
    no segundo em que uma cliente subiu um arquivo — e eu passei a manha
    olhando "RAM 86%" sem entender. O 86% era do HOST: o /api/health lia
    `psutil.virtual_memory()`, que num container enxerga a maquina inteira.
    Reportava **61,4 GB de total** enquanto o container do plano Pro tem **4 GB**.

    Ou seja: o unico numero que a gente tinha sobre memoria nao tinha relacao
    nenhuma com o limite que causa o OOM. Cego com o instrumento na mao.

    Le o cgroup, que e o limite de verdade:
      v2 -> /sys/fs/cgroup/memory.max        + memory.current
      v1 -> .../memory/memory.limit_in_bytes + memory.usage_in_bytes

    🪤 Nao substitui o numero do host: devolve os DOIS, com nome diferente.
    Trocar em silencio faria a serie historica mentir sem ninguem perceber.
    Fora de container (a maquina do Pedro, Windows) devolve `dentro_de_container:
    False` e so o host — e isso e informacao, nao falha.
    """
    import io as _io

    def _num(caminho):
        try:
            with _io.open(caminho, "r") as f:
                bruto = f.read().strip()
            if bruto in ("max", "-1", ""):
                return None
            v = int(bruto)
            # cgroup v1 usa um numero gigante pra "sem limite"
            return None if v <= 0 or v > (1 << 62) else v
        except Exception:
            return None

    limite = _num("/sys/fs/cgroup/memory.max")
    uso = _num("/sys/fs/cgroup/memory.current")
    versao = "v2"
    if limite is None:
        limite = _num("/sys/fs/cgroup/memory/memory.limit_in_bytes")
        uso = _num("/sys/fs/cgroup/memory/memory.usage_in_bytes")
        versao = "v1"
    if limite is None or uso is None:
        return {"dentro_de_container": False}
    mb = 1024 * 1024
    return {
        "dentro_de_container": True,
        "cgroup": versao,
        "limite_mb": round(limite / mb),
        "usado_mb": round(uso / mb),
        "usado_pct": round(100.0 * uso / limite, 1),
        "livre_mb": round((limite - uso) / mb),
    }


@app.get("/health")
async def liveness():
    """Sonda de vida pro Render. NÃO toca em banco, rede nem disco.

    🔎 26/08/2026, lendo o Render pela primeira vez: o serviço está com
    `healthCheckPath` VAZIO — a plataforma não tem como saber se o processo
    travou, e o deploy troca a instância sem esperar o app subir. E o log já
    tinha `GET /health → 404 Not Found` repetido: alguma coisa sonda esse
    caminho e leva 404 desde sempre.

    🚨 Por que NÃO usar o `/api/health` aqui: ele consulta o Supabase pra contar
    projetos do dia. Como sonda do Render isso é perigoso — uma oscilação do
    Supabase derrubaria a checagem e a plataforma entraria em laço de restart,
    transformando um problema de terceiro em queda nossa. Sonda de vida
    responde uma pergunta só: "o processo está de pé?".

    Quem quiser diagnóstico (memória, chaves, contagem) usa `/api/health`.
    """
    return {"ok": True}


@app.get("/api/health")
def health(request: Request):
    """Health check. PÚBLICO devolve só o mínimo (sonda de vida + trava de
    deploy); métricas de sistema, totais e config do motor só pra ADMIN.

    🔒 30/08/2026 (auditoria): esta rota expunha a ANÔNIMOS o nº de usuários e
    projetos, RAM/disco/CPU do container, o modelo de IA em uso, a temperatura,
    e se as chaves estão configuradas — inteligência de negócio e de infra de
    graça. Agora o payload sensível exige o mesmo login de admin do /api/admin/*.
    🪤 `jobs_em_curso`/`uploads_em_curso` CONTINUAM públicos de propósito: o
    scripts/guard_deploy.py (pre-push) os lê sem credencial pra saber se há
    cliente ativo. Não vazam nada do cliente, só a contagem."""
    # ── público: barato, nada sensível ──────────────────────────────────────
    saida = {
        "status": "healthy",
        "versao": _versao_no_ar(),
        "timestamp": datetime.utcnow().isoformat(),
        # trava de deploy (Pedro 03/08): guard_deploy.py lê estes dois sem auth.
        "jobs_em_curso": jobs.em_curso(),
        "uploads_em_curso": jobs.uploads_em_curso(),
        # formatos aceitos: capacidade do serviço, não é segredo (o site já diz).
        "features": {
            "pdf": True,
            "dxf": True,
            "dwg": shutil.which("ODAFileConverter") is not None,
        },
    }

    # admin? (checagem SOFT — não levanta; anônimo só não vê o extra)
    _is_admin = False
    try:
        _u = _get_user_from_request(request, tolerante=True)
        _is_admin = bool(_u and _u.get("email", "").lower() == ADMIN_EMAIL)
    except Exception:
        _is_admin = False
    if not _is_admin:
        return saida

    # ── daqui pra baixo: só ADMIN. Cálculo caro (psutil + Supabase) só agora ──
    try:
        import psutil
    except ImportError:
        psutil = None
    api_key = os.getenv("ANTHROPIC_API_KEY", "")
    stripe_key = os.getenv("STRIPE_SECRET_KEY", "")
    mem = psutil.virtual_memory() if psutil else None
    disk = psutil.disk_usage('/') if psutil else None

    # Contar projetos hoje — data de BRASÍLIA (meia-noite BR = 03:00 UTC), não
    # UTC: senão entre 21h e meia-noite o contador zerava e mostrava só as
    # últimas horas como "hoje".
    today_count = 0
    try:
        import urllib.request, json
        _ini_br = _hoje_br().strftime("%Y-%m-%d") + "T03:00:00"
        url = f"{SUPABASE_URL}/rest/v1/projects?select=id&created_at=gte.{_ini_br}"
        req = urllib.request.Request(url)
        req.add_header('apikey', SUPABASE_KEY)
        req.add_header('Authorization', f'Bearer {SUPABASE_SERVICE_ROLE_KEY}')
        req.add_header('Prefer', 'count=exact')
        resp = urllib.request.urlopen(req, timeout=3)
        count_header = resp.headers.get('content-range', '')
        today_count = int(count_header.split('/')[1]) if '/' in count_header else len(json.loads(resp.read()))
    except Exception:
        pass

    total_projects = None
    total_users = None
    try:
        import urllib.request, json
        def _count_table(table, coluna='id'):
            url = f"{SUPABASE_URL}/rest/v1/{table}?select={coluna}&limit=1"
            req = urllib.request.Request(url)
            req.add_header('apikey', SUPABASE_KEY)
            req.add_header('Authorization', f'Bearer {SUPABASE_SERVICE_ROLE_KEY}')
            req.add_header('Prefer', 'count=exact')
            resp = urllib.request.urlopen(req, timeout=3)
            count_header = resp.headers.get('content-range', '')
            if '/' in count_header:
                return int(count_header.split('/')[1])
            return len(json.loads(resp.read()))
        try:
            total_projects = _count_table('projects', 'id')
        except Exception as _ec:
            print(f"[health] contagem de projects falhou: {type(_ec).__name__}: {_ec}")
        try:
            total_users = _count_table('profiles', 'user_id')
        except Exception as _ec:
            print(f"[health] contagem de profiles falhou: {type(_ec).__name__}: {_ec}")
    except Exception as _eh:
        print(f"[health] contagens indisponíveis: {type(_eh).__name__}: {_eh}")

    saida["api_key_configured"] = bool(api_key and api_key.startswith("sk-"))
    saida["stripe_configured"] = bool(stripe_key)
    saida["memoria_container"] = _memoria_do_container()
    saida["system"] = {
        "ram_used_pct": round(mem.percent, 1) if mem else 0,
        "ram_used_mb": round(mem.used / 1024 / 1024) if mem else 0,
        "ram_total_mb": round(mem.total / 1024 / 1024) if mem else 0,
        "disk_used_pct": round(disk.percent, 1) if disk else 0,
        "cpu_pct": psutil.cpu_percent(interval=0.5) if psutil else 0,
    }
    saida["stats"] = {
        "projects_today": today_count,
        "total_projects": total_projects,
        "total_users": total_users,
    }
    saida["features"].update({
        "calibrator": bool(globals().get("HAS_CALIBRATOR", False)),
        "libredwg_instalado": shutil.which("dwg2dxf") is not None,
        "libredwg_ligado": os.getenv("LIBREDWG_FALLBACK", "0").strip().lower()
                           in ("1", "true", "on", "sim"),
        "dxf_extract_model": _DXF_MODEL_ATUAL,
        "dxf_temperature": (
            None if any(_t in _DXF_MODEL_ATUAL
                        for _t in ("opus-4-8", "opus-4-7", "fable"))
            else float(os.environ.get("DXF_EXTRACT_TEMP", "0.7"))),
    })
    return saida


# ── TCPO BIM: busca técnica de composições ──
@app.get("/api/tcpo/search")
async def tcpo_search(q: str, limit: int = 5):
    """Busca composições TCPO BIM por similaridade de descrição.

    Exemplo: /api/tcpo/search?q=luminaria+fluorescente&limit=5

    Retorna top N composições ordenadas por similaridade, com o 1º match
    enriquecido com a lista de insumos (material/mão de obra/equipamento).
    Usado pela UI pra permitir que o revisor busque a referência TCPO ideal
    pra cada item.
    """
    try:
        from tcpo_matcher import match_item, get_insumos
    except ImportError:
        return {"results": [], "error": "tcpo_matcher indisponível"}

    if not q or len(q.strip()) < 2:
        return {"results": []}

    matches = match_item(q.strip(), limit=min(int(limit or 5), 15))
    # Enriquece o 1º com insumos pra UI poder mostrar direto
    if matches:
        matches[0]['insumos'] = get_insumos(matches[0]['id'])
    return {"query": q, "count": len(matches), "results": matches}


@app.get("/api/tcpo/details/{composicao_id}")
async def tcpo_details(composicao_id: str):
    """Retorna detalhes completos de uma composição TCPO — todos os insumos,
    metadados (conteúdo, critério, normas). Usado quando o usuário expande uma
    referência pra ver a composição inteira.
    """
    try:
        from tcpo_matcher import get_insumos, _supabase_rpc
    except ImportError:
        return {"error": "tcpo_matcher indisponível"}

    rows = _supabase_rpc("get_tcpo_details", {"p_id": composicao_id}) or []
    if not rows:
        return {"error": "composição não encontrada"}
    return rows[0] if isinstance(rows, list) else rows


