#  CASHBACK EVENTS POR PROJETO
# ═══════════════════════════════════════════════════════════════

@app.get("/api/user/{user_id}/cashback-all")
def get_user_cashback_all(request: Request, user_id: str):
    """Retorna cashback agregado de TODOS os projetos do usuário.

    Usa pra mostrar o resumo na tela de cashback (total geral + por projeto).
    Só dono (ou admin) — saldo de cashback é dado financeiro.
    """
    jwt_user = _get_user_from_request(request)
    if not jwt_user:
        raise HTTPException(401, "Autenticação requerida")
    if jwt_user.get("id") != user_id and jwt_user.get("email", "").lower() != ADMIN_EMAIL:
        raise HTTPException(403, "Só é possível consultar seu próprio cashback")
    try:
        # Busca todos eventos do user
        url = (f"{SUPABASE_URL}/rest/v1/project_cashback_events"
               f"?user_id=eq.{user_id}"
               f"&select=*&order=created_at.desc&limit=1000")
        req = urllib.request.Request(url, method="GET")
        req.add_header("apikey", SUPABASE_KEY)
        req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        resp = urllib.request.urlopen(req, timeout=8)
        events = json.loads(resp.read().decode("utf-8"))

        # Busca nome dos projetos envolvidos
        job_ids = list({e["job_id"] for e in events})
        projects_map = {}
        if job_ids:
            ids_filter = ",".join(f'"{j}"' for j in job_ids)
            pj_url = (f"{SUPABASE_URL}/rest/v1/projects"
                      f"?job_id=in.({','.join(job_ids)})&select=job_id,project_name")
            pj_req = urllib.request.Request(pj_url, method="GET")
            pj_req.add_header("apikey", SUPABASE_KEY)
            pj_req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
            try:
                pj_resp = urllib.request.urlopen(pj_req, timeout=8)
                for p in json.loads(pj_resp.read().decode("utf-8")):
                    projects_map[p["job_id"]] = p.get("project_name", "Projeto sem nome")
            except Exception:
                pass

        # Agrupa por projeto
        from collections import defaultdict
        by_proj = defaultdict(lambda: {
            "job_id": "", "project_name": "", "total_cents": 0,
            "n_events": 0, "event_types": set(),
        })
        for e in events:
            p = by_proj[e["job_id"]]
            p["job_id"] = e["job_id"]
            p["project_name"] = projects_map.get(e["job_id"], "Projeto sem nome")
            p["total_cents"] += e.get("credit_cents", 0)
            p["n_events"] += 1
            p["event_types"].add(e.get("event_type", ""))

        by_project_list = []
        for p in by_proj.values():
            by_project_list.append({
                "job_id": p["job_id"],
                "project_name": p["project_name"],
                "total_cents": p["total_cents"],
                "n_events": p["n_events"],
                "event_types": sorted(p["event_types"]),
            })
        by_project_list.sort(key=lambda x: -x["total_cents"])

        return {
            "total_cents": sum(e.get("credit_cents", 0) for e in events),
            "n_events": len(events),
            "by_project": by_project_list,
        }
    except Exception as e:
        return {"error": str(e)}


@app.get("/api/projects-confidence")
def projects_confidence_summary(request: Request):
    """Selo de confiança em 'Meus Projetos': medido/total por projeto do usuário,
    numa query só (RPC user_project_confidence). Evita N fetches pesados de itens."""
    user = _get_user_from_request(request)
    if not user:
        raise HTTPException(401, "Autenticação requerida")
    uid = str(user.get("id") or "")
    if not uid:
        raise HTTPException(401, "Sessão inválida")
    import urllib.request as _ur
    try:
        u = f"{SUPABASE_URL}/rest/v1/rpc/user_project_confidence"
        body = _json.dumps({"p_user_id": uid}).encode("utf-8")
        r = _ur.Request(u, data=body, method="POST")
        r.add_header("apikey", SUPABASE_KEY)
        r.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        r.add_header("Content-Type", "application/json")
        rows = _json.loads(_ur.urlopen(r, timeout=15).read().decode("utf-8"))
    except Exception as _e:
        print(f"[proj-conf] erro: {_e}")
        return {"summary": {}}
    summary = {}
    for row in (rows or []):
        jid = row.get("job_id")
        if jid:
            summary[jid] = {"total": int(row.get("total") or 0), "medido": int(row.get("medido") or 0)}
    return {"summary": summary}


@app.get("/api/meus-entregaveis")
def meus_entregaveis(request: Request):
    """Tudo que já foi gerado pro usuário, de TODOS os projetos, numa chamada só.

    Alimenta as telas Downloads / Planilhas / Cronogramas / Memoriais /
    Comparativos / Revisão do painel. Sem isso, cada uma dessas telas faria
    N×(3 a 5) requests — com o teto de 50 projetos da RPC, até 250 idas ao
    servidor pra desenhar uma lista.

    Aqui são 4 consultas fixas, independente da quantidade de projetos.

    🚨 Honestidade do que é "disponível" (regra dura nº1 aplicada a entregável):
      - planilha    → `projects.planilha_gerada_em` preenchido. É o carimbo real.
      - cronograma  → existe linha em `cronogramas`. O cliente montou.
      - memorial    → o .docx nasce dos itens em qualquer projeto concluído,
                      então `disponivel` = projeto concluído; `salvo` diz se o
                      cliente já EDITOU (linha em `project_memorial`). São coisas
                      diferentes e a tela mostra as duas.
      - comparativo → `projects.comparativo_gerado_em`. Exige cotação enviada;
                      hoje ninguém tem, e a tela precisa dizer isso em vez de
                      aparecer vazia sem explicação.
    """
    user = _get_user_from_request(request)
    if not user:
        raise HTTPException(401, "Autenticação requerida")
    uid = str(user.get("id") or "")
    if not uid:
        raise HTTPException(401, "Sessão inválida")

    import urllib.request as _ur

    def _rpc(nome: str, payload: dict):
        try:
            r = _ur.Request(f"{SUPABASE_URL}/rest/v1/rpc/{nome}",
                            data=_json.dumps(payload).encode("utf-8"), method="POST")
            r.add_header("apikey", SUPABASE_KEY)
            r.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
            r.add_header("Content-Type", "application/json")
            return _json.loads(_ur.urlopen(r, timeout=15).read().decode("utf-8")) or []
        except Exception as _e:
            print(f"[entregaveis] rpc {nome} falhou: {_e}")
            return []

    # 🪤 NÃO dá pra usar a RPC list_user_projects aqui: ela devolve 21 colunas e
    # planilha_gerada_em / comparativo_gerado_em NÃO estão entre elas (conferido
    # no pg_get_functiondef em 04/08). Usando a RPC, a tela diria "nenhuma
    # planilha" pra todo mundo — e existem 156 no banco. Select direto, então.
    st_proj, projetos = _supa_rest_service(
        "GET", "/projects",
        params={
            "user_id": f"eq.{uid}",
            "select": ("job_id,project_name,typology,status,created_at,completed_at,"
                       "items_count,planilha_gerada_em,comparativo_gerado_em,archived"),
            "order": "created_at.desc",
            "limit": "200",
        })
    # 🚨 Consulta que falha NÃO pode virar "você não tem nada". Devolver lista
    # vazia com HTTP 200 faz a tela dizer, com todas as letras, que o cliente
    # nunca gerou planilha nenhuma — e ele tem. Erro tem que soar como erro.
    if st_proj != 200:
        raise HTTPException(503, "Não consegui ler seus projetos agora. Tente de novo em instantes.")
    if not projetos:
        # sem projeto não há entregável pra conferir: `conferida` é verdade
        # trivial, mas o campo tem que existir sempre — tela que lê
        # `!== false` num campo ausente decide por acaso.
        return {"status": "ok", "projetos": [], "count": 0,
                "coerencia_conferida": True}

    jobs = [str(p.get("job_id")) for p in projetos if p.get("job_id")]
    filtro = "in.(" + ",".join(f'"{j}"' for j in jobs) + ")"

    # Quem tem cronograma montado, quem tem memorial editado.
    _, crons = _supa_rest_service(
        "GET", "/cronogramas", params={"job_id": filtro, "select": "job_id,updated_at"})
    _, memos = _supa_rest_service(
        "GET", "/project_memorial", params={"job_id": filtro, "select": "job_id,updated_at"})
    cron_por_job = {str(r.get("job_id")): r.get("updated_at") for r in (crons or [])}
    memo_por_job = {str(r.get("job_id")): r.get("updated_at") for r in (memos or [])}

    # Medido × estimado, pra tela de Revisão. Mesma RPC do selo de confiança.
    conf_por_job = {}
    for row in _rpc("user_project_confidence", {"p_user_id": uid}):
        jid = row.get("job_id")
        if jid:
            conf_por_job[str(jid)] = (int(row.get("total") or 0), int(row.get("medido") or 0))

    # 🚨 Quem o cliente JÁ conferiu não pode continuar sendo cobrado.
    # 'medido' conta confidence='confirmado', e aprovar ou editar item NÃO mexe
    # em confidence — de propósito: olhar uma estimativa não a transforma em
    # medição (regra dura nº1). Só que, sem descontar o que já foi revisado, a
    # tela pede pra sempre o trabalho que a pessoa já fez: no projeto de 03/08
    # foram 28 ações e o contador seguiu em 170, igualzinho.
    # Então: 'medido' continua puro, e 'a_revisar' desconta o já conferido.
    # 🪤 DESCONTAR DUAS VEZES. A 1ª versão fazia
    #     a_revisar = total - medido - len(revisados)
    # contando TODA linha de item_reviews. Só que o cliente também confirma item
    # que já era MEDIDO — e esse item saía da conta duas vezes: uma por estar em
    # `medido`, outra por estar em `revisados`. Com 143 estimativas abertas e o
    # cliente passeando pelos medidos, o contador chegava a ZERO com o trabalho
    # todo por fazer.
    # O certo é contar diretamente o que a tela promete: ESTIMATIVA QUE AINDA
    # NÃO FOI CONFERIDA. Então precisamos dos ids dos estimados, não só do total.
    # 🚨 25/08: as duas leituras abaixo pediam `limit=20000` e o PostgREST
    # devolvia 1000. São 6107 itens não-confirmados no acervo: o funil da
    # revisão — o KPI que o Pedro lê — media 16% da base e se apresentava como
    # o todo. Mesma família do `/api/track` de 22/08. Ver `_supa_rest_tudo`.
    estimados_por_job = {}
    _, itens_est = _supa_rest_tudo(
        "/project_items",
        params={"job_id": filtro, "confidence": "neq.confirmado",
                "select": "job_id,id"})
    for r in (itens_est or []):
        jid = str(r.get("job_id") or "")
        if jid:
            estimados_por_job.setdefault(jid, set()).add(str(r.get("id")))

    revisados_por_job = {}
    _, revs = _supa_rest_tudo(
        "/item_reviews",
        params={"job_id": filtro, "select": "job_id,item_id"})
    for r in (revs or []):
        jid = str(r.get("job_id") or "")
        if jid:
            revisados_por_job.setdefault(jid, set()).add(str(r.get("item_id")))

    # 🚨 REGRA DURA nº7: mexeu no quantitativo, os entregáveis ficam velhos e o
    # site AVISA. Esse aviso existia só DENTRO da página do projeto — nestas
    # telas um cronograma desatualizado aparecia igualzinho a um atualizado, e
    # o cliente baixava e mandava pro cliente dele sem saber.
    # Reaproveita a MESMA RPC do chip de "desatualizado" em Meus Projetos:
    # devolve planilha/cronograma/memorial/comparativo por job numa consulta só.
    velho_por_job = {}
    # 🩸 08/09/2026 — O RASTRO NUNCA ERA GRAVADO, E O COMENTÁRIO ABAIXO JÁ
    # SABIA O QUE PRECISAVA ACONTECER. `coerencia:entregaveis` está no código
    # desde que esta rota nasceu e nunca disparou em produção (0 linhas em
    # 5.464 eventos do error_log). Motivo: `_supa_rest_service` NUNCA levanta —
    # devolve (código, None) ou (0, None) —, então o `except` é inalcançável, e
    # o `if _stv == 200 else ()` engolia a falha em silêncio. RPC fora do ar →
    # `velho_por_job` vazio → TODO entregável aparece atualizado nas 6 abas do
    # painel, que é o caminho mais quente da regra nº7.
    # 🔑 A falha vira DADO, não sumiço: o status é conferido onde ele é
    # conhecido, e a resposta carrega `coerencia_conferida` pra tela poder
    # dizer "não consegui conferir" em vez de esconder o aviso.
    _coer_ok = True
    _stv, _rowsv = _supa_rest_service(
        "POST", "rpc/projetos_desatualizados", {"p_user_id": uid})
    if _stv != 200 or _rowsv is None:
        _coer_ok = False
        _log_error("coerencia:entregaveis",
                   f"rpc/projetos_desatualizados HTTP {_stv} — as 6 abas do "
                   f"painel mostram TODO entregável como atualizado sem ter "
                   f"conferido", severity="warning")
    else:
        for r in (_rowsv or []):
            jid = str(r.get("job_id") or "")
            if jid:
                velho_por_job[jid] = {
                    k: bool(r.get(k)) for k in
                    ("planilha", "cronograma", "memorial", "comparativo")
                }

    saida = []
    for p in projetos:
        jid = str(p.get("job_id") or "")
        if not jid:
            continue
        concluido = (p.get("status") == "done")
        total, medido = conf_por_job.get(jid, (0, 0))
        saida.append({
            "job_id": jid,
            "nome": p.get("project_name") or "Projeto sem nome",
            "status": p.get("status"),
            "tipologia": p.get("typology"),
            "criado_em": p.get("created_at"),
            "concluido_em": p.get("completed_at"),
            # Arquivado (90 dias) perde o arquivo no Storage. A tela precisa
            # mostrar cinza e explicar, nunca oferecer um download que dá 404.
            "arquivado": bool(p.get("archived")),
            # 🪤 `items_count` é contador GUARDADO na tabela projects e mente:
            # 12 projetos concluídos dizem ter item (de 6 a 144) e têm ZERO
            # linha em project_items — conferido no banco em 05/08. O menu
            # lateral usava esse número pra decidir o selo da Revisão e pintava
            # "ok" VERDE ("está conferido") num projeto sem item nenhum.
            # `total` vem da RPC user_project_confidence, que CONTA as linhas.
            "itens": total,
            "medido": medido,
            # Estimativa que o cliente ainda NÃO conferiu — a interseção, não a
            # subtração. Confirmar item medido não mexe neste número, porque
            # item medido nunca esteve aqui dentro.
            "revisados": len(estimados_por_job.get(jid, set())
                             & revisados_por_job.get(jid, set())),
            "a_revisar": len(estimados_por_job.get(jid, set())
                             - revisados_por_job.get(jid, set())),
            "entregaveis": {
                "planilha": {
                    # 🚨 Carimbo NÃO é arquivo. _carimbar_planilha roda ANTES do
                    # upload pro Storage e antes de status='done'; se o servidor
                    # reinicia nessa janela, sobra carimbo sem arquivo nenhum.
                    # Medido em produção 04/08: 88 projetos em erro, 54 com
                    # carimbo, e 7 não arquivados sem arquivo no bucket. Sem o
                    # status aqui, a tela listava a planilha de um projeto que
                    # nunca funcionou e o botão Baixar devolvia 404.
                    "disponivel": bool(p.get("planilha_gerada_em")) and concluido,
                    "em": p.get("planilha_gerada_em"),
                    "desatualizado": bool(velho_por_job.get(jid, {}).get("planilha")),
                },
                "cronograma": {
                    "disponivel": jid in cron_por_job,
                    "em": cron_por_job.get(jid),
                    "desatualizado": bool(velho_por_job.get(jid, {}).get("cronograma")),
                },
                "memorial": {
                    "disponivel": concluido,
                    "salvo": jid in memo_por_job,
                    "em": memo_por_job.get(jid),
                    "desatualizado": bool(velho_por_job.get(jid, {}).get("memorial")),
                },
                "comparativo": {
                    "disponivel": bool(p.get("comparativo_gerado_em")),
                    "em": p.get("comparativo_gerado_em"),
                    "desatualizado": bool(velho_por_job.get(jid, {}).get("comparativo")),
                },
            },
        })

    # 🔑 `coerencia_conferida=False` diz que os selos de "desatualizado" desta
    # resposta NÃO foram conferidos — sem isso, "não consegui" chega na tela
    # igualzinho a "está tudo em dia" (o defeito de 08/09).
    return {"status": "ok", "projetos": saida, "count": len(saida),
            "coerencia_conferida": _coer_ok}


@app.get("/api/projects/{job_id}/cashback")
def get_project_cashback(job_id: str, request: Request):
    """Retorna eventos de cashback + total acumulado desse projeto.

    Ownership check adicionado em 2026-05-27: antes o endpoint ficava
    aberto — qualquer um com job_id válido lia o saldo. Não é PII forte,
    mas vazava histórico financeiro do projeto. Bug bônus achado durante
    auditoria RLS/REST (commit b5ddd07).
    """
    _require_project_owner(request, job_id)
    try:
        status, events = _supa_rest_as_user(
            request, "GET",
            f"project_cashback_events?job_id=eq.{job_id}"
            f"&select=*&order=created_at.desc"
        )
        if status >= 400 or events is None:
            return {"error": f"HTTP {status}", "events": [], "total_cents": 0,
                    "total_reais": 0.0, "count": 0}
        total_cents = sum(e.get("credit_cents", 0) for e in events)
        return {
            "events": events,
            "total_cents": total_cents,
            "total_reais": total_cents / 100.0,
            "count": len(events),
        }
    except Exception as e:
        return {"error": str(e)}


