#  COERÊNCIA ENTRE OS ENTREGÁVEIS  (regra do Pedro, 02/08/2026)
#  Planilha, cronograma, memorial e comparativo de fornecedores saem
#  do MESMO quantitativo. Mexeu no quantitativo, os outros envelheceram
#  — e o cliente tem que ficar sabendo, não descobrir na obra. Aqui a
#  gente detecta e avisa; refazer é sempre escolha dele (memorial e
#  cronograma têm edição manual dentro, ninguém sobrescreve o trabalho
#  do cliente sozinho; planilha e comparativo são 100% derivados, então
#  esses dois ganham botão direto).
#  🪤 Entregável NOVO entra aqui no mesmo commit em que nasce. O
#  comparativo provou o custo de esquecer: nasceu antes da regra e
#  ficou 1 dia de fora (fechado em 03/08/2026, antes do primeiro uso
#  real — a tabela de cotações ainda estava vazia).
# ═══════════════════════════════════════════════════════════════

def _revisoes_depois_de(job_id: str, quando: str) -> dict:
    """Quantos itens foram editados/excluídos depois de `quando` (ISO). É o
    'o que mudou' que a assinatura sozinha não conta."""
    import urllib.parse
    out = {"editados": 0, "excluidos": 0}
    if not quando:
        return out
    _st, _rows = _supa_rest_service(
        "GET",
        f"item_reviews?job_id=eq.{urllib.parse.quote(job_id)}"
        f"&reviewed_at=gt.{urllib.parse.quote(quando)}"
        f"&action=in.(edit,reject)&select=action,item_id")
    if _st != 200 or not isinstance(_rows, list):
        return out
    # Mesmo item mexido 3× continua sendo 1 item mudado.
    editados, excluidos = set(), set()
    for r in _rows:
        (excluidos if r.get("action") == "reject" else editados).add(r.get("item_id"))
    out["editados"] = len(editados - excluidos)
    out["excluidos"] = len(excluidos)
    return out


def _frase_mudanca(m: dict) -> str:
    p = []
    if m.get("editados"):
        n = m["editados"]
        p.append(f"{n} item corrigido" if n == 1 else f"{n} itens corrigidos")
    if m.get("excluidos"):
        n = m["excluidos"]
        p.append(f"{n} item excluído" if n == 1 else f"{n} itens excluídos")
    return " e ".join(p)


def _coerencia_do_financeiro(job_id: str) -> dict:
    """Quantos lançamentos do financeiro da obra apontam pra item do quantitativo que
    mudou de quantidade, saiu da planilha ou ficou ambíguo — pela MESMA régua do GET da
    tela (`_fin_estado_da_origem`). Regra nº7: o financeiro nasceu do quantitativo em
    05/09 e entra no aviso de coerência do projeto. Leitura falhando devolve
    `indisponivel` — nunca "está tudo em dia" por engano."""
    import urllib.parse
    jq = urllib.parse.quote(job_id)
    st, rows = _supa_rest_service(
        "GET", f"/financeiro_lancamentos?job_id=eq.{jq}&escopo=eq.obra"
               "&select=id,origem,origem_ref_id,origem_ref_pos,origem_quantidade,origem_unidade,descricao",
        timeout=8)
    if st != 200 or rows is None:
        return {"existe": False, "desatualizado": False, "indisponivel": True}
    if not rows:
        return {"existe": False, "desatualizado": False}
    base = {"existe": True, "n": len(rows)}
    do_quant = [l for l in rows if l.get("origem") == "quantitativo"]
    if not do_quant:
        return {**base, "desatualizado": False, "mudados": 0, "removidos": 0, "ambiguos": 0, "frase": ""}
    st2, itens = _supa_rest_service(
        "GET", f"/project_items?job_id=eq.{jq}&select=id,description,quantity,unit", timeout=8)
    if st2 != 200 or itens is None or len(itens) >= 1000:
        return {**base, "desatualizado": False, "indisponivel": True}
    por_id = {str(i.get("id")): i for i in itens}
    por_desc = {}
    for i in itens:
        por_desc.setdefault(_fin_norm(i.get("description")), []).append(i)
    contagem = {"mudou": 0, "removido": 0, "ambiguo": 0}
    for l in do_quant:
        est = (_fin_estado_da_origem(l, por_id, por_desc) or {}).get("origem_estado")
        if est in contagem:
            contagem[est] += 1
    partes = []
    if contagem["mudou"]:
        partes.append(f"{contagem['mudou']} com item que mudou de quantidade")
    if contagem["removido"]:
        partes.append(f"{contagem['removido']} com item que saiu da planilha")
    if contagem["ambiguo"]:
        partes.append(f"{contagem['ambiguo']} com item repetido na planilha")
    n_velhos = sum(contagem.values())
    return {**base, "desatualizado": n_velhos > 0, "n_velhos": n_velhos,
            "mudados": contagem["mudou"], "removidos": contagem["removido"], "ambiguos": contagem["ambiguo"],
            "frase": " e ".join(partes)}


def _coerencia_do_projeto(job_id: str) -> dict:
    """Estado de sincronia dos entregáveis do projeto: planilha, cronograma,
    memorial, comparativo de fornecedores e financeiro da obra."""
    import urllib.parse
    # 🩸 08/09/2026 — A REGRA Nº7 FALHAVA CALADA, E ISSO FOI PROVADO RODANDO.
    # O log `coerencia:projeto` existe desde 02/08 e NUNCA disparou em produção
    # (0 linhas em 5.464 eventos). Não por sorte: o `except` da rota é
    # inalcançável, porque TODO ajudante aqui engole a própria falha e devolve
    # valor benigno — `_assinatura_atual` devolve "", `_supabase_get_cronograma`
    # devolve None, `_supa_rest_service` nunca levanta.
    # Medido com o Supabase 100% fora do ar (URLError, HTTP 500 e conexão
    # resetada, os três):
    #     tudo_em_dia=True  desatualizados=[]  erro=None  logs=0
    # Ou seja: "não consegui conferir" saía IDÊNTICO a "está tudo em dia", e o
    # cliente baixava cronograma e memorial velhos pra mandar pro cliente dele.
    # 🪤 Pior que o silêncio total é a falha PARCIAL: com a leitura do memorial
    # caindo e a planilha velha, a resposta vinha `desatualizados=['planilha']`
    # — o memorial simplesmente SUMIA da lista. A resposta parece saudável.
    # 🔑 Agora cada leitura que falha marca o entregável como `indisponivel` e
    # deixa rastro NO PONTO em que a falha é conhecida, não num except que não
    # roda. `conferido` diz se dá pra confiar na resposta inteira.
    _indisponiveis: list = []

    def _nao_consegui(nome: str, detalhe: str) -> dict:
        _indisponiveis.append(nome)
        _log_error("coerencia:projeto", f"{nome}: {detalhe}", job_id=job_id,
                   severity="warning")
        return {"existe": False, "desatualizado": False, "indisponivel": True}

    atual = _assinatura_atual(job_id)

    def _avaliar(nome: str, row: Optional[dict]) -> dict:
        if not row:
            return {"existe": False, "desatualizado": False}
        quando = row.get("updated_at") or row.get("created_at") or ""
        salva = row.get("itens_assinatura")
        mudancas = _revisoes_depois_de(job_id, quando)
        # Duas provas independentes. A assinatura pega qualquer diferença de
        # números; a contagem de revisões cobre os entregáveis antigos, salvos
        # antes de existir assinatura (8 cronogramas em 02/08/2026).
        por_assinatura = bool(atual and salva and salva != atual)
        por_revisao = bool(mudancas["editados"] or mudancas["excluidos"])
        return {
            "existe": True,
            "desatualizado": por_assinatura or por_revisao,
            "em": quando,
            "mudancas": mudancas,
            "frase": _frase_mudanca(mudancas),
        }

    _st, _mem = _supa_rest_service(
        "GET", f"project_memorial?job_id=eq.{urllib.parse.quote(job_id)}"
               f"&select=updated_at,itens_assinatura&limit=1")
    if _st != 200 or _mem is None:
        memorial = _nao_consegui("memorial", f"project_memorial HTTP {_st}")
    else:
        memorial = _avaliar("memorial", (_mem or [None])[0] if _mem else None)
    # 🪤 `_fin_cronograma_salvo` e não `_supabase_get_cronograma`: a docstring
    # daquele diz, com todas as letras, que este ENGOLE "não existe" e "não
    # consegui ler" no mesmo None. A régua com status já existia — usar a que
    # existe em vez de reimplementar.
    _st_cron, _cron_row = _fin_cronograma_salvo(None, job_id)
    if _st_cron != 200:
        cronograma = _nao_consegui("cronograma", f"cronogramas HTTP {_st_cron}")
        _cron_row = None
    else:
        cronograma = _avaliar("cronograma", _cron_row)
    # 🪤 Cronograma com valor informado NÃO é só prazo — é dinheiro. Quando o
    # quantitativo muda, as durações mudam, o rateio muda e o DESEMBOLSO por mês
    # muda junto. Avisar só "o cronograma ficou velho" faria o cliente achar que
    # é questão de data e mandar pro banco um desembolso errado. Regra nº7:
    # o aviso tem que dizer o que de fato mudou.
    try:
        _fases_salvas = (_cron_row or {}).get("fases_custom") or []
        cronograma["tem_financeiro"] = any(
            float(f.get("valor_previsto") or 0) > 0
            for f in _fases_salvas if isinstance(f, dict))
    except Exception:
        cronograma["tem_financeiro"] = False

    # A planilha .xlsx é servida de arquivo salvo — envelhece igual aos outros.
    _st, _prj = _supa_rest_service(
        "GET", f"projects?job_id=eq.{urllib.parse.quote(job_id)}"
               f"&select=planilha_assinatura,planilha_gerada_em,"
               f"comparativo_assinatura,comparativo_gerado_em&limit=1")
    # 🪤 UMA leitura alimenta DOIS entregáveis: se ela cai, os dois ficam sem
    # resposta. Antes os dois saíam como "em dia" — dois avisos sumindo de uma
    # vez, e nada no log.
    _prj_falhou = (_st != 200 or _prj is None)
    _row = (_prj or [None])[0] if not _prj_falhou and _prj else None
    if _prj_falhou:
        planilha = _nao_consegui("planilha", f"projects HTTP {_st}")
    else:
        planilha = _avaliar("planilha", {
            "updated_at": _row.get("planilha_gerada_em"),
            "itens_assinatura": _row.get("planilha_assinatura"),
        } if _row and _row.get("planilha_gerada_em") else None)

    # O comparativo de fornecedores também sai daqui: ele confronta as cotações
    # contra os itens do quantitativo e fica salvo no Storage. Entrou na regra
    # em 03/08/2026 — nasceu antes dela e tinha ficado de fora.
    if _prj_falhou:
        # mesma leitura, mesma sorte — mas sem um 2º log dizendo a mesma coisa
        _indisponiveis.append("comparativo")
        comparativo = {"existe": False, "desatualizado": False, "indisponivel": True}
    else:
        comparativo = _avaliar("comparativo", {
            "updated_at": _row.get("comparativo_gerado_em"),
            "itens_assinatura": _row.get("comparativo_assinatura"),
        } if _row and _row.get("comparativo_gerado_em") else None)

    # O financeiro da obra (05/09/2026) nasce do quantitativo: cada linha guarda o retrato do
    # item de origem e a tela marca "item mudou / saiu". Aqui a mesma régua chega ao painel do
    # projeto — regra nº7: entregável novo entra no aviso no dia em que nasce.
    try:
        financeiro = _coerencia_do_financeiro(job_id)
    except Exception as e:
        _log_error("coerencia:financeiro", str(e), job_id=job_id, severity="warning")
        financeiro = {"existe": False, "desatualizado": False, "indisponivel": True}

    if financeiro.get("indisponivel") and "financeiro" not in _indisponiveis:
        _indisponiveis.append("financeiro")
    desatualizados = [n for n, v in (("planilha", planilha),
                                     ("cronograma", cronograma),
                                     ("memorial", memorial),
                                     ("comparativo", comparativo),
                                     ("financeiro", financeiro)) if v.get("desatualizado")]
    return {
        "assinatura": atual,
        "planilha": planilha,
        "cronograma": cronograma,
        "memorial": memorial,
        "comparativo": comparativo,
        "financeiro": financeiro,
        "desatualizados": desatualizados,
        "tudo_em_dia": not desatualizados,
        # 🔑 `tudo_em_dia` continua respondendo "algum entregável está velho?".
        # `conferido` responde outra pergunta, que a tela precisava e não tinha:
        # "dá pra confiar nesta resposta?". Sem os dois, "não consegui conferir"
        # e "está tudo em dia" chegavam idênticos na tela.
        "conferido": not _indisponiveis,
        "indisponivel": sorted(set(_indisponiveis)),
    }


@app.get("/api/projetos/desatualizados")
def projetos_desatualizados(request: Request):
    """Lista, de uma vez, os projetos do usuário logado com entregável velho —
    pro chip de aviso em Meus Projetos. Uma consulta pra todos: recalcular a
    assinatura projeto por projeto significaria reler os itens de cada um."""
    user = _get_user_from_request(request)
    if not user or not user.get("id"):
        raise HTTPException(401, "Autenticação requerida")
    try:
        _st, _rows = _supa_rest_service(
            "POST", "rpc/projetos_desatualizados", {"p_user_id": user["id"]})
        if _st != 200 or not isinstance(_rows, list):
            # Devolver lista vazia calado esconderia permissão errada no RPC:
            # o chip some e parece que está tudo em dia. Registra pra aparecer
            # no error_log em vez de virar "funcionou".
            _log_error("coerencia:lista", f"RPC {_st}: {str(_rows)[:300]}")
            return {"projetos": []}
        return {"projetos": _rows}
    except Exception as e:
        _log_error("coerencia:lista", str(e))
        return {"projetos": []}


@app.get("/api/projeto/{job_id}/coerencia")
async def projeto_coerencia(job_id: str, request: Request):
    """Diz quais entregáveis salvos ficaram velhos depois que o cliente mexeu
    no quantitativo. Só leitura — quem refaz é o cliente, com um clique."""
    _require_project_owner(request, job_id)
    try:
        return _coerencia_do_projeto(job_id)
    except Exception as e:
        # Nunca derruba a tela por causa do aviso: sem resposta confiável, o
        # front simplesmente não mostra banner nenhum. Mas registra — "nenhum
        # aviso" por falha é indistinguível de "está tudo em dia".
        _log_error("coerencia:projeto", str(e), job_id=job_id)
        _vazio = {"existe": False, "desatualizado": False}
        return {"assinatura": "", "planilha": _vazio, "cronograma": _vazio,
                "memorial": _vazio, "comparativo": _vazio, "financeiro": _vazio,
                "desatualizados": [], "tudo_em_dia": True, "erro": True}


