class StatusPayload(BaseModel):
    user_status: str


@app.post("/api/project/{job_id}/status")
def update_project_user_status(job_id: str, payload: StatusPayload, request: Request):
    """Atualiza o status editável do projeto (em_analise, enviado_cliente,
    aprovado, fechado, arquivado)."""
    _require_project_owner(request, job_id)
    import urllib.request, urllib.error, json
    valid = {"em_analise", "enviado_cliente", "aprovado", "fechado", "arquivado"}
    if payload.user_status not in valid:
        raise HTTPException(400, f"status inválido. Aceito: {valid}")
    try:
        url = f"{SUPABASE_URL}/rest/v1/rpc/update_user_status"
        body = json.dumps({
            "p_job_id": job_id,
            "p_user_status": payload.user_status,
        }).encode('utf-8')
        req = urllib.request.Request(url, data=body, method='POST')
        req.add_header('apikey', SUPABASE_KEY)
        req.add_header('Authorization', f'Bearer {SUPABASE_SERVICE_ROLE_KEY}')
        req.add_header('Content-Type', 'application/json')
        resp = urllib.request.urlopen(req, timeout=15)
        return {"status": "ok", "user_status": payload.user_status}
    except Exception as e:
        raise HTTPException(500, f"Erro: {e}")


class FaltouPayload(BaseModel):
    texto: str
    reviewed_by: Optional[str] = ""


@app.post("/api/items/{job_id}/faltou")
def registrar_item_faltando(job_id: str, payload: FaltouPayload, request: Request):
    """O cliente diz que a planilha ESQUECEU alguma coisa.

    🩸 05/09/2026 — MEDIDO: **0 em 413 ações de revisão**. Não porque ninguém
    quis: porque não havia como dizer. A tela de revisão só deixa aprovar,
    editar e excluir — as três coisas que se fazem com um item que EXISTE.
    Item que falta não tem onde ser apontado.
    🔑 É a única pergunta de COBERTURA que existe. Sem ela a gente mede o quanto
    o motor erra no que entregou, e fica cego no que ele nem viu — e "o que o
    motor não viu" é metade da qualidade de um quantitativo.

    🚫 NÃO cria item, NÃO mexe em `items_count`, NÃO entra no quantitativo.
    Regra nº7: se entrasse, cronograma, memorial e comparativo ficariam velhos
    na hora — e a gente estaria deixando o cliente escrever quantidade sem
    medição nenhuma, que é a regra nº1 pelo avesso. Isto é RECADO, não linha.

    Mora em `item_reviews` com `item_id` NULO — forma que a tabela já tem (as
    48 exclusões são assim, porque a FK é ON DELETE CASCADE).
    """
    _require_project_owner(request, job_id)
    texto = (payload.texto or "").strip()
    if not texto:
        raise HTTPException(400, "Escreva o que faltou na planilha.")
    if len(texto) > 2000:
        texto = texto[:2000]

    linha = {
        "job_id": job_id,
        "item_id": None,
        "action": "faltou",
        "comment": texto,
        "reviewed_by": (payload.reviewed_by or "")[:120],
    }
    # 🪤 CONFERE O RETORNO. `_supabase_insert` devolve False em falha e só
    # registra num arquivo local do Render, que some no redeploy — foi
    # exatamente esse buraco que escondeu a perda total de itens por 4 meses
    # (`2e96daf`, 04/09). Um "faltou" perdido calado é PIOR que não ter botão:
    # o cliente sai achando que contou, e a gente nunca soube.
    if not _supabase_insert("item_reviews", linha):
        _log_error("revisao:faltou-nao-gravou",
                   f"o cliente apontou item faltando e a gravação FALHOU. "
                   f"Texto perdido: {texto[:300]}",
                   job_id, severity="critical")
        raise HTTPException(500, "Não consegui salvar seu recado. Tenta de novo?")

    _log_error("revisao:faltou-item",
               f"o cliente apontou item faltando: {texto[:300]}",
               job_id, severity="info")
    return {"status": "ok"}


class NotePayload(BaseModel):
    note: str
    author: Optional[str] = ""


@app.post("/api/items/{job_id}/note/{item_id}")
def save_item_note(job_id: str, item_id: str, payload: NotePayload, request: Request):
    """Salva (upsert) nota de um item. Vazio deleta a nota."""
    _require_project_owner(request, job_id)
    import urllib.request, urllib.error, json
    text = (payload.note or "").strip()
    try:
        if not text:
            # Delete
            _supa_rest_as_user(
                request, "DELETE",
                f"/item_notes?item_id=eq.{item_id}&job_id=eq.{job_id}",
                timeout=10,
            )
            return {"status": "ok", "deleted": True}

        # Upsert: try update first, insert on 0 rows
        patch_body = {
            "note": text,
            "author": payload.author or "",
            "updated_at": datetime.utcnow().isoformat(),
        }
        _, rows = _supa_rest_as_user(
            request, "PATCH",
            f"/item_notes?item_id=eq.{item_id}&job_id=eq.{job_id}",
            body=patch_body, prefer="return=representation", timeout=10,
        )
        rows = rows or []
        if not rows:
            # Insert novo
            _supabase_insert("item_notes", {
                "job_id": job_id,
                "item_id": item_id,
                "note": text,
                "author": payload.author or "",
            })
        return {"status": "ok", "saved": True}
    except Exception as e:
        raise HTTPException(500, f"Erro: {e}")


@app.get("/api/items/{job_id}/notes")
def list_job_notes(job_id: str, request: Request):
    _require_project_owner(request, job_id)
    """Lista todas as notas de itens de um job — restaura estado na revisão."""
    import urllib.request, urllib.error, json
    try:
        url = f"{SUPABASE_URL}/rest/v1/rpc/list_item_notes"
        body = json.dumps({"p_job_id": job_id}).encode('utf-8')
        req = urllib.request.Request(url, data=body, method='POST')
        req.add_header('apikey', SUPABASE_KEY)
        req.add_header('Authorization', f'Bearer {SUPABASE_SERVICE_ROLE_KEY}')
        req.add_header('Content-Type', 'application/json')
        resp = urllib.request.urlopen(req, timeout=15)
        notes = json.loads(resp.read().decode('utf-8'))
        # Retorna como mapa {item_id: {note, author, updated_at}}
        state = {n["item_id"]: {
            "note": n.get("note", ""),
            "author": n.get("author", ""),
            "updated_at": n.get("updated_at"),
        } for n in notes}
        return {"status": "ok", "notes": state}
    except Exception as e:
        raise HTTPException(500, f"Erro: {e}")


@app.get("/api/projects/by-user/{user_id}")
def list_my_projects(user_id: str, request: Request):
    """Lista projetos de um usuário (pra tela 'Meus projetos').
    Usa RPC list_user_projects (SECURITY DEFINER).

    Auth: sempre exige JWT Bearer do próprio usuário (ou admin).
    28/07/2026: 'anonymous' deixou de ser livre — listava os 53 projetos órfãos
    do começo do beta, com nome de projeto de cliente real, sem login."""
    user = _get_user_from_request(request)
    if not user:
        raise HTTPException(401, "Autenticação requerida")
    is_admin = user.get("email", "").lower() == ADMIN_EMAIL
    if user_id == "anonymous" and not is_admin:
        raise HTTPException(403, "Lista indisponível")
    if user_id != "anonymous" and user.get("id") != user_id and not is_admin:
        raise HTTPException(403, "Só é possível listar seus próprios projetos")
    import urllib.request, urllib.error, json
    try:
        url = f"{SUPABASE_URL}/rest/v1/rpc/list_user_projects"
        body = json.dumps({"p_user_id": user_id}).encode('utf-8')
        req = urllib.request.Request(url, data=body, method='POST')
        req.add_header('apikey', SUPABASE_KEY)
        req.add_header('Authorization', f'Bearer {SUPABASE_SERVICE_ROLE_KEY}')
        req.add_header('Content-Type', 'application/json')
        resp = urllib.request.urlopen(req, timeout=15)
        projects = json.loads(resp.read().decode('utf-8'))
        saida = {"status": "ok", "user_id": user_id, "projects": projects,
                 "count": len(projects)}
        # 🩸 22/09/2026 — O CLIENTE SUPRIMIDO NÃO SABIA. A lista de supressão
        # cala TODO e-mail daquele endereço (é o desenho, e está certo: 14
        # devoluções em 90 dias pesam na reputação do remetente), mas ninguém
        # contava isso pra ele — ele só parava de receber "sua planilha está
        # pronta" e achava que a casa tinha sumido. Medido: 3 clientes ficaram
        # sem NENHUM e-mail nosso, um desde julho. Os suprimidos de hoje têm
        # conta: a TELA alcança quem o e-mail não alcança.
        # 🪤 Só pro DONO da conta, e vindo do token — nunca do `user_id` da URL.
        # E falha ABERTA: lista ilegível não pode derrubar a tela de projetos.
        try:
            _meu = (user.get("email") or "").strip().lower()
            if _meu and user.get("id") == user_id:
                _ficha_sup = _email_suprimido_ficha(_meu)
                if _ficha_sup:
                    saida["entrega_email"] = {
                        "suprimido": True,
                        "tipo": _ficha_sup.get("tipo") or "manual",
                        "desde": _ficha_sup.get("desde"),
                        "ultima_devolucao": _ficha_sup.get("ultima_devolucao"),
                    }
        except Exception as _es:
            print(f"[email] ficha de supressão do dono falhou (nao-fatal): {_es}")
        return saida
    except Exception as e:
        raise HTTPException(500, f"Erro ao buscar projetos: {str(e)}")


