class NPSPayload(BaseModel):
    user_id: str
    score: int                               # 0-10
    comment: Optional[str] = ""
    context: Optional[str] = "manual"        # 'after_download' | 'after_review' | 'manual' | 'first_project'
    user_email: Optional[str] = ""
    user_name: Optional[str] = ""
    job_id: Optional[str] = ""


class NPSDetailedPayload(BaseModel):
    recommend: int                           # 0-10 (NPS clássico)
    stage_ratings: dict = {}                 # {"upload":1-5, "tempo":1-5, "precisao":1-5, "planilha":1-5}
    comment: Optional[str] = ""
    job_id: Optional[str] = ""


@app.post("/api/nps")
async def submit_nps(payload: NPSPayload, request: Request):
    """Registra uma resposta NPS. Score 0-10 obrigatório, comentário opcional.

    🚨 IDENTIDADE VEM DO TOKEN, não do corpo (conserto 09/08). Antes a rota não
    recebia `request` e gravava o `user_id`/`user_email` que viessem no JSON —
    qualquer um podia lançar NPS em nome de qualquer cliente. NPS é número de
    decisão; contaminá-lo é barato pra quem quer e caro pra nós.
    🪤 Não quebra ninguém: os dois chamadores (dashboard.html:4882 e
    projeto.html:2596) usam `authFetch`, que já manda o Bearer."""
    if payload.score < 0 or payload.score > 10:
        raise HTTPException(400, "score deve estar entre 0 e 10")

    _u = _get_user_from_request(request)
    if not _u:
        raise HTTPException(401, "sessão inválida — entre de novo pra enviar sua nota")

    row = {
        "user_id": _u["id"],
        "user_email": _u["email"] or "",
        "user_name": payload.user_name or "",
        "score": int(payload.score),
        "comment": (payload.comment or "")[:2000],
        "context": (payload.context or "manual")[:50],
        "job_id": payload.job_id or "",
    }
    ok = _supabase_insert("nps_responses", row)
    category = "promoter" if payload.score >= 9 else "passive" if payload.score >= 7 else "detractor"
    # 🩸 31/08/2026 — ANTES daqui só o detrator avisava. O cliente-13 deu 9 em
    # 24/08 com o comentário "Gostei muito do resultado" e o Pedro descobriu
    # em 31/08, sete dias depois, olhando o painel por acaso. Com 5 respostas
    # em toda a história, perder UMA é perder 20% do sinal.
    _alerta_nps(row, category)
    return {"status": "ok" if ok else "error", "category": category}


#: O que a página do PROJETO realmente pergunta. Ela NÃO mostra uma régua de
#: 0 a 10: mostra três botões, e o número é tradução NOSSA (projeto.html:441-443).
_NPS_BOTOES_DO_PROJETO = {9: "👍 Ajudou bastante", 7: "😐 Mais ou menos",
                          2: "👎 Não muito"}


def _nps_rotulo(score, context: str) -> str:
    """O que a pessoa CLICOU — não o número que a gente guardou.

    🩸 02/09/2026, caso cliente-19. Ele clicou "😐 Mais ou menos" na página do
    projeto e o alerta chegou pro Pedro dizendo **"Nota: 7/10"**. O Pedro lê
    isso como "ele deu sete", quando o cliente disse "mais ou menos" — que é
    informação diferente e mais pobre.

    🪤 São DUAS telas gravando na MESMA coluna `score`:
      · `after_download` → o widget do dashboard, com os 11 botões de 0 a 10.
        Nota de verdade.
      · `after_project`  → três botões (9/7/2). Escala de 3 pontos.
    Das 6 avaliações da história do produto, 2 vieram da escala de três — e o
    painel mostrava as seis do mesmo jeito.

    🔑 Não mexo na coleta nem no número guardado (isso é decisão de produto do
    Pedro): mexo em como ele é APRESENTADO, que é onde nasce o engano.

    🪤 Fora dos três valores conhecidos, cai no rótulo numérico: se um dia a
    página do projeto passar a mandar outra coisa, é melhor mostrar o número
    cru do que inventar uma carinha que ninguém clicou.
    """
    try:
        n = int(score)
    except (TypeError, ValueError):
        return "?"
    if (context or "") == "after_project" and n in _NPS_BOTOES_DO_PROJETO:
        return "%s — escolha de 3 opções na página do projeto" % _NPS_BOTOES_DO_PROJETO[n]
    return "%d de 10" % n


def _alerta_nps(row: dict, category: str = "detractor"):
    """TODA nota vira e-mail interno na hora — em thread, best-effort.

    Por que o detrator (16/08/2026): a cliente-20 deu nota 2 às 19:18 e o Pedro só
    viu olhando o painel por acaso. Detrator engajado é a janela de recuperação
    mais curta que existe — ela voltou 1h30 depois com as pranchas de armação;
    um alerta imediato teria posto o Pedro na conversa ANTES.

    🩸 Por que TODAS (31/08/2026): a regra era `if category == "detractor"`, e
    promotor não avisava ninguém. O cliente-13 deu **9 com comentário** em 24/08 e
    o Pedro viu em 31/08 — 7 dias depois. Com 5 respostas em toda a história do
    produto, cada uma perdida é 20% do sinal. E promotor com comentário é a
    matéria-prima da página de cases, que está parada esperando depoimento.

    🪤 Isto é alerta INTERNO (`NOTIFY_EMAIL`), não e-mail de cliente: a regra de
    no máximo 1 e-mail por semana por pessoa não se aplica aqui.
    """
    import threading as _tal

    def _envia():
        try:
            _ctx = ""
            _jid = (row.get("job_id") or "").strip()
            if _jid:
                try:
                    _p = _supa_rows(
                        "GET", "projects",
                        params={"job_id": f"eq.{_jid}",
                                "select": "project_name,status,files_count,file_types"})
                    if _p:
                        _ctx = (f"<br><b>Projeto:</b> {_p[0].get('project_name') or '?'} "
                                f"({_p[0].get('status')}, {_p[0].get('files_count')} arquivo(s)) — "
                                f"https://ai.arq.br/projeto.html?job_id={_jid}")
                except Exception:
                    pass
            _nota = row.get("score")
            # 🩸 02/09: o e-mail dizia "{n}/10" mesmo quando a pessoa tinha
            # clicado numa das TRÊS carinhas da página do projeto. Ver
            # `_nps_rotulo`.
            _rotulo = _nps_rotulo(_nota, row.get("context") or "")
            _com = (row.get("comment") or "").strip()
            if category == "detractor":
                _assunto = f"🔴 {_rotulo} — detrator: {row.get('user_email') or 'sem e-mail'}"
                _fecho = ("Detrator engajado responde melhor a contato pessoal RÁPIDO — "
                          "a janela é de horas, não dias (caso cliente-20, 16/08).")
            elif category == "promoter":
                _assunto = f"🟢 {_rotulo} — promotor: {row.get('user_email') or 'sem e-mail'}"
                _fecho = ("Promotor é a hora de pedir DEPOIMENTO — a página de cases está "
                          "parada esperando um. Se veio comentário, ele já é meio depoimento."
                          if _com else
                          "Promotor sem comentário: vale uma pergunta curta pra saber o que "
                          "funcionou. É barato e vira copy.")
            else:
                _assunto = f"🟡 {_rotulo} — neutro: {row.get('user_email') or 'sem e-mail'}"
                _fecho = ("Neutro é quem quase gostou: o que faltou costuma ser a próxima "
                          "melhoria óbvia do produto.")
            _avisou_nps = _notify_admin(
                _assunto,
                f"<b>Resposta:</b> {_rotulo}<br>"
                f"<b>Cliente:</b> {row.get('user_name') or '?'} ({row.get('user_email') or '?'})<br>"
                f"<b>Comentário:</b> {_com or '(sem comentário)'}"
                f"{_ctx}<br><br>{_fecho}")
            _log_error(f"nps:{category}-alerta",
                       f"resposta={_rotulo!r} score_guardado={_nota} {row.get('user_email')} "
                       f"avisei_admin={_avisou_nps}", _jid)
        except Exception as _e:
            print(f"[nps] alerta de NPS falhou (não-fatal): {_e}")

    _tal.Thread(target=_envia, daemon=True).start()


def _alerta_recado(job_id: str, item_id: str, texto: str, reviewed_by: str = ""):
    """Cliente digitou na tela de revisão → e-mail interno na hora.

    🩸 06/09/2026, o caso que criou isto. Em 02/09 às 16h30 um cliente escreveu
    *"faça a separação dos tipo, cada um para cada item"* (job 17d6e1f2) e
    passaram 4 dias sem ninguém ver. Dois minutos ANTES ele tinha dado nota 7 —
    e ESSA o dono recebeu, porque nota tem alerta desde 16/08. O recado não
    tinha. O sinal mais caro do produto era o único sem campainha.

    E o recado valia mais que a nota: ele estava respondendo a uma instrução do
    nosso próprio motor, que mediu 760,6 m de tubulação, escreveu na descrição
    "subdividir por diâmetro na revisão" e deixou 5 linhas zeradas pro cliente
    preencher. Ele devolveu a tarefa, com razão.

    🪤 Best-effort em thread, como `_alerta_nps`: alerta que falha NÃO pode
    derrubar o salvamento da revisão do cliente.
    🔒 LGPD: o e-mail da pessoa vai no AVISO (o dono precisa saber a quem
    responder) e NÃO vai no `error_log` — em 06/09 achei 19 linhas de log com
    endereço de cliente dentro. Log recebe job_id, que já é opaco.
    """
    import threading as _tr

    def _envia():
        # 🚨 O texto é DIGITADO pelo cliente e vai pro corpo de um e-mail HTML
        # que o dono abre. Sem escape, quem batiza o comentário de
        # `<img src=x onerror=...>` manda marcação pra dentro da caixa dele —
        # a mesma classe do XSS do painel admin consertado hoje (ce7846a).
        import html as _html

        def _e(s):
            return _html.escape(str(s or ""))

        try:
            _ctx, _proj = "", ""
            _jid = (job_id or "").strip()
            if _jid:
                try:
                    _p = _supa_rows("GET", "projects",
                                    params={"job_id": f"eq.{_jid}",
                                            "select": "project_name,status,user_email"})
                    if _p:
                        _proj = _p[0].get("project_name") or "?"
                        _ctx = (f"<br><b>Projeto:</b> {_e(_proj)} ({_e(_p[0].get('status'))}) — "
                                f"https://ai.arq.br/projeto.html?job_id={_e(_jid)}")
                except Exception:
                    pass
            _quem = (reviewed_by or "").strip() or "(sem e-mail na revisão)"
            _avisou = _notify_admin(
                f"💬 Recado de cliente na revisão: {_proj or _jid}",
                f"<b>O cliente escreveu:</b><br>"
                f"<blockquote style='margin:8px 0;padding:8px 12px;"
                f"border-left:3px solid #f59e0b'>{_e(texto[:2000])}</blockquote>"
                f"<b>Quem:</b> {_e(_quem)}<br>"
                f"<b>Item:</b> {_e(item_id)}{_ctx}<br><br>"
                "Recado digitado é o sinal mais raro que este produto tem — em "
                "toda a história foram pouquíssimos. Responder à mão hoje vale "
                "mais que qualquer melhoria de motor desta semana.")
            _log_error("cliente:recado",
                       f"item={item_id} chars={len(texto)} avisei_admin={_avisou}",
                       _jid, severity="warning")
        except Exception as _e:
            print(f"[revisao] alerta de recado falhou (nao-fatal): {_e}")

    _tr.Thread(target=_envia, daemon=True).start()


_NPS_STAGES = ("upload", "tempo", "precisao", "planilha")


@app.post("/api/nps/detailed")
async def submit_nps_detailed(payload: NPSDetailedPayload, request: Request):
    """Feedback detalhado: nota 0-10 (recomendaria) + nota 1-5 por etapa +
    comentário. Autenticado (JWT) — só grava no nome do próprio usuário."""
    user = _get_user_from_request(request)
    if not user or not user.get("id"):
        raise HTTPException(401, "Autenticação requerida")
    if payload.recommend < 0 or payload.recommend > 10:
        raise HTTPException(400, "recommend deve estar entre 0 e 10")
    stages = {}
    for k in _NPS_STAGES:
        v = (payload.stage_ratings or {}).get(k)
        if isinstance(v, (int, float)) and 1 <= int(v) <= 5:
            stages[k] = int(v)
    cat = "promoter" if payload.recommend >= 9 else "passive" if payload.recommend >= 7 else "detractor"
    # OBS: NÃO incluir 'category' — é coluna GERADA (o banco calcula do score).
    # Inserir valor nela faz o insert inteiro falhar.
    row = {
        "user_id": user["id"],
        "user_email": user.get("email", ""),
        "user_name": _name_from_auth(user["id"]),
        "score": int(payload.recommend),
        "comment": (payload.comment or "")[:2000],
        "context": "feedback_detailed",
        "job_id": payload.job_id or "",
        "stage_ratings": stages,
    }
    ok = _supabase_insert("nps_responses", row)
    # 31/08: aqui também era só detrator. Feedback detalhado é o mais rico que
    # existe (nota por etapa + comentário) — perder um promotor deste é pior
    # ainda que perder um NPS simples.
    _alerta_nps(row, cat)
    return {"status": "ok" if ok else "error", "category": cat}


@app.get("/api/nps/check/{user_id}")
def should_show_nps(user_id: str, request: Request):
    """Verifica se o usuário já respondeu NPS recentemente (últimos 60 dias).
    Frontend usa isso pra não mostrar o widget repetidamente.

    Auth: exige JWT do próprio usuário (ou admin) — evita checar/inferir NPS de
    terceiros (auditoria 2026-07-13). O frontend já chama com authFetch."""
    jwt_user = _get_user_from_request(request)
    if not jwt_user:
        raise HTTPException(401, "Autenticação requerida")
    if jwt_user.get("id") != user_id and jwt_user.get("email", "").lower() != ADMIN_EMAIL:
        raise HTTPException(403, "Só é possível checar o próprio NPS")
    import urllib.request, urllib.error, json
    try:
        url = (f"{SUPABASE_URL}/rest/v1/nps_responses"
               f"?user_id=eq.{user_id}&select=created_at"
               f"&order=created_at.desc&limit=1")
        req = urllib.request.Request(url, method='GET')
        req.add_header('apikey', SUPABASE_KEY)
        req.add_header('Authorization', f'Bearer {SUPABASE_SERVICE_ROLE_KEY}')
        resp = urllib.request.urlopen(req, timeout=10)
        rows = json.loads(resp.read().decode('utf-8'))
        if not rows:
            return {"should_show": True, "last_answered": None}
        last = rows[0].get("created_at")
        # 60 dias de cooldown
        try:
            dt = datetime.fromisoformat(last.replace("Z", "+00:00"))
            days_since = (datetime.utcnow().replace(tzinfo=dt.tzinfo) - dt).days
            return {"should_show": days_since >= 60, "last_answered": last, "days_since": days_since}
        except Exception as _ed:
            # 🩸 Data ilegível não é "já respondeu". Ver o bloco abaixo.
            _log_error("nps:check-data-ilegivel", f"user={user_id} valor={last!r} {_ed}",
                       severity="warning")
            return {"should_show": True, "last_answered": last, "indeterminado": True}
    except Exception as e:
        # 🩸 31/08/2026 — ISTO FALHAVA FECHADO, e calado. O dashboard tem o
        # comentário "fail-safe: mostra se API falhar" (dashboard.html), só que
        # a API NUNCA falhava: ela respondia HTTP 200 dizendo `should_show:
        # false`. Do lado do navegador isso é indistinguível de "essa pessoa já
        # respondeu" — a rede de segurança do front estava morta, e nada era
        # gravado pra gente perceber.
        # Com 5 respostas de NPS em toda a história, o erro caro é deixar de
        # perguntar, não perguntar de novo (o cooldown de 60 dias segue valendo
        # em todo caminho que CONSEGUE ler a data).
        _log_error("nps:check-falhou", f"user={user_id} {e}", severity="warning")
        return {"should_show": True, "error": str(e), "indeterminado": True}


@app.get("/api/admin/nps/summary")
def admin_nps_summary(request: Request, days: int = 30):
    """Dashboard admin: resumo agregado de NPS."""
    _require_admin(request)
    import urllib.request, urllib.error, json
    try:
        url = f"{SUPABASE_URL}/rest/v1/rpc/get_nps_summary"
        body = json.dumps({"p_days": days}).encode('utf-8')
        req = urllib.request.Request(url, data=body, method='POST')
        req.add_header('apikey', SUPABASE_KEY)
        req.add_header('Authorization', f'Bearer {SUPABASE_SERVICE_ROLE_KEY}')
        req.add_header('Content-Type', 'application/json')
        resp = urllib.request.urlopen(req, timeout=10)
        rows = json.loads(resp.read().decode('utf-8'))
        return rows[0] if rows else {}
    except Exception as e:
        raise HTTPException(500, f"Erro: {e}")


def _nps_janela_dias(days) -> int:
    """Mesmo clamp pras três rotas do NPS: 1..3650 dias, padrão 30."""
    try:
        return max(1, min(int(days or 30), 3650))
    except (TypeError, ValueError):
        return 30


def _nps_dentro_da_janela(rows, days: int):
    """Só as respostas com `created_at` nos últimos `days` dias.

    🚨 02/09/2026: o seletor da aba NPS só chegava no resumo; a lista e as
    etapas eram a história inteira. Linha sem data (ou com data ilegível)
    NÃO entra e é contada em `sem_data` — não vira "dentro" nem "fora" calada.
    Devolve (dentro, sem_data)."""
    from datetime import datetime, timedelta, timezone
    corte = datetime.now(timezone.utc) - timedelta(days=days)
    dentro, sem_data = [], 0
    for r in rows or []:
        ts = r.get("created_at") if isinstance(r, dict) else None
        try:
            dt = datetime.fromisoformat(str(ts or "").replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
        except (TypeError, ValueError):
            sem_data += 1
            continue
        if dt >= corte:
            dentro.append(r)
    return dentro, sem_data


@app.get("/api/admin/nps/responses")
def admin_nps_responses(request: Request, limit: int = 50, days: int = 30):
    """Dashboard admin: respostas recentes com comentários (insights qualitativos).
    `days` = janela do seletor da aba. A RPC devolve as `limit` mais recentes
    (sem janela) e o corte é feito aqui — com 5 respostas na história (02/09)
    o teto nunca morde; se um dia morder, a lista mostra as mais recentes
    DENTRO da janela, e `limit` vai no JSON pra tela poder dizer isso."""
    _require_admin(request)
    import urllib.request, urllib.error, json
    days = _nps_janela_dias(days)
    try:
        url = f"{SUPABASE_URL}/rest/v1/rpc/list_nps_responses"
        body = json.dumps({"p_limit": limit}).encode('utf-8')
        req = urllib.request.Request(url, data=body, method='POST')
        req.add_header('apikey', SUPABASE_KEY)
        req.add_header('Authorization', f'Bearer {SUPABASE_SERVICE_ROLE_KEY}')
        req.add_header('Content-Type', 'application/json')
        resp = urllib.request.urlopen(req, timeout=10)
        rows = json.loads(resp.read().decode('utf-8'))
    except Exception as e:
        raise HTTPException(500, f"Erro: {e}")
    dentro, sem_data = _nps_dentro_da_janela(rows, days)
    return {"responses": dentro, "window_days": days, "limit": limit, "sem_data": sem_data}


@app.get("/api/admin/nps/stages")
def admin_nps_stages(request: Request, days: int = 30):
    """Médias por etapa do feedback detalhado (upload, tempo, precisão, planilha).
    Lê as respostas e agrega em Python (volume pequeno). `days` = janela do
    seletor da aba (02/09/2026: antes era a história inteira, encostada num
    resumo de 30 dias)."""
    _require_admin(request)
    import urllib.request as _urs
    days = _nps_janela_dias(days)
    try:
        url = (f"{SUPABASE_URL}/rest/v1/nps_responses"
               f"?context=eq.feedback_detailed&select=stage_ratings,score,comment,user_name,created_at"
               f"&order=created_at.desc")
        req = _urs.Request(url, method="GET")
        req.add_header("apikey", SUPABASE_KEY)
        req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        rows = _json.loads(_urs.urlopen(req, timeout=15).read().decode("utf-8"))
    except Exception as e:
        raise HTTPException(500, f"Erro: {e}")
    rows, _sem_data = _nps_dentro_da_janela(rows, days)
    stages = ("upload", "tempo", "precisao", "planilha")
    sums = {k: 0.0 for k in stages}
    counts = {k: 0 for k in stages}
    rec_sum, rec_n = 0.0, 0
    for r in rows:
        sr = r.get("stage_ratings") or {}
        for k in stages:
            v = sr.get(k)
            if isinstance(v, (int, float)):
                sums[k] += v
                counts[k] += 1
        sc = r.get("score")
        if isinstance(sc, (int, float)):
            rec_sum += sc
            rec_n += 1
    avgs = {k: (round(sums[k] / counts[k], 2) if counts[k] else None) for k in stages}
    return {
        "total": len(rows),
        "stages": avgs,
        "counts": counts,
        "recommend_avg": round(rec_sum / rec_n, 2) if rec_n else None,
        "window_days": days,
        "sem_data": _sem_data,
    }


