@app.post("/api/items/{job_id}/review-finalize")
async def finalize_review(job_id: str, request: Request):
    """Marca a revisão inline como concluída e credita cashback (R$0,10 por
    ação, teto R$ 20,00 por projeto).

    Chamado quando o usuário clica "Concluir revisão" na tela de revisão.
    """
    _require_project_owner(request, job_id)  # fix IDOR 2026-07-22 (igual ao review-state)
    try:
        body = await request.json()
    except Exception:
        body = {}
    user_id = body.get("user_id", "")

    # 🔑 A revisão na tela vira APRENDIZADO (09/08). Até hoje revision_feedback
    # só enchia por upload de XLSX revisado — gesto que quase ninguém faz — e
    # estava com 0 linhas, enquanto 54 revisões inline de 5 clientes eram
    # jogadas fora. Agora o mesmo agregador do XLSX roda sobre o par
    # (`edits._antes` × item_items de hoje) e alimenta o painel "Onde a IA erra".
    # 🪤 Em thread e best-effort: NUNCA pode atrasar nem derrubar o "Concluir
    # revisão" do cliente — mesma doutrina do caminho do upload.
    # 📊 GRAVA O CLIQUE, SEMPRE — antes da thread. `revision_feedback` está em 0
    # linhas desde que o produto existe, e até 11/08/2026 não havia como saber
    # POR QUÊ: `projects` só guarda `revisao_aberta_em`/`revisao_aberturas`, que
    # medem a PORTA e não a SAÍDA. Sem isto, "o cliente não concluiu" e "concluiu
    # mas não havia nada pra aprender" produzem o mesmo zero — e em 10/08 eu
    # afirmei o primeiro sobre o Felipe sem ter como saber.
    # Dois clientes entraram na tela em 2 dias: Felipe (6cd52d01) editou a
    # unidade, cliente-79 (4b2db70b) clicou approve. Nenhum dos dois deixou
    # rastro do passo final.
    # 🚨 23/08 (auditoria): aqui era `len(_supa_rest_service(...))`. O retorno é
    # a TUPLA (status, dados), e len(tupla) é SEMPRE 2 — este log vinha dizendo
    # "itens tocados=2" desde que nasceu, em toda revisão concluída. Justo o log
    # criado pra responder POR QUE `revision_feedback` não enche.
    try:
        _st_rl, _rows_rl = _supa_rest_tudo("item_reviews", params={
            "job_id": f"eq.{job_id}", "select": "action"})
        _n_rev_log = len(_rows_rl or []) if _st_rl == 200 else -1
    except Exception:
        _n_rev_log = -1
    _log_error("motor:revisao-concluida",
               f"cliente clicou Concluir · itens tocados={_n_rev_log}", job_id)

    try:
        import threading as _th
        import revision_feedback as _rfi

        def _esteira_com_log():
            # 🪤 A thread é daemon e best-effort: se ela morre, some sem deixar
            # nada. O resultado dela É a resposta da pergunta "por que
            # revision_feedback não enche" — tem que ficar gravado.
            try:
                _gerou = _rfi.processar_revisao_inline(job_id)
                _log_error("motor:revisao-aprendizado",
                           f"gerou_linha={bool(_gerou)}", job_id,
                           severity=("info" if _gerou else "error"))
            except Exception as _e:
                _log_error("motor:revisao-aprendizado",
                           f"ESTEIRA FALHOU: {type(_e).__name__}: {_e}", job_id)

        _th.Thread(target=_esteira_com_log, daemon=True).start()
    except Exception as _erfi:
        print(f"[revision-feedback] inline não iniciou job={job_id}: {_erfi}")
        _log_error("motor:revisao-aprendizado", f"NAO INICIOU: {_erfi}", job_id)

    # Cashback inline removido em 2026-05-13. Política nova:
    # - Revisar itens dentro do site: agradecimento, sem cashback (treinava IA
    #   mas era cognição confusa: R$ 0,10/item raramente atingia o teto).
    # - Cashback fica concentrado em ações de MAIOR sinal pra IA:
    #     * Upload de planilha revisada offline → R$ 30
    #     * Upload de cotação de fornecedor → R$ 10 (max 3 = R$ 30)
    # Total possível por projeto: R$ 60.
    try:
        # Ainda conta reviews pra retornar n_actions ao frontend (pra UI mostrar
        # progresso do usuário), mas não cria evento de cashback.
        _, reviews = _supa_rest_as_user(
            request, "GET",
            f"/item_reviews?job_id=eq.{job_id}&select=item_id&limit=5000",
            timeout=10,
        )
        reviews = reviews or []
        n_actions = len({r["item_id"] for r in reviews if r.get("item_id")})
    except Exception as e:
        n_actions = 0

    return {
        "status": "ok",
        "n_actions": n_actions,
        "credit_cents": 0,
        "credit_brl": 0.0,
        "message": "Obrigado pela revisão — suas correções treinam a IA pro próximo projeto.",
    }


def _marcar_revisao_aberta(job_id: str) -> None:
    """Conta que a tela de revisão deste projeto foi aberta.

    Existe porque o número que mais importa hoje é `revision_feedback` = 0: o
    motor não tem verdade de campo pra aprender. Só que "ninguém revisa" tinha
    duas leituras opostas — não abrem, ou abrem e desistem — e não dava pra
    escolher entre elas. Fica no servidor porque o trackEvent é opt-in de
    cookie: mediria só quem consentiu, e a metade que falta é justamente a que
    a gente não conhece.

    Best-effort de propósito: é medição, não pode custar a tela do cliente."""
    try:
        _supa_rest_service("POST", "rpc/marcar_revisao_aberta", {"p_job_id": job_id})
    except Exception as e:
        print(f"[revisao] não consegui marcar abertura de {job_id}, não crítico: {e}")


@app.get("/api/items/{job_id}/review-state")
def get_review_state(job_id: str, request: Request, marcar: int = 0):
    """Retorna as revisões já feitas nesse job pra restaurar o estado no
    browser quando o user volta pra terminar depois.

    Retorna mapa {item_id: {action, edits, comment, reviewed_at}} com a
    última review de cada item."""
    _require_project_owner(request, job_id)
    import urllib.request, urllib.error, json
    try:
        _, reviews = _supa_rest_as_user(
            request, "GET",
            f"/item_reviews?job_id=eq.{job_id}"
            f"&select=item_id,action,edits,comment,reviewed_at"
            f"&order=reviewed_at.desc&limit=2000",
            timeout=15,
        )
        reviews = reviews or []
        # Manter só a MAIS RECENTE por item (supabase retorna ordenado desc)
        state = {}
        for r in reviews:
            iid = r.get("item_id")
            if iid and iid not in state:
                state[iid] = {
                    "action": r.get("action"),
                    "comment": r.get("comment") or "",
                    "reviewed_at": r.get("reviewed_at"),
                }
        # 🚨 Só conta abertura quem DECLARA que é a tela de revisão (?marcar=1).
        # O comentário antigo aqui dizia "esta rota é chamada SÓ pela tela de
        # revisão" — e era falso: o dashboard chama pra CADA projeto concluído
        # toda vez que "Meus Projetos" renderiza, e o projeto.html também chama.
        # Resultado: em 04/08 havia 54 "aberturas" em 8 projetos, enquanto só 6
        # projetos tinham ação real. O funil da revisão ligado em 03/08 estava
        # medindo render de lista, não gente abrindo a tela.
        # Best-effort e depois do trabalho útil: contador não pode derrubar a
        # tela nem atrasar o carregamento dos itens.
        if marcar == 1:
            _marcar_revisao_aberta(job_id)
        return {"status": "ok", "job_id": job_id, "state": state, "count": len(state)}
    except Exception as e:
        raise HTTPException(500, f"Erro ao buscar state: {e}")


