def _base_normalizada(nome: str) -> str:
    """Nome de arquivo → chave comparável entre envios.

    Tira extensão, acento, pontuação e os sufixos de VERSÃO que o pessoal de
    projeto usa o tempo todo ("Rev B", "R02", "v3", "final", "(1)"). Sem isso,
    'BOMBEIRO 01 Rev B.dxf' e 'BOMBEIRO 01 Rev C.dwg' — que são a mesma prancha
    revisada — não casariam.
    """
    import re as _re2
    import unicodedata as _ud
    s = os.path.splitext(nome or "")[0]
    s = _ud.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii").lower()
    s = _re2.sub(r"[_\-.]+", " ", s)
    s = _re2.sub(r"\(\s*\d+\s*\)", " ", s)                      # "(1)", "(2)"
    s = _re2.sub(r"\b(rev|r|v|ver|versao|version)\s*[.\-]?\s*[a-z0-9]{1,3}\b", " ", s)
    s = _re2.sub(r"\b(final|copia|copy|novo|new|atualizado)\b", " ", s)
    s = _re2.sub(r"[^a-z0-9 ]+", " ", s)
    return _re2.sub(r"\s+", " ", s).strip()


@app.get("/api/projetos/candidatos-anexo")
def projetos_candidatos_anexo(request: Request, horas: int = 72):
    """Projetos recentes do usuário logado, com os nomes dos arquivos que já
    estão neles — pro site poder perguntar "isso não é do projeto X?" ANTES de
    criar um projeto novo.

    Nasceu de um caso real (03/08/2026): um cliente mandou um DWG, e minutos
    depois um DXF, cada um como projeto SEPARADO. Ficam dois quantitativos pela
    metade em vez de um inteiro — e a gente perde a chance de comparar os dois
    formatos do mesmo desenho.

    🔒 Só leitura, e só do dono. Devolve nome de arquivo (que é dele) e nada mais.
    """
    user = _get_user_from_request(request)
    if not user or not user.get("id"):
        raise HTTPException(401, "Autenticação requerida")
    import urllib.parse
    horas = max(1, min(int(horas or 72), 24 * 30))
    try:
        _desde = (datetime.utcnow() - timedelta(hours=horas)).isoformat() + "Z"
        _st, _rows = _supa_rest_service(
            "GET",
            f"projects?user_id=eq.{urllib.parse.quote(str(user['id']))}"
            f"&created_at=gte.{urllib.parse.quote(_desde)}"
            f"&archived_at=is.null"
            f"&select=job_id,project_name,project_type,status,created_at,items_count,desenho_assinatura"
            f"&order=created_at.desc&limit=8")
        if _st != 200 or not isinstance(_rows, list):
            return {"projetos": []}
        out = []
        for r in _rows:
            job = r.get("job_id") or ""
            if not job:
                continue
            try:
                nomes = [n for n in _supabase_storage_list(PRANCHAS_BUCKET, f"{job}/")
                         if n and not n.startswith("checkpoint")]
            except Exception:
                nomes = []
            out.append({
                "job_id": job,
                "project_name": r.get("project_name") or "",
                # 🩸 22/09/2026 (job ee801b82 → f8d8e6d8): o anexo recusado
                # virava projeto novo no tipo PADRÃO do formulário. Com o tipo
                # daqui, o site oferece o projeto novo no tipo do irmão.
                "project_type": r.get("project_type") or "",
                "status": r.get("status"),
                "created_at": r.get("created_at"),
                "items_count": r.get("items_count") or 0,
                "arquivos": nomes,
                # A chave de comparação sai daqui pronta: o site não precisa
                # reimplementar a normalização (e divergir dela com o tempo).
                # 🪤 Base VAZIA fica de fora: "rev.dwg", "v1.dxf" e "(1).pdf"
                # normalizam pra "" (só sufixo de versão), e aí vazio casaria com
                # vazio — TODO projeto viraria candidato de todo arquivo. E base
                # curtíssima ("a", "01") casa por acaso: exige 3 caracteres.
                "bases": sorted({b for b in (_base_normalizada(n) for n in nomes if n)
                                 if len(b) >= 3}),
                # Identidade do desenho — pega o caso que o nome NÃO pega: o
                # cliente renomeou o arquivo. Só o fingerprint e a contagem vão
                # pro navegador; a lista de layers fica no servidor (é o
                # desenho dele, e mandar centenas de nomes por sugestão é peso
                # à toa). A comparação por layers acontece no /comparar-desenho.
                "assinatura": ({"fingerprint": (r.get("desenho_assinatura") or {}).get("fingerprint"),
                                "n_layers": (r.get("desenho_assinatura") or {}).get("n_layers") or 0}
                               if r.get("desenho_assinatura") else None),
            })
        return {"projetos": out}
    except Exception as e:
        _log_error("candidatos-anexo", str(e))
        return {"projetos": []}


class AssinaturaPayload(BaseModel):
    fingerprint: Optional[str] = None
    layers: Optional[list] = None


@app.post("/api/projetos/comparar-desenho")
def comparar_desenho(payload: AssinaturaPayload, request: Request, horas: int = 72):
    """Recebe a assinatura do DXF que o cliente ACABOU de escolher (lida no
    navegador, sem subir o arquivo) e diz se ela bate com algum projeto recente
    dele.

    Fecha o buraco da sugestão por nome: pega o cliente que RENOMEOU o arquivo —
    que é justamente quando ele não lembra que já mandou aquele desenho.

    🔒 A comparação acontece AQUI, não no navegador: a lista de layers do
    projeto antigo não precisa sair do servidor.
    """
    user = _get_user_from_request(request)
    if not user or not user.get("id"):
        raise HTTPException(401, "Autenticação requerida")
    import urllib.parse
    nova = {"fingerprint": (payload.fingerprint or None),
            "layers": [str(x) for x in (payload.layers or [])][:400]}
    if not nova["fingerprint"] and len(nova["layers"]) < 5:
        return {"achou": None}     # sinal fraco demais pra sugerir
    try:
        from dxf_assinatura import semelhanca
        _desde = (datetime.utcnow() - timedelta(hours=max(1, min(int(horas or 72), 720)))).isoformat() + "Z"
        _st, _rows = _supa_rest_service(
            "GET",
            f"projects?user_id=eq.{urllib.parse.quote(str(user['id']))}"
            f"&created_at=gte.{urllib.parse.quote(_desde)}"
            f"&archived_at=is.null&desenho_assinatura=not.is.null"
            f"&select=job_id,project_name,project_type,created_at,items_count,desenho_assinatura"
            f"&order=created_at.desc&limit=8")
        if _st != 200 or not isinstance(_rows, list):
            return {"achou": None}
        for r in _rows:
            v = semelhanca(nova, r.get("desenho_assinatura") or {})
            if v.get("mesmo_desenho"):
                return {"achou": {
                    "job_id": r.get("job_id"),
                    "project_name": r.get("project_name") or "",
                    # o mesmo tipo que o /candidatos-anexo devolve (ver lá)
                    "project_type": r.get("project_type") or "",
                    "created_at": r.get("created_at"),
                    "items_count": r.get("items_count") or 0,
                    "motivo": v.get("motivo"),
                    "forca": "identificador" if v.get("jaccard") == 1.0 else "layers",
                }}
        return {"achou": None}
    except Exception as e:
        _log_error("comparar-desenho", str(e))
        return {"achou": None}      # sugestão é acessório: erro nunca atrapalha


