@app.post("/api/admin/cleanup-old-projects")
def cleanup_old_projects(request: Request):
    """Deleta arquivos originais + planilha de projetos com 90+ dias.
    Marca projeto como archived=true pra preservar histórico no DB.

    Autenticação: header 'X-Cleanup-Secret' deve bater com env var
    CLEANUP_SECRET. Se CLEANUP_SECRET não estiver setado no Render, o
    endpoint responde 503.

    Chamado por GitHub Action cron diariamente."""
    # Auth
    provided_secret = request.headers.get("X-Cleanup-Secret", "")
    if not CLEANUP_SECRET:
        raise HTTPException(503, "CLEANUP_SECRET não configurado no ambiente")
    if provided_secret != CLEANUP_SECRET:
        raise HTTPException(401, "Secret inválido")

    # Query days pode customizar pra testes (default 90)
    import urllib.request, json as _j
    try:
        days = int(request.query_params.get("days", CLEANUP_RETENTION_DAYS))
    except Exception:
        days = CLEANUP_RETENTION_DAYS

    # 1) Lista projetos elegíveis via RPC
    try:
        url = f"{SUPABASE_URL}/rest/v1/rpc/list_expired_projects"
        body = _j.dumps({"p_days": days}).encode("utf-8")
        req = urllib.request.Request(url, data=body, method="POST")
        req.add_header("apikey", SUPABASE_KEY)
        req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        req.add_header("Content-Type", "application/json")
        resp = urllib.request.urlopen(req, timeout=15)
        expired = _j.loads(resp.read().decode("utf-8"))
    except Exception as e:
        raise HTTPException(500, f"Erro ao buscar projetos expirados: {e}")

    stats = {
        "days_threshold": days,
        "total_expired": len(expired),
        "archived": 0,
        "files_deleted": 0,
        "errors": [],
        "jobs": [],
    }

    # 2) Pra cada projeto: deletar arquivos do Storage + marcar archived
    for proj in expired:
        job_id = proj.get("job_id")
        if not job_id:
            continue

        # 🧪 A CONTA DE SMOKE É FIXTURE PERMANENTE, NÃO DADO ENVELHECÍVEL
        # (20/08/2026). O projeto 0de29633 (zarelalopes+smoke@gmail.com, criado
        # 22/05) cruzou os 90 dias na madrugada e foi arquivado — a listagem
        # filtra arquivado, o nível 2 do smoke morreu em "0 projetos", e o
        # teste de produção ficou VERMELHO num código são. Passou 19/08 21:45 e
        # falhou 20/08 06:39 no MESMO commit; foi assim que se achou.
        # Sem esta trava, o conserto de hoje re-quebra em novembro, quando o
        # próximo projeto de teste envelhecer.
        # 🚨 23/08 (auditoria): esta trava tinha voltado a falhar ABERTA. Com
        # _supa_rows, erro de leitura devolve [] → _mail_own = "" → o cleanup
        # NÃO reconhece a fixture e apaga o projeto do smoke. É exatamente o
        # incidente de 20/08 que o comentário acima jura que não pode repetir.
        # Agora: na dúvida, PULA (não apagar é sempre reversível; apagar não).
        _st_own, _own = _supa_rest_service(
            "GET", "projects",
            params={"job_id": f"eq.{job_id}", "select": "user_email"})
        if _st_own != 200:
            stats["jobs"].append({"job_id": job_id,
                                  "skip": f"não consegui ler o dono (HTTP {_st_own}) — não apago no escuro"})
            continue
        _mail_own = str(((_own or [{}]) or [{}])[0].get("user_email") or "")
        if "+smoke@" in _mail_own.lower():
            stats["jobs"].append({"job_id": job_id, "skip": "conta de smoke (fixture)"})
            continue

        # 2a) Arquivos originais (bucket aiarq-pranchas/{job_id}/)
        listou, pranchas_list = _supabase_storage_list_ou_falha(PRANCHAS_BUCKET, f"{job_id}/")
        files_ok = 0
        falhas = 0 if listou else 1     # não listei = não sei o que ficou pra trás
        for obj in pranchas_list:
            # list retorna "nome.pdf" (sem prefix). Delete precisa do path completo.
            path = f"{job_id}/{obj}"
            if _supabase_storage_delete(PRANCHAS_BUCKET, path):
                files_ok += 1
            else:
                falhas += 1

        # 2b) Planilha (bucket aiarq-planilhas/{job_id}.xlsx)
        if _supabase_storage_delete(PLANILHAS_BUCKET, f"{job_id}.xlsx"):
            files_ok += 1
        else:
            falhas += 1

        # 🚨 2b-bis) ARQUIVAR SÓ QUANDO APAGOU TUDO.
        # Esta era a causa raiz do lixo de 65,7 MB: o projeto era marcado como
        # arquivado mesmo com a exclusão falhando, e a RPC `list_expired_projects`
        # filtra `archived = false` — ou seja, o cron NUNCA MAIS volta nele. Um
        # erro de uma noite virava resíduo permanente. Agora o projeto fica na
        # fila e a próxima rodada tenta de novo; o rastro fica no error_log
        # (`storage:delete-falhou`) e aqui no cleanup_log.
        if falhas:
            stats["errors"].append({"job_id": job_id,
                                    "error": f"{falhas} exclusão(ões) falharam — NÃO arquivei, "
                                             f"o projeto volta na fila amanhã"})
            stats["jobs"].append({"job_id": job_id, "files_deleted": files_ok,
                                  "skip": f"{falhas} falha(s) — fica na fila"})
            stats["files_deleted"] += files_ok
            continue

        # 2c) Marcar projeto como archived
        try:
            mark_url = f"{SUPABASE_URL}/rest/v1/rpc/mark_project_archived"
            mark_body = _j.dumps({"p_job_id": job_id}).encode("utf-8")
            mark_req = urllib.request.Request(mark_url, data=mark_body, method="POST")
            mark_req.add_header("apikey", SUPABASE_KEY)
            mark_req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
            mark_req.add_header("Content-Type", "application/json")
            urllib.request.urlopen(mark_req, timeout=10)
            stats["archived"] += 1
            stats["files_deleted"] += files_ok
            stats["jobs"].append({"job_id": job_id, "files_deleted": files_ok})
        except Exception as e:
            stats["errors"].append({"job_id": job_id, "error": str(e)[:200]})

    # ── 3) VARREDURA DE RESGATE ────────────────────────────────────────────
    # 🩸 O passo 2 só alcança projeto NÃO arquivado. Todo arquivo que ficou pra
    # trás numa noite em que a exclusão falhou some da vista pra sempre, porque
    # o projeto já foi marcado. Medido em 07/09: 31 arquivos, 18 projetos,
    # 65,7 MB, com mais de 90 dias — promessa de privacidade descumprida em
    # silêncio. A RPC olha o STORAGE (não a lista de projetos) e devolve
    # exatamente o que sobrou; fica vazia sozinha quando não há mais nada.
    stats["resgatados"] = 0
    stats["resgate_falhou"] = 0
    # 🚨 A VARREDURA NÃO ACEITA `?days` — SEMPRE a retenção configurada.
    # `days` existe pra ajustar o passo 2 em teste. Aqui é diferente: o passo 3
    # é uma varredura de MASSA, sem dono lido e sem projeto pra pular, e o
    # parâmetro chegava CRU na RPC. Medido em 07/09 no banco de produção:
    #   list_expired_storage_leftovers(90)  →   31 arquivos (o resíduo real)
    #   list_expired_storage_leftovers(0)   → 1000 arquivos (o teto), de 1.282
    # Ou seja, um `?days=0` apagaria o CAD de praticamente todos os clientes
    # numa chamada. A retenção é uma PROMESSA, não um botão de URL.
    _dias_resgate = CLEANUP_RETENTION_DAYS
    try:
        _url_r = f"{SUPABASE_URL}/rest/v1/rpc/list_expired_storage_leftovers"
        _body_r = _j.dumps({"p_days": _dias_resgate, "p_limit": 200}).encode("utf-8")
        _req_r = urllib.request.Request(_url_r, data=_body_r, method="POST")
        _req_r.add_header("apikey", SUPABASE_KEY)
        _req_r.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        _req_r.add_header("Content-Type", "application/json")
        _sobras = _j.loads(urllib.request.urlopen(_req_r, timeout=20).read().decode("utf-8"))
    except Exception as _e:
        _sobras = None
        _log_error("cleanup:resgate-nao-listou",
                   "%s — não deu pra ver o que sobrou no storage" % type(_e).__name__,
                   None, severity="warning")
    for _o in (_sobras or []):
        _b = str(_o.get("bucket_id") or "")
        _n = str(_o.get("object_name") or "")
        if _b not in (PRANCHAS_BUCKET, PLANILHAS_BUCKET) or not _n:
            continue        # a RPC já filtra, mas o cliente não confia de graça
        if _supabase_storage_delete(_b, _n):
            stats["resgatados"] += 1
        else:
            stats["resgate_falhou"] += 1
    # sem teto silencioso: o que passou de 200 fica escrito e sai amanhã
    if _sobras is not None and len(_sobras) >= 200:
        _log_error("cleanup:resgate-lote-cheio",
                   "200 sobras nesta rodada — ainda há mais pra apagar amanhã",
                   None, severity="warning")
    if stats["resgatados"] or stats["resgate_falhou"]:
        _supa_log(f"CLEANUP resgate: {stats['resgatados']} apagados, "
                  f"{stats['resgate_falhou']} falharam")

    _supa_log(f"CLEANUP archived={stats['archived']} files={stats['files_deleted']} "
              f"errors={len(stats['errors'])}")
    print(f"[cleanup] {stats['archived']} projetos arquivados, "
          f"{stats['files_deleted']} arquivos deletados, "
          f"{len(stats['errors'])} erros")

    # Registra execução no cleanup_log pra monitoramento no admin
    _supabase_insert("cleanup_log", {
        "days_threshold": days,
        "total_expired": stats["total_expired"],
        "archived": stats["archived"],
        "files_deleted": stats["files_deleted"],
        "errors_count": len(stats["errors"]),
        # o resgate entra no `details` porque `cleanup_log` não tem coluna
        # própria — e sem isso a rodada que só resgatou pareceria uma noite
        # em que nada aconteceu.
        "details": {"jobs": stats["jobs"][:50],
                    "resgatados": stats["resgatados"],
                    "resgate_falhou": stats["resgate_falhou"]},
    })

    return stats


@app.get("/api/admin/cleanup-log")
def admin_cleanup_log(request: Request, limit: int = 30):
    """Retorna últimas execuções do cleanup pra dashboard admin."""
    _require_admin(request)
    import urllib.request, json as _j
    try:
        url = f"{SUPABASE_URL}/rest/v1/rpc/list_cleanup_runs"
        body = _j.dumps({"p_limit": limit}).encode("utf-8")
        req = urllib.request.Request(url, data=body, method="POST")
        req.add_header("apikey", SUPABASE_KEY)
        req.add_header("Authorization", f"Bearer {SUPABASE_SERVICE_ROLE_KEY}")
        req.add_header("Content-Type", "application/json")
        resp = urllib.request.urlopen(req, timeout=10)
        return {"runs": _j.loads(resp.read().decode("utf-8"))}
    except Exception as e:
        raise HTTPException(500, f"Erro: {e}")


